-- 정리 노트·퀴즈·모범 답안·추가 표현 (scripts/gen_notes.py로 생성)
update public.ielts_days set note = '{"summary": "교육은 Writing Task 2 단골 주제예요. 문제는 대부분 세 갈래로 나와요: ① 대학은 무료여야 하나? ② 학교는 이론과 실용 기술 중 무엇을 가르쳐야 하나? ③ 모두가 대학에 가야 하나? 오늘 표현 5개면 세 유형 모두 첫 문장을 쓸 수 있어요.", "items": [{"en": "compulsory education", "ko": "의무 교육", "usage": "셀 수 없는 명사라 a/an을 붙이지 않아요. 짝꿍 동사는 last(기간), finish, complete.", "examples": [{"type": "w", "text": "Compulsory education should include basic financial skills."}, {"type": "s", "text": "In Korea, compulsory education lasts nine years."}], "mistake": "✗ a compulsory education / ✗ obligatory education (뜻은 통하지만 어색해요)", "pron": {"word": "compulsory", "ipa": "/kəmˈpʌlsəri/", "youglish": "https://youglish.com/pronounce/compulsory%20education/english", "dict": "https://dictionary.cambridge.org/dictionary/english/compulsory"}}, {"en": "higher education", "ko": "고등 교육 (대학 이상)", "usage": "역시 셀 수 없는 명사예요. access to higher education, go on to higher education으로 자주 써요.", "examples": [{"type": "w", "text": "Governments should make higher education available to everyone."}, {"type": "s", "text": "Most of my friends went on to higher education after high school."}], "mistake": "✗ high education → 반드시 비교급 higher로 써요.", "pron": {"word": "education", "ipa": "/ˌedʒuˈkeɪʃn/", "youglish": "https://youglish.com/pronounce/higher%20education/english", "dict": "https://dictionary.cambridge.org/dictionary/english/education"}}, {"en": "get a degree in ~", "ko": "~ 학위를 따다", "usage": "전공 앞에는 in을 써요. 더 격식 있게는 obtain a degree in.", "examples": [{"type": "w", "text": "Getting a degree in engineering does not guarantee a good job."}, {"type": "s", "text": "I got a degree in computer science, but I learned most things at work."}], "mistake": "✗ a degree of business → in business / ✗ graduate university → graduate from university", "pron": {"word": "degree", "ipa": "/dɪˈɡriː/", "youglish": "https://youglish.com/pronounce/get%20a%20degree%20in/english", "dict": "https://dictionary.cambridge.org/dictionary/english/degree"}}, {"en": "acquire practical skills", "ko": "실용적 기술을 익히다", "usage": "learn보다 격식 있는 말이라 Writing에 잘 맞아요. Speaking에서는 pick up 정도가 자연스러워요.", "examples": [{"type": "w", "text": "Students should acquire practical skills that employers value."}, {"type": "s", "text": "I picked up a lot of practical skills at my first job."}], "mistake": "skill은 셀 수 있는 명사예요. ✗ acquire practical skill → skills 또는 a practical skill", "pron": {"word": "acquire", "ipa": "/əˈkwaɪə(r)/", "youglish": "https://youglish.com/pronounce/acquire%20practical%20skills/english", "dict": "https://dictionary.cambridge.org/dictionary/english/acquire"}}, {"en": "tuition fees", "ko": "등록금", "usage": "영국식은 보통 복수형 fees로 써요. 짝꿍: pay / raise / cut tuition fees, high tuition fees.", "examples": [{"type": "w", "text": "High tuition fees prevent many talented students from going to university."}, {"type": "s", "text": "My parents paid my tuition fees, so I didn''t have a student loan."}], "mistake": "✗ Tuition fee is expensive. → Tuition fees are high. (fees는 expensive보다 high와 잘 어울려요)", "pron": {"word": "tuition", "ipa": "/tjuˈɪʃn/", "youglish": "https://youglish.com/pronounce/tuition%20fees/english", "dict": "https://dictionary.cambridge.org/dictionary/english/tuition"}}], "frame_tip": "Task 2 서론의 첫 문장으로 양쪽 의견을 보여줄 때 써요. “To what extent do you agree?” 문제라면 바로 다음 문장에 In my opinion, ...으로 내 입장을 꼭 써야 해요. 양쪽만 소개하고 끝나면 감점이에요.", "extra": null}'::jsonb, quiz = '[{"q": "In Korea, ______ ______ lasts nine years. (의무 교육)", "a": "compulsory education"}, {"q": "She got a degree ___ business.", "a": "in"}, {"q": "틀린 곳 고치기: “Tuition fee is very expensive in my country.”", "a": "Tuition *fees are* very *high* in my country."}, {"q": "Writing 스타일로 바꾸기: “Students should learn useful skills for work.”", "a": "Students should *acquire practical skills* for work."}]'::jsonb, model = '{"text": "Some people believe that higher education should be free for everyone, while others argue that students should pay tuition fees. In my opinion, university should be free because high tuition fees stop many talented young people from getting a degree. However, students should also acquire practical skills so that society benefits from free education.", "why": ["문장 틀로 양쪽 의견을 보여준 뒤 In my opinion으로 입장을 분명히 밝혔어요.", "이유를 because 한 개로 구체적으로 댔어요.", "오늘 표현을 4개 썼어요. 어려운 단어 없이 정확하게 쓰는 것이 목표예요."]}'::jsonb, extras = '{"phrases": [{"en": "drop out of school", "ko": "학교를 중퇴하다", "example": "Some students drop out of school because they need to earn money.", "youglish": "https://youglish.com/pronounce/drop%20out%20of%20school/english"}, {"en": "a well-rounded education", "ko": "균형 잡힌 교육", "example": "Sport and music are part of a well-rounded education.", "youglish": "https://youglish.com/pronounce/a%20well-rounded%20education/english"}, {"en": "lifelong learning", "ko": "평생 학습", "example": "Lifelong learning is essential in a fast-changing job market.", "youglish": "https://youglish.com/pronounce/lifelong%20learning/english"}, {"en": "put pressure on ~", "ko": "~에게 압박을 주다", "example": "Many parents put too much pressure on their children to get good grades.", "youglish": "https://youglish.com/pronounce/put%20pressure%20on/english"}, {"en": "apply for a scholarship", "ko": "장학금을 신청하다", "example": "I applied for a scholarship to study abroad.", "youglish": "https://youglish.com/pronounce/apply%20for%20a%20scholarship/english"}], "words": [{"en": "curriculum", "ipa": "/kəˈrɪkjələm/", "ko": "교육과정", "example": "The school curriculum should include more practical subjects.", "youglish": "https://youglish.com/pronounce/curriculum/english", "dict": "https://dictionary.cambridge.org/dictionary/english/curriculum"}, {"en": "graduate", "ipa": "/ˈɡrædʒuət/", "ko": "졸업생 (명사)", "example": "Many graduates struggle to find a job in their field.", "youglish": "https://youglish.com/pronounce/graduate/english", "dict": "https://dictionary.cambridge.org/dictionary/english/graduate"}, {"en": "literacy", "ipa": "/ˈlɪtərəsi/", "ko": "읽고 쓰는 능력", "example": "Computer literacy is as important as reading today.", "youglish": "https://youglish.com/pronounce/literacy/english", "dict": "https://dictionary.cambridge.org/dictionary/english/literacy"}, {"en": "vocational", "ipa": "/vəʊˈkeɪʃənl/", "ko": "직업의, 직업 교육의", "example": "Vocational courses prepare students for specific jobs.", "youglish": "https://youglish.com/pronounce/vocational/english", "dict": "https://dictionary.cambridge.org/dictionary/english/vocational"}, {"en": "academic", "ipa": "/ˌækəˈdemɪk/", "ko": "학문의, 학업의", "example": "Some students are good at academic subjects, while others prefer hands-on work.", "youglish": "https://youglish.com/pronounce/academic/english", "dict": "https://dictionary.cambridge.org/dictionary/english/academic"}]}'::jsonb, todos = '[{"kind": "blog", "text": "교육 어휘 목록(약 75개) 훑고, 빈칸 연습문제 첫 세트 풀기 (발음 오디오도 있어요)", "url": "https://ieltsliz.com/education-vocabulary-school-and-university/", "minutes": 15}]'::jsonb where day = '2026-11-24';
update public.ielts_days set note = '{"summary": "온라인 vs 교실 수업은 Task 2 ''장단점(advantages and disadvantages)'' 유형으로 자주 나와요. 온라인의 장점은 유연성과 속도, 교실의 장점은 대면 소통과 집중력이에요. 양쪽 표현을 하나씩 챙겨두면 어느 쪽 입장이든 쓸 수 있어요.", "items": [{"en": "online learning", "ko": "온라인 학습", "usage": "셀 수 없는 명사예요. online courses / online classes도 같이 알아두세요.", "examples": [{"type": "w", "text": "Online learning allows people to study while they work."}, {"type": "s", "text": "I tried online learning during the pandemic, and it was quite convenient."}], "mistake": "✗ an online learning / ✗ on-line study (예전 표기)", "pron": {"word": "learning", "ipa": "/ˈlɜːnɪŋ/", "youglish": "https://youglish.com/pronounce/online%20learning/english", "dict": "https://dictionary.cambridge.org/dictionary/english/learning"}}, {"en": "academic performance", "ko": "학업 성적", "usage": "짝꿍: improve / affect academic performance. 구어에서는 그냥 grades도 많이 써요.", "examples": [{"type": "w", "text": "A lack of sleep can affect students'' academic performance."}, {"type": "s", "text": "My grades got better when I started studying in the morning."}], "mistake": "✗ academic score performance / ✗ academic perform (명사 performance로)", "pron": {"word": "academic", "ipa": "/ˌækəˈdemɪk/", "youglish": "https://youglish.com/pronounce/academic%20performance/english", "dict": "https://dictionary.cambridge.org/dictionary/english/academic"}}, {"en": "learn at their own pace", "ko": "자기 속도로 배우다", "usage": "주어에 맞춰 my / their / his own pace로 바꿔요.", "examples": [{"type": "w", "text": "Online courses allow students to learn at their own pace."}, {"type": "s", "text": "I like language apps because I can learn at my own pace."}], "mistake": "✗ learn in their own speed → at their own pace", "pron": {"word": "pace", "ipa": "/peɪs/", "youglish": "https://youglish.com/pronounce/at%20their%20own%20pace/english", "dict": "https://dictionary.cambridge.org/dictionary/english/pace"}}, {"en": "face-to-face interaction", "ko": "대면 소통", "usage": "명사 앞에서 형용사로 쓸 땐 하이픈을 붙여요. face-to-face classes / meetings.", "examples": [{"type": "w", "text": "Children need face-to-face interaction with teachers and classmates."}, {"type": "s", "text": "I prefer face-to-face meetings because it''s easier to ask questions."}], "mistake": "✗ face to face interaction (하이픈 빠짐) / 부사로 쓸 땐 하이픈 없이: We met face to face.", "pron": {"word": "interaction", "ipa": "/ˌɪntərˈækʃn/", "youglish": "https://youglish.com/pronounce/face-to-face%20interaction/english", "dict": "https://dictionary.cambridge.org/dictionary/english/interaction"}}, {"en": "well-qualified teachers", "ko": "자격을 잘 갖춘 교사", "usage": "well-qualified / highly qualified 둘 다 OK. 하이픈 주의.", "examples": [{"type": "w", "text": "Rural schools often struggle to hire well-qualified teachers."}, {"type": "s", "text": "My high school had some really well-qualified teachers."}], "mistake": "✗ well-qualificated / ✗ qualify teachers → qualified", "pron": {"word": "qualified", "ipa": "/ˈkwɒlɪfaɪd/", "youglish": "https://youglish.com/pronounce/well-qualified/english", "dict": "https://dictionary.cambridge.org/dictionary/english/qualified"}}], "frame_tip": "의견 + 이유를 한 문장에 담는 가장 기본 틀이에요. because 뒤에는 ''왜''를 구체적으로 써야 Band 5 이상이에요. 주의: In my opinion과 I think를 같이 쓰면 중복이에요.", "extra": null}'::jsonb, quiz = '[{"q": "Many apps let users learn at their own ______.", "a": "pace"}, {"q": "Online classes cannot replace ______-___-______ interaction.", "a": "face-to-face"}, {"q": "틀린 곳 고치기: “In my opinion, I think online learning is better.”", "a": "*In my opinion* 또는 *I think* 중 하나만 써요."}, {"q": "A lack of sleep can affect students'' ______ ______. (학업 성적)", "a": "academic performance"}]'::jsonb, model = '{"text": "In my opinion, classroom learning is better than online learning because students need face-to-face interaction. In a classroom, well-qualified teachers can see when students do not understand and help them immediately. Online learning is useful for adults who want to learn at their own pace, but it is not ideal for children.", "why": ["입장 → 이유(because) → 구체적 상황 → 반대쪽 인정(but) 순서예요.", "반대쪽 장점을 인정하면 논리가 균형 잡혀 보여요.", "오늘 표현 4개를 자연스럽게 넣었어요."]}'::jsonb, extras = '{"phrases": [{"en": "pay attention in class", "ko": "수업에 집중하다", "example": "It is harder for children to pay attention in class when they are tired.", "youglish": "https://youglish.com/pronounce/pay%20attention%20in%20class/english"}, {"en": "at any time", "ko": "언제든지", "example": "With online courses, students can study at any time.", "youglish": "https://youglish.com/pronounce/at%20any%20time/english"}, {"en": "ask questions", "ko": "질문하다", "example": "In a classroom, students can ask questions immediately.", "youglish": "https://youglish.com/pronounce/ask%20questions/english"}, {"en": "study from home", "ko": "집에서 공부하다", "example": "Studying from home saves time and money.", "youglish": "https://youglish.com/pronounce/study%20from%20home/english"}, {"en": "motivate students to ~", "ko": "학생들이 ~하도록 동기를 주다", "example": "Good teachers motivate students to work harder.", "youglish": "https://youglish.com/pronounce/motivate%20students%20to/english"}], "words": [{"en": "flexible", "ipa": "/ˈfleksəbl/", "ko": "유연한", "example": "Online learning is more flexible than classroom learning.", "youglish": "https://youglish.com/pronounce/flexible/english", "dict": "https://dictionary.cambridge.org/dictionary/english/flexible"}, {"en": "distraction", "ipa": "/dɪˈstrækʃn/", "ko": "방해 요소, 주의를 흩뜨리는 것", "example": "Phones are a major distraction for students.", "youglish": "https://youglish.com/pronounce/distraction/english", "dict": "https://dictionary.cambridge.org/dictionary/english/distraction"}, {"en": "discipline", "ipa": "/ˈdɪsəplɪn/", "ko": "규율, 자제력", "example": "Studying online requires a lot of self-discipline.", "youglish": "https://youglish.com/pronounce/discipline/english", "dict": "https://dictionary.cambridge.org/dictionary/english/discipline"}, {"en": "isolated", "ipa": "/ˈaɪsəleɪtɪd/", "ko": "고립된", "example": "Some online learners feel isolated from other students.", "youglish": "https://youglish.com/pronounce/isolated/english", "dict": "https://dictionary.cambridge.org/dictionary/english/isolated"}, {"en": "concentrate", "ipa": "/ˈkɒnsntreɪt/", "ko": "집중하다", "example": "I can''t concentrate when there is a lot of noise.", "youglish": "https://youglish.com/pronounce/concentrate/english", "dict": "https://dictionary.cambridge.org/dictionary/english/concentrate"}]}'::jsonb, todos = '[{"kind": "blog", "text": "같은 페이지의 남은 빈칸 연습문제 풀기 + 남녀공학 주제 영상 보기", "url": "https://ieltsliz.com/education-vocabulary-school-and-university/", "minutes": 15}]'::jsonb where day = '2026-11-25';
update public.ielts_days set note = '{"summary": "일·직업은 Speaking Part 1의 첫 질문(“Do you work or study?”)이자 Task 2 주제(돈 vs 만족, 재택근무)예요. 오늘 표현은 말하기와 쓰기 양쪽에 바로 쓰여요.", "items": [{"en": "job satisfaction", "ko": "직업 만족도", "usage": "셀 수 없는 명사. high / low job satisfaction, get job satisfaction from ~.", "examples": [{"type": "w", "text": "For many young people, job satisfaction is more important than a high salary."}, {"type": "s", "text": "I get a lot of job satisfaction from helping customers."}], "mistake": "✗ a job satisfaction / ✗ job satisfy", "pron": {"word": "satisfaction", "ipa": "/ˌsætɪsˈfækʃn/", "youglish": "https://youglish.com/pronounce/job%20satisfaction/english", "dict": "https://dictionary.cambridge.org/dictionary/english/satisfaction"}}, {"en": "work-life balance", "ko": "일과 삶의 균형", "usage": "a good / healthy work-life balance, maintain / achieve a work-life balance.", "examples": [{"type": "w", "text": "Remote work can help employees maintain a healthy work-life balance."}, {"type": "s", "text": "My work-life balance isn''t great at the moment because I often finish late."}], "mistake": "✗ work and life balance (어색해요)", "pron": {"word": "balance", "ipa": "/ˈbæləns/", "youglish": "https://youglish.com/pronounce/work-life%20balance/english", "dict": "https://dictionary.cambridge.org/dictionary/english/balance"}}, {"en": "work long hours", "ko": "장시간 일하다", "usage": "long hours 앞에 for를 붙이지 않아요.", "examples": [{"type": "w", "text": "People who work long hours often suffer from stress."}, {"type": "s", "text": "I sometimes work long hours, especially at the end of the month."}], "mistake": "✗ work for long time → work long hours / work for a long time", "pron": {"word": "hours", "ipa": "/ˈaʊəz/", "youglish": "https://youglish.com/pronounce/work%20long%20hours/english", "dict": "https://dictionary.cambridge.org/dictionary/english/hours"}}, {"en": "career prospects", "ko": "경력 전망, 승진 가능성", "usage": "항상 복수형이에요. good / poor career prospects, improve your career prospects.", "examples": [{"type": "w", "text": "Speaking a second language can improve your career prospects."}, {"type": "s", "text": "I chose this company because the career prospects are good."}], "mistake": "✗ The career prospect is good. → The career prospects are good.", "pron": {"word": "prospects", "ipa": "/ˈprɒspekts/", "youglish": "https://youglish.com/pronounce/career%20prospects/english", "dict": "https://dictionary.cambridge.org/dictionary/english/prospects"}}, {"en": "earn a good salary", "ko": "좋은 급여를 받다", "usage": "get보다 earn이 자연스러워요. salary는 월급·연봉, wage는 시급·주급이에요.", "examples": [{"type": "w", "text": "Doctors earn a good salary, but they also work long hours."}, {"type": "s", "text": "I don''t earn a huge salary, but I really enjoy my job."}], "mistake": "✗ receive a good salary (어색) / salary와 wage 혼동", "pron": {"word": "salary", "ipa": "/ˈsæləri/", "youglish": "https://youglish.com/pronounce/earn%20a%20good%20salary/english", "dict": "https://dictionary.cambridge.org/dictionary/english/salary"}}], "frame_tip": "장단점 문제에서 본론 문단 첫 문장으로 써요. 반대쪽은 One disadvantage of ... is that ... 주의: of 뒤에는 명사나 -ing가 와요.", "extra": null}'::jsonb, quiz = '[{"q": "Remote work helps people keep a good ______-______ ______.", "a": "work-life balance"}, {"q": "Learning English can improve your career ______.", "a": "prospects"}, {"q": "틀린 곳 고치기: “One advantage of work from home is that I save time.”", "a": "One advantage of *working* from home is ..."}, {"q": "Many nurses ______ long hours.", "a": "work"}]'::jsonb, model = '{"text": "Q: Do you work or study?\nA: I work. I''m in IT, at a small company in Seoul. I really enjoy it because I get a lot of job satisfaction from building things that people actually use. To be honest, I sometimes work long hours, but the career prospects are good, so I don''t mind.", "why": ["Part 1은 질문에 바로 답(I work)하고 시작해요.", "무슨 일 → 좋은 점(이유) → 솔직한 단점 순으로 3~4문장, 20~30초가 적당해요.", "To be honest 같은 연결 표현이 말을 자연스럽게 만들어요."]}'::jsonb, extras = '{"phrases": [{"en": "work from home", "ko": "재택근무를 하다", "example": "Many companies now allow employees to work from home two days a week.", "youglish": "https://youglish.com/pronounce/work%20from%20home/english"}, {"en": "a nine-to-five job", "ko": "평범한 사무직 (9시~5시 일)", "example": "I don''t want a nine-to-five job; I prefer flexible hours.", "youglish": "https://youglish.com/pronounce/a%20nine-to-five%20job/english"}, {"en": "get promoted", "ko": "승진하다", "example": "She got promoted after only two years.", "youglish": "https://youglish.com/pronounce/get%20promoted/english"}, {"en": "be under a lot of pressure", "ko": "압박을 많이 받다", "example": "Doctors are often under a lot of pressure at work.", "youglish": "https://youglish.com/pronounce/be%20under%20a%20lot%20of%20pressure/english"}, {"en": "change careers", "ko": "직업을 바꾸다", "example": "More people are changing careers in their thirties and forties.", "youglish": "https://youglish.com/pronounce/change%20careers/english"}], "words": [{"en": "colleague", "ipa": "/ˈkɒliːɡ/", "ko": "직장 동료", "example": "I get on well with most of my colleagues.", "youglish": "https://youglish.com/pronounce/colleague/english", "dict": "https://dictionary.cambridge.org/dictionary/english/colleague"}, {"en": "employer", "ipa": "/ɪmˈplɔɪə(r)/", "ko": "고용주", "example": "Employers value communication skills.", "youglish": "https://youglish.com/pronounce/employer/english", "dict": "https://dictionary.cambridge.org/dictionary/english/employer"}, {"en": "deadline", "ipa": "/ˈdedlaɪn/", "ko": "마감일", "example": "I work long hours when there is a tight deadline.", "youglish": "https://youglish.com/pronounce/deadline/english", "dict": "https://dictionary.cambridge.org/dictionary/english/deadline"}, {"en": "unemployment", "ipa": "/ˌʌnɪmˈplɔɪmənt/", "ko": "실업", "example": "Youth unemployment is a serious problem in many countries.", "youglish": "https://youglish.com/pronounce/unemployment/english", "dict": "https://dictionary.cambridge.org/dictionary/english/unemployment"}, {"en": "stressful", "ipa": "/ˈstresfl/", "ko": "스트레스가 많은", "example": "My job can be stressful, but it is never boring.", "youglish": "https://youglish.com/pronounce/stressful/english", "dict": "https://dictionary.cambridge.org/dictionary/english/stressful"}]}'::jsonb, todos = '[{"kind": "blog", "text": "Part 1 질문 목록에서 Work·Study 질문(각 10개 정도)을 소리 내 답해 보기", "url": "https://ieltsliz.com/ielts-speaking-part-1-topics/", "minutes": 15}]'::jsonb where day = '2026-11-26';
update public.ielts_days set note = '{"summary": "연결어는 Writing 채점 기준 중 ''일관성과 결속(Coherence & Cohesion)''에 직결돼요 (4개 기준 중 하나, 25%). 많이 쓰는 것보다 정확한 자리(문장 맨 앞 + 쉼표)에 쓰는 게 중요해요.", "items": [{"en": "In addition,", "ko": "게다가", "usage": "같은 방향의 이유를 더할 때. 문장 맨 앞 + 쉼표. 뒤에 명사를 붙일 땐 In addition to + 명사.", "examples": [{"type": "w", "text": "Online courses are cheap. In addition, they are very flexible."}, {"type": "s", "text": "Also, it''s really cheap. (말할 땐 Also가 더 자연스러워요)"}], "mistake": "✗ In addition of → In addition to + 명사", "pron": {"word": "addition", "ipa": "/əˈdɪʃn/", "youglish": "https://youglish.com/pronounce/in%20addition/english", "dict": "https://dictionary.cambridge.org/dictionary/english/addition"}}, {"en": "However,", "ko": "하지만", "usage": "문장 맨 앞 + 쉼표. 두 문장을 쉼표로 잇는 접속사가 아니에요.", "examples": [{"type": "w", "text": "University is expensive. However, it can lead to a better career."}, {"type": "s", "text": "It''s a nice city. However, the traffic is terrible."}], "mistake": "✗ University is expensive, however it is useful. → 마침표로 끊고 However, ...", "pron": {"word": "however", "ipa": "/haʊˈevə(r)/", "youglish": "https://youglish.com/pronounce/however/english", "dict": "https://dictionary.cambridge.org/dictionary/english/however"}}, {"en": "For example,", "ko": "예를 들어", "usage": "뒤에 완전한 문장이 와요. 명사만 나열할 땐 such as를 써요.", "examples": [{"type": "w", "text": "Many jobs require practical skills. For example, nurses need to stay calm in emergencies."}, {"type": "s", "text": "I like outdoor activities such as hiking and camping."}], "mistake": "✗ I like sports. For example, football. → I like sports such as football.", "pron": {"word": "example", "ipa": "/ɪɡˈzɑːmpl/", "youglish": "https://youglish.com/pronounce/for%20example/english", "dict": "https://dictionary.cambridge.org/dictionary/english/example"}}, {"en": "As a result,", "ko": "그 결과", "usage": "원인 문장 다음, 결과 문장 맨 앞에 써요. 명사가 오면 As a result of + 명사.", "examples": [{"type": "w", "text": "Tuition fees have risen sharply. As a result, fewer students can afford university."}, {"type": "s", "text": "I missed the bus, and as a result I was late for work."}], "mistake": "✗ As a result of, it rained. → As a result of the rain, ... 또는 As a result, ...", "pron": {"word": "result", "ipa": "/rɪˈzʌlt/", "youglish": "https://youglish.com/pronounce/as%20a%20result/english", "dict": "https://dictionary.cambridge.org/dictionary/english/result"}}, {"en": "due to + 명사", "ko": "~ 때문에", "usage": "뒤에 명사(구)가 와요. 주어+동사가 오면 because를 써요.", "examples": [{"type": "w", "text": "Air pollution has increased due to the rise in car use."}, {"type": "s", "text": "I couldn''t sleep due to the noise."}], "mistake": "✗ due to it was raining → because it was raining / due to the rain", "pron": {"word": "due", "ipa": "/djuː/", "youglish": "https://youglish.com/pronounce/due%20to%20the/english", "dict": "https://dictionary.cambridge.org/dictionary/english/due"}}], "frame_tip": "“Discuss both views” 문제에서 본론 두 문단을 시작할 때 써요. On the other hand는 ''반대 입장''에만 써요. 단순히 내용을 더할 때 쓰면 틀려요. On one hand(미국 구어)보다 On the one hand가 정석이에요.", "extra": null}'::jsonb, quiz = '[{"q": "The weather was bad. ___ ___ ______, the flight was cancelled.", "a": "As a result"}, {"q": "틀린 곳 고치기: “University is expensive, however it is useful.”", "a": "University is expensive*. However,* it is useful."}, {"q": "because / due to: “Many people were late ______ the heavy snow.”", "a": "due to"}, {"q": "틀린 곳 고치기: “I like sports. For example, football and tennis.”", "a": "I like sports *such as* football and tennis."}]'::jsonb, model = '{"text": "Many young people want to get a degree because it can improve their career prospects. In addition, graduates usually earn a better salary. However, high tuition fees are a serious problem. For example, many students in my country have to work long hours while they study. As a result, their academic performance often suffers.", "why": ["연결어마다 역할이 달라요: 추가(In addition) → 반대(However) → 예시(For example) → 결과(As a result).", "모두 문장 맨 앞 + 쉼표 위치예요.", "지난 3일 표현(degree, career prospects, salary, tuition fees, long hours, academic performance)을 재활용했어요."]}'::jsonb, extras = '{"phrases": [{"en": "in other words,", "ko": "다시 말해", "example": "Prices have doubled. In other words, people can buy half as much.", "youglish": "https://youglish.com/pronounce/in%20other%20words/english"}, {"en": "on top of that,", "ko": "게다가 (구어)", "example": "It''s cheap. On top of that, it''s really close to my house.", "youglish": "https://youglish.com/pronounce/on%20top%20of%20that/english"}, {"en": "as a consequence,", "ko": "그 결과로 (격식)", "example": "Sea levels are rising. As a consequence, some islands may disappear.", "youglish": "https://youglish.com/pronounce/as%20a%20consequence/english"}, {"en": "for instance,", "ko": "예를 들어 (For example과 같은 뜻)", "example": "Many jobs require teamwork. For instance, nurses work closely with doctors.", "youglish": "https://youglish.com/pronounce/for%20instance/english"}, {"en": "because of + 명사", "ko": "~ 때문에 (말하기·쓰기 모두)", "example": "I was late because of the traffic.", "youglish": "https://youglish.com/pronounce/because%20of/english"}], "words": [{"en": "furthermore", "ipa": "/ˌfɜːðəˈmɔː(r)/", "ko": "더욱이 (격식)", "example": "Furthermore, online courses are often cheaper.", "youglish": "https://youglish.com/pronounce/furthermore/english", "dict": "https://dictionary.cambridge.org/dictionary/english/furthermore"}, {"en": "nevertheless", "ipa": "/ˌnevəðəˈles/", "ko": "그럼에도 불구하고", "example": "The job is stressful. Nevertheless, I enjoy it.", "youglish": "https://youglish.com/pronounce/nevertheless/english", "dict": "https://dictionary.cambridge.org/dictionary/english/nevertheless"}, {"en": "consequently", "ipa": "/ˈkɒnsɪkwəntli/", "ko": "결과적으로", "example": "Fewer people are having children. Consequently, the population is getting older.", "youglish": "https://youglish.com/pronounce/consequently/english", "dict": "https://dictionary.cambridge.org/dictionary/english/consequently"}, {"en": "similarly", "ipa": "/ˈsɪmələli/", "ko": "마찬가지로", "example": "Children need exercise. Similarly, adults need to stay active.", "youglish": "https://youglish.com/pronounce/similarly/english", "dict": "https://dictionary.cambridge.org/dictionary/english/similarly"}, {"en": "whereas", "ipa": "/ˌweərˈæz/", "ko": "반면에", "example": "My brother loves sport, whereas I prefer reading.", "youglish": "https://youglish.com/pronounce/whereas/english", "dict": "https://dictionary.cambridge.org/dictionary/english/whereas"}]}'::jsonb, todos = '[{"kind": "blog", "text": "기능별 연결어 목록 보고, 빈칸 연습문제 풀기 (정답 해설 있음)", "url": "https://ieltsliz.com/linking-words-for-writing/", "minutes": 15}]'::jsonb where day = '2026-11-27';
update public.ielts_days set note = '{"summary": "어제 연결어의 ''격식 버전''과 결론 표현이에요. 특히 Although는 한 문장 안에서 두 절을 잇는 접속사라 However와 자리가 달라요. 가장 많이 헷갈리는 부분이에요.", "items": [{"en": "owing to + 명사", "ko": "~ 때문에 (격식)", "usage": "due to와 거의 같고 조금 더 격식 있어요. 문장 맨 앞에 쓰기 좋아요.", "examples": [{"type": "w", "text": "Owing to rising costs, many families cannot afford private schools."}, {"type": "s", "text": "The train was late because of the snow. (말할 땐 because of가 자연스러워요)"}], "mistake": "✗ owing to they are busy → because they are busy", "pron": {"word": "owing", "ipa": "/ˈəʊɪŋ/", "youglish": "https://youglish.com/pronounce/owing%20to/english", "dict": "https://dictionary.cambridge.org/dictionary/english/owing"}}, {"en": "one clear example is ...", "ko": "한 가지 분명한 예는", "usage": "본론에서 예시를 시작할 때. 뒤에 명사가 오고, where/who로 설명을 붙이면 좋아요.", "examples": [{"type": "w", "text": "One clear example is Finland, where education is free at all levels."}, {"type": "s", "text": "A good example is my brother, who learned coding online."}], "mistake": "✗ One clear example is that Finland. → that 빼기", "pron": {"word": "clear", "ipa": "/klɪə(r)/", "youglish": "https://youglish.com/pronounce/one%20clear%20example%20is/english", "dict": "https://dictionary.cambridge.org/dictionary/english/clear"}}, {"en": "Therefore,", "ko": "그러므로", "usage": "논리적 결론을 낼 때. 문장 맨 앞 + 쉼표.", "examples": [{"type": "w", "text": "Education benefits the whole of society. Therefore, governments should fund universities."}, {"type": "s", "text": "So, I think it''s worth it. (말할 땐 So가 자연스러워요)"}], "mistake": "Therefore를 남발하지 마세요. 앞 문장에서 정말 결론이 나올 때만 써요.", "pron": {"word": "therefore", "ipa": "/ˈðeəfɔː(r)/", "youglish": "https://youglish.com/pronounce/therefore/english", "dict": "https://dictionary.cambridge.org/dictionary/english/therefore"}}, {"en": "Although + 주어 + 동사", "ko": "비록 ~이지만", "usage": "한 문장 안에서 두 절을 이어요: Although A, B.", "examples": [{"type": "w", "text": "Although online courses are cheap, they require a lot of self-discipline."}, {"type": "s", "text": "Although it''s a small city, there''s a lot to do."}], "mistake": "✗ Although it is expensive, but it is useful. → but을 빼야 해요 (한국어 습관 주의)", "pron": {"word": "although", "ipa": "/ɔːlˈðəʊ/", "youglish": "https://youglish.com/pronounce/although/english", "dict": "https://dictionary.cambridge.org/dictionary/english/although"}}, {"en": "In conclusion,", "ko": "결론적으로", "usage": "에세이 마지막 문단의 첫마디. 내 입장을 다시 말해요.", "examples": [{"type": "w", "text": "In conclusion, I believe that university education should be free for all students."}, {"type": "s", "text": "So overall, I''d say ... (말할 땐 거의 안 써요)"}], "mistake": "In conclusion 뒤에 새로운 이유를 추가하면 안 돼요. ✗ In a conclusion", "pron": {"word": "conclusion", "ipa": "/kənˈkluːʒn/", "youglish": "https://youglish.com/pronounce/in%20conclusion/english", "dict": "https://dictionary.cambridge.org/dictionary/english/conclusion"}}], "frame_tip": "반대쪽을 먼저 인정하고 내 입장을 세우는 문장이에요. 서론의 입장 문장, 결론의 첫 문장 모두에 써요. 주의: Although와 but은 함께 쓰지 않아요.", "extra": null}'::jsonb, quiz = '[{"q": "틀린 곳 고치기: “Although it is expensive, but it is useful.”", "a": "*but* 삭제 → Although it is expensive, it is useful."}, {"q": "(격식) ______ ___ the bad weather, the event was cancelled.", "a": "Owing to"}, {"q": "However / Although: “______ the course is short, it is very useful.”", "a": "Although"}, {"q": "에세이 마지막 문단 첫 두 단어: “______, I believe that ...”", "a": "In conclusion"}]'::jsonb, model = '{"text": "Although university education is expensive, I believe it is a good investment. Owing to strong competition in the job market, a degree is often necessary to get a good job. One clear example is the IT industry, where many companies prefer graduates. Therefore, governments should help students pay their tuition fees.", "why": ["Although(인정) → Owing to(이유) → One clear example(예시) → Therefore(결론) 흐름이에요.", "Although 문장에 but이 없어요.", "이 4문장이 그대로 에세이 본론 한 문단 뼈대가 돼요."]}'::jsonb, extras = '{"phrases": [{"en": "despite + 명사/-ing", "ko": "~에도 불구하고", "example": "Despite the high cost, many students choose to study abroad.", "youglish": "https://youglish.com/pronounce/despite/english"}, {"en": "even though + 문장", "ko": "비록 ~이지만 (although보다 강조)", "example": "Even though I was tired, I finished my homework.", "youglish": "https://youglish.com/pronounce/even%20though/english"}, {"en": "to sum up,", "ko": "요약하자면", "example": "To sum up, both sides have valid points.", "youglish": "https://youglish.com/pronounce/to%20sum%20up/english"}, {"en": "on balance,", "ko": "모든 걸 고려하면", "example": "On balance, I believe the advantages outweigh the disadvantages.", "youglish": "https://youglish.com/pronounce/on%20balance/english"}, {"en": "the advantages outweigh the disadvantages", "ko": "장점이 단점보다 크다", "example": "In my view, the advantages of online learning outweigh the disadvantages.", "youglish": "https://youglish.com/pronounce/the%20advantages%20outweigh%20the%20disadvantages/english"}], "words": [{"en": "whereby", "ipa": "/weəˈbaɪ/", "ko": "그것에 의하여 (격식, 제도 설명)", "example": "There is a system whereby students can borrow money for tuition.", "youglish": "https://youglish.com/pronounce/whereby/english", "dict": "https://dictionary.cambridge.org/dictionary/english/whereby"}, {"en": "thus", "ipa": "/ðʌs/", "ko": "따라서 (격식)", "example": "Prices rose; thus, sales fell.", "youglish": "https://youglish.com/pronounce/thus/english", "dict": "https://dictionary.cambridge.org/dictionary/english/thus"}, {"en": "moreover", "ipa": "/mɔːrˈəʊvə(r)/", "ko": "게다가 (격식)", "example": "Moreover, public transport reduces pollution.", "youglish": "https://youglish.com/pronounce/moreover/english", "dict": "https://dictionary.cambridge.org/dictionary/english/moreover"}, {"en": "hence", "ipa": "/hens/", "ko": "그래서 (격식, 짧게)", "example": "The city is crowded, hence the high rents.", "youglish": "https://youglish.com/pronounce/hence/english", "dict": "https://dictionary.cambridge.org/dictionary/english/hence"}, {"en": "overall", "ipa": "/ˌəʊvərˈɔːl/", "ko": "전반적으로", "example": "Overall, I think the policy has been successful.", "youglish": "https://youglish.com/pronounce/overall/english", "dict": "https://dictionary.cambridge.org/dictionary/english/overall"}]}'::jsonb, todos = '[{"kind": "blog", "text": "연결어 빈칸 5문제 풀기 (오늘 미션)", "url": "https://ieltsliz.com/ielts-writing-task-2-practice-with-linking-words/", "minutes": 10}, {"kind": "listening", "text": "British Council 공식 Listening Test 1 (4파트, 30분) → 채점 → 틀린 문제는 스크립트로 확인", "url": "https://takeielts.britishcouncil.org/prepare-test/free-ielts-practice-tests/listening-practice-test-1", "minutes": 45}]'::jsonb where day = '2026-11-28';
update public.ielts_days set note = '{"summary": "이번 주 표현으로 Task 2 에세이 한 편을 써요. 40분 동안 계획 5분 → 쓰기 30분 → 검토 5분으로 나눠 보세요. 아래 설계도대로 문단마다 어떤 표현을 쓸지 미리 정하면 훨씬 빨라져요.", "items": [], "frame_tip": null, "extra": "*🧭 에세이 설계도 (4~5문단, 250단어 이상)*\n• *서론* (2문장): Some people believe that ..., while others argue that ... + 내 입장 (Although ..., I believe that ...)\n• *본론 1* (4~5문장): 첫 번째 이유 + For example + As a result\n• *본론 2* (4~5문장): 두 번째 이유 + In addition + One clear example is ...\n• *(선택) 반대 의견 인정*: However, ... Therefore, ...\n• *결론* (2문장): In conclusion, + 입장 재진술 (새 이유 금지)\n\n*✅ 다 쓰고 2분 체크*\n• 단어 수 250 이상? • Although 뒤에 but 없나? • tuition fees / skills 복수형? • 연결어 뒤 쉼표?"}'::jsonb, quiz = null, model = '{"text": "Some people believe that university education should be free for everyone, while others argue that students should pay for their own studies. Although free education would be expensive for governments, I agree with this idea for two main reasons.\n\nFirstly, high tuition fees prevent many talented students from going to university. Owing to the high cost, young people from poor families often choose to work instead of getting a degree. As a result, society loses people who could become good doctors, engineers or teachers. If higher education were free, everyone would have an equal chance.\n\nSecondly, free university education benefits the whole country. Graduates usually earn a good salary, so they pay more tax in the future. In addition, they acquire practical skills that help the economy grow. One clear example is Germany, where most public universities do not charge tuition fees.\n\nHowever, free education also has some problems. For example, some students may not study seriously if they do not pay anything. Therefore, governments should support only students who maintain good academic performance.\n\nIn conclusion, I believe that university education should be free because it gives everyone a fair chance and benefits society as a whole. However, students should show that they deserve this support by working hard.", "why": ["서론에서 양쪽 의견 + 내 입장을 두 문장으로 끝냈어요.", "본론마다 이유 → 설명 → 예시/결과 순서예요.", "이번 주 표현을 12개 이상 썼지만 어려운 단어는 없어요. Band 6 정도의 답안이에요."]}'::jsonb, extras = null, todos = null where day = '2026-11-29';
update public.ielts_days set note = '{"summary": "기술은 Speaking Part 1(휴대폰·인터넷 사용)과 Task 2(SNS가 인간관계에 미치는 영향) 양쪽에 나와요. 오늘은 일상 표현 위주라 말하기에 바로 써 보세요.", "items": [{"en": "keep in touch with", "ko": "~와 연락하고 지내다", "usage": "keep in touch with + 사람. stay in touch with도 같은 뜻이에요.", "examples": [{"type": "w", "text": "Social media helps people keep in touch with friends who live abroad."}, {"type": "s", "text": "I use KakaoTalk to keep in touch with my family."}], "mistake": "✗ keep in touch to → with / ✗ contact with him → contact him (contact는 바로 목적어)", "pron": {"word": "touch", "ipa": "/tʌtʃ/", "youglish": "https://youglish.com/pronounce/keep%20in%20touch%20with/english", "dict": "https://dictionary.cambridge.org/dictionary/english/touch"}}, {"en": "spend too much time online", "ko": "온라인에 너무 많은 시간을 쓰다", "usage": "spend + 시간 + -ing / on + 명사.", "examples": [{"type": "w", "text": "Teenagers who spend too much time online may suffer from poor sleep."}, {"type": "s", "text": "I probably spend too much time online, especially at night."}], "mistake": "✗ spend time to play → spend time playing", "pron": {"word": "online", "ipa": "/ˌɒnˈlaɪn/", "youglish": "https://youglish.com/pronounce/spend%20too%20much%20time%20online/english", "dict": "https://dictionary.cambridge.org/dictionary/english/online"}}, {"en": "access information", "ko": "정보에 접근하다", "usage": "동사 access는 바로 목적어가 와요. 명사로 쓸 땐 have access to.", "examples": [{"type": "w", "text": "The internet allows people to access information instantly."}, {"type": "s", "text": "I can access information about almost anything on my phone."}], "mistake": "✗ access to information (동사일 때) → access information / have access to information", "pron": {"word": "access", "ipa": "/ˈækses/", "youglish": "https://youglish.com/pronounce/access%20information/english", "dict": "https://dictionary.cambridge.org/dictionary/english/access"}}, {"en": "social media platforms", "ko": "소셜 미디어 (플랫폼)", "usage": "social media는 보통 단수 취급해요: Social media is ...", "examples": [{"type": "w", "text": "Social media platforms can spread false information very quickly."}, {"type": "s", "text": "I''m not very active on social media."}], "mistake": "✗ SNS (한국식 표현이라 영어권에선 잘 안 통해요) → social media", "pron": {"word": "media", "ipa": "/ˈmiːdiə/", "youglish": "https://youglish.com/pronounce/social%20media%20platforms/english", "dict": "https://dictionary.cambridge.org/dictionary/english/media"}}, {"en": "be addicted to ~", "ko": "~에 중독되다", "usage": "to는 전치사라 뒤에 명사나 -ing가 와요.", "examples": [{"type": "w", "text": "A growing number of children are addicted to online games."}, {"type": "s", "text": "I think I''m a bit addicted to my phone."}], "mistake": "✗ addicted to play → addicted to playing", "pron": {"word": "addicted", "ipa": "/əˈdɪktɪd/", "youglish": "https://youglish.com/pronounce/addicted%20to/english", "dict": "https://dictionary.cambridge.org/dictionary/english/addicted"}}], "frame_tip": "Task 2 서론 첫 문장(배경 소개)으로 써요. more and more people 뒤에는 복수 동사가 와요. 뒤 내용은 문제 문장을 베끼지 말고 내 말로 바꾸세요.", "extra": null}'::jsonb, quiz = '[{"q": "I use video calls to keep in ______ ______ my parents.", "a": "touch with"}, {"q": "틀린 곳 고치기: “The internet lets us access to information easily.”", "a": "lets us *access information* easily"}, {"q": "틀린 곳 고치기: “Many teenagers are addicted to play games.”", "a": "addicted to *playing* games"}, {"q": "한국식 표현 고치기: “I use SNS every day.”", "a": "I use *social media* every day."}]'::jsonb, model = '{"text": "Q: How often do you use your phone?\nA: Honestly, I use it all the time. I check the news in the morning and keep in touch with my family on messaging apps. I think I spend too much time online at night, so I''m trying to put my phone away before bed.", "why": ["빈도 질문에 바로 답(all the time)해요.", "용도 두 가지 → 솔직한 반성 → 계획 순서라 자연스러워요.", "Part 1에서는 짧은 축약형(I''m, it''s)이 오히려 자연스러워요."]}'::jsonb, extras = '{"phrases": [{"en": "scroll through social media", "ko": "소셜 미디어를 계속 넘겨보다", "example": "I often scroll through social media before I go to sleep.", "youglish": "https://youglish.com/pronounce/scroll%20through%20social%20media/english"}, {"en": "go viral", "ko": "(영상·글이) 퍼지다, 화제가 되다", "example": "Her video went viral overnight.", "youglish": "https://youglish.com/pronounce/go%20viral/english"}, {"en": "screen time", "ko": "화면 보는 시간", "example": "Parents should limit their children''s screen time.", "youglish": "https://youglish.com/pronounce/screen%20time/english"}, {"en": "log on / log off", "ko": "접속하다 / 접속을 끊다", "example": "I log off from work apps at the weekend.", "youglish": "https://youglish.com/pronounce/log%20on/english"}, {"en": "stay up late", "ko": "늦게까지 깨어 있다", "example": "Teenagers often stay up late playing games.", "youglish": "https://youglish.com/pronounce/stay%20up%20late/english"}], "words": [{"en": "device", "ipa": "/dɪˈvaɪs/", "ko": "기기", "example": "Most people have more than one device.", "youglish": "https://youglish.com/pronounce/device/english", "dict": "https://dictionary.cambridge.org/dictionary/english/device"}, {"en": "notification", "ipa": "/ˌnəʊtɪfɪˈkeɪʃn/", "ko": "알림", "example": "I turn off notifications when I need to focus.", "youglish": "https://youglish.com/pronounce/notification/english", "dict": "https://dictionary.cambridge.org/dictionary/english/notification"}, {"en": "cyberbullying", "ipa": "/ˈsaɪbəbʊliɪŋ/", "ko": "사이버 괴롭힘", "example": "Cyberbullying is a serious problem in schools.", "youglish": "https://youglish.com/pronounce/cyberbullying/english", "dict": "https://dictionary.cambridge.org/dictionary/english/cyberbullying"}, {"en": "isolation", "ipa": "/ˌaɪsəˈleɪʃn/", "ko": "고립", "example": "Too much time online can lead to social isolation.", "youglish": "https://youglish.com/pronounce/isolation/english", "dict": "https://dictionary.cambridge.org/dictionary/english/isolation"}, {"en": "convenient", "ipa": "/kənˈviːniənt/", "ko": "편리한", "example": "Online shopping is very convenient.", "youglish": "https://youglish.com/pronounce/convenient/english", "dict": "https://dictionary.cambridge.org/dictionary/english/convenient"}]}'::jsonb, todos = '[{"kind": "blog", "text": "짧은 읽기 글 + 빈칸 문제 풀고, Part 1 모범 답안 1개 읽기", "url": "https://ieltsliz.com/technology-vocabulary-for-speaking/", "minutes": 15}]'::jsonb where day = '2026-11-30';
update public.ielts_days set note = '{"summary": "“AI와 기술이 일자리를 빼앗을까?”는 최근 자주 나오는 Task 2 주제예요. 장점(효율)과 단점(일자리·사생활) 표현을 둘 다 준비하세요.", "items": [{"en": "technological advances", "ko": "기술 발전", "usage": "복수형으로 써요. advances in + 분야.", "examples": [{"type": "w", "text": "Technological advances in medicine have helped people live longer."}, {"type": "s", "text": "Technological advances have made my job much easier."}], "mistake": "✗ technology advance → technological advances", "pron": {"word": "technological", "ipa": "/ˌteknəˈlɒdʒɪkl/", "youglish": "https://youglish.com/pronounce/technological%20advances/english", "dict": "https://dictionary.cambridge.org/dictionary/english/technological"}}, {"en": "replace human workers", "ko": "인간 노동자를 대체하다", "usage": "A replace B = A가 B를 대신하다. 수동태: B be replaced by A.", "examples": [{"type": "w", "text": "Robots are likely to replace human workers in many factories."}, {"type": "s", "text": "I don''t think AI will replace teachers completely."}], "mistake": "✗ replace to human workers → replace human workers", "pron": {"word": "replace", "ipa": "/rɪˈpleɪs/", "youglish": "https://youglish.com/pronounce/replace%20human%20workers/english", "dict": "https://dictionary.cambridge.org/dictionary/english/replace"}}, {"en": "improve efficiency", "ko": "효율을 높이다", "usage": "명사 efficiency를 써요. 형용사는 efficient.", "examples": [{"type": "w", "text": "Automation can improve efficiency and reduce costs."}, {"type": "s", "text": "Using AI tools has really improved efficiency at my company."}], "mistake": "✗ improve efficient → improve efficiency", "pron": {"word": "efficiency", "ipa": "/ɪˈfɪʃnsi/", "youglish": "https://youglish.com/pronounce/improve%20efficiency/english", "dict": "https://dictionary.cambridge.org/dictionary/english/efficiency"}}, {"en": "privacy concerns", "ko": "사생활 침해 우려", "usage": "raise privacy concerns, concerns about privacy.", "examples": [{"type": "w", "text": "Facial recognition technology raises serious privacy concerns."}, {"type": "s", "text": "I have some privacy concerns about smart speakers."}], "mistake": "발음: 영국 /ˈprɪvəsi/ (프리버시), 미국 /ˈpraɪvəsi/ (프라이버시) 둘 다 맞아요.", "pron": {"word": "privacy", "ipa": "/ˈprɪvəsi/", "youglish": "https://youglish.com/pronounce/privacy%20concerns/english", "dict": "https://dictionary.cambridge.org/dictionary/english/privacy"}}, {"en": "artificial intelligence", "ko": "인공지능", "usage": "셀 수 없는 명사. 처음엔 풀어 쓰고 그다음부터 AI로 써요.", "examples": [{"type": "w", "text": "Artificial intelligence (AI) is changing the way people work."}, {"type": "s", "text": "I use AI almost every day for work."}], "mistake": "✗ an artificial intelligence (일반 개념일 때)", "pron": {"word": "artificial", "ipa": "/ˌɑːtɪˈfɪʃl/", "youglish": "https://youglish.com/pronounce/artificial%20intelligence/english", "dict": "https://dictionary.cambridge.org/dictionary/english/artificial"}}], "frame_tip": "본론에서 이유 여러 개를 소개할 때 써요. why 뒤는 평서문 어순(주어 + 동사)이에요.", "extra": null}'::jsonb, quiz = '[{"q": "틀린 곳 고치기: “There are several reasons why is AI popular.”", "a": "why *AI is* popular"}, {"q": "Robots may ______ human workers in many factories.", "a": "replace"}, {"q": "형태 고치기: “AI can improve efficient.”", "a": "efficiency"}, {"q": "Smart cameras raise serious ______ ______.", "a": "privacy concerns"}]'::jsonb, model = '{"text": "I do not think artificial intelligence will replace most workers, although it will replace some human workers in factories and offices. AI can improve efficiency, but people are still needed for jobs that require creativity and communication. Therefore, workers should learn new skills so that they can work together with AI.", "why": ["입장을 먼저 밝히고 although로 반대쪽을 일부 인정했어요.", "이유(창의성·소통) → 결론(Therefore) 흐름이에요.", "지난주 연결어를 그대로 재활용했어요."]}'::jsonb, extras = '{"phrases": [{"en": "lose their jobs", "ko": "일자리를 잃다", "example": "Many factory workers may lose their jobs to robots.", "youglish": "https://youglish.com/pronounce/lose%20their%20jobs/english"}, {"en": "keep up with technology", "ko": "기술 변화를 따라가다", "example": "Older people sometimes find it hard to keep up with technology.", "youglish": "https://youglish.com/pronounce/keep%20up%20with%20technology/english"}, {"en": "in the long run", "ko": "장기적으로", "example": "In the long run, AI will create new types of jobs.", "youglish": "https://youglish.com/pronounce/in%20the%20long%20run/english"}, {"en": "a double-edged sword", "ko": "양날의 검", "example": "Technology is a double-edged sword.", "youglish": "https://youglish.com/pronounce/a%20double-edged%20sword/english"}, {"en": "rely on ~", "ko": "~에 의존하다", "example": "Many companies rely on AI to answer customer questions.", "youglish": "https://youglish.com/pronounce/rely%20on/english"}], "words": [{"en": "automation", "ipa": "/ˌɔːtəˈmeɪʃn/", "ko": "자동화", "example": "Automation has changed the way factories work.", "youglish": "https://youglish.com/pronounce/automation/english", "dict": "https://dictionary.cambridge.org/dictionary/english/automation"}, {"en": "innovation", "ipa": "/ˌɪnəˈveɪʃn/", "ko": "혁신", "example": "Innovation is the key to economic growth.", "youglish": "https://youglish.com/pronounce/innovation/english", "dict": "https://dictionary.cambridge.org/dictionary/english/innovation"}, {"en": "obsolete", "ipa": "/ˈɒbsəliːt/", "ko": "더 이상 쓰이지 않는, 구식이 된", "example": "Some jobs may become obsolete in the next twenty years.", "youglish": "https://youglish.com/pronounce/obsolete/english", "dict": "https://dictionary.cambridge.org/dictionary/english/obsolete"}, {"en": "surveillance", "ipa": "/sɜːˈveɪləns/", "ko": "감시", "example": "Some people worry about government surveillance.", "youglish": "https://youglish.com/pronounce/surveillance/english", "dict": "https://dictionary.cambridge.org/dictionary/english/surveillance"}, {"en": "retrain", "ipa": "/ˌriːˈtreɪn/", "ko": "재교육하다, 재교육을 받다", "example": "Workers need to retrain when their jobs change.", "youglish": "https://youglish.com/pronounce/retrain/english", "dict": "https://dictionary.cambridge.org/dictionary/english/retrain"}]}'::jsonb, todos = '[{"kind": "blog", "text": "같은 페이지 아래 ''Part 3 기술 질문'' 링크에서 질문 2개 골라 소리 내 답하기", "url": "https://ieltsliz.com/technology-vocabulary-for-speaking/", "minutes": 10}]'::jsonb where day = '2026-12-01';
update public.ielts_days set note = '{"summary": "환경은 Task 2 최다 출제 주제 중 하나예요. 보통 원인 → 결과 → 해결 구조로 물어요. 오늘은 ''문제와 원인'', 내일은 ''해결책''이에요.", "items": [{"en": "climate change", "ko": "기후 변화", "usage": "셀 수 없는 명사라 관사 없이 써요. tackle / combat climate change.", "examples": [{"type": "w", "text": "Climate change is one of the biggest problems facing the world today."}, {"type": "s", "text": "You can really feel climate change in Korea; summers are getting hotter."}], "mistake": "✗ the climate change (일반적으로 말할 때)", "pron": {"word": "climate", "ipa": "/ˈklaɪmət/", "youglish": "https://youglish.com/pronounce/climate%20change/english", "dict": "https://dictionary.cambridge.org/dictionary/english/climate"}}, {"en": "air pollution", "ko": "대기 오염", "usage": "셀 수 없는 명사. cause / reduce air pollution. 미세먼지는 fine dust.", "examples": [{"type": "w", "text": "Air pollution in big cities causes serious health problems."}, {"type": "s", "text": "The air pollution is pretty bad in spring because of fine dust."}], "mistake": "✗ air pollutions", "pron": {"word": "pollution", "ipa": "/pəˈluːʃn/", "youglish": "https://youglish.com/pronounce/air%20pollution/english", "dict": "https://dictionary.cambridge.org/dictionary/english/pollution"}}, {"en": "greenhouse gas emissions", "ko": "온실가스 배출", "usage": "emissions는 복수형. reduce / cut emissions. 구어에선 carbon emissions도 많이 써요.", "examples": [{"type": "w", "text": "Governments must cut greenhouse gas emissions to slow global warming."}, {"type": "s", "text": "I try to cut my carbon emissions by taking the subway."}], "mistake": "✗ The emission is decreased. → Emissions have fallen.", "pron": {"word": "emissions", "ipa": "/iˈmɪʃnz/", "youglish": "https://youglish.com/pronounce/greenhouse%20gas%20emissions/english", "dict": "https://dictionary.cambridge.org/dictionary/english/emissions"}}, {"en": "cause serious damage to ~", "ko": "~에 심각한 피해를 주다", "usage": "damage는 셀 수 없는 명사예요. 전치사는 to.", "examples": [{"type": "w", "text": "Plastic waste causes serious damage to marine life."}, {"type": "s", "text": "The typhoon caused serious damage to the town."}], "mistake": "✗ cause serious damages / ✗ damage on → to", "pron": {"word": "damage", "ipa": "/ˈdæmɪdʒ/", "youglish": "https://youglish.com/pronounce/cause%20serious%20damage/english", "dict": "https://dictionary.cambridge.org/dictionary/english/damage"}}, {"en": "fossil fuels", "ko": "화석 연료", "usage": "복수형. burn / rely on fossil fuels.", "examples": [{"type": "w", "text": "Burning fossil fuels is the main cause of climate change."}, {"type": "s", "text": "Most cars in Korea still run on fossil fuels."}], "mistake": "발음 주의: fossil /ˈfɒsl/ (포슬)", "pron": {"word": "fossil", "ipa": "/ˈfɒsl/", "youglish": "https://youglish.com/pronounce/fossil%20fuels/english", "dict": "https://dictionary.cambridge.org/dictionary/english/fossil"}}], "frame_tip": "원인을 제시하는 문장이에요. One of the + 복수 명사 + is (단수 동사)! 두 번째 원인은 Another cause is ...로 이어요.", "extra": null}'::jsonb, quiz = '[{"q": "틀린 곳 고치기: “One of the main cause of pollution are cars.”", "a": "One of the main *causes* of pollution *is* cars."}, {"q": "틀린 곳 고치기: “Floods caused serious damages to the city.”", "a": "*damage*"}, {"q": "Burning ______ ______ releases carbon dioxide.", "a": "fossil fuels"}, {"q": "관사: “___ climate change is a global problem.” (a / the / 없음)", "a": "없음 → Climate change is ..."}]'::jsonb, model = '{"text": "One of the main causes of air pollution is the large number of cars in big cities. Another cause is factories that burn fossil fuels and release harmful gases into the air.", "why": ["원인마다 ''무엇이 → 어떻게''를 구체적으로 썼어요.", "Another cause is로 두 번째 원인을 자연스럽게 이었어요.", "One of the main causes ... is — 단수 동사 is에 주의했어요."]}'::jsonb, extras = '{"phrases": [{"en": "global warming", "ko": "지구 온난화", "example": "Global warming is causing more extreme weather.", "youglish": "https://youglish.com/pronounce/global%20warming/english"}, {"en": "rising sea levels", "ko": "해수면 상승", "example": "Rising sea levels threaten coastal cities.", "youglish": "https://youglish.com/pronounce/rising%20sea%20levels/english"}, {"en": "extreme weather", "ko": "극단적인 날씨, 이상 기후", "example": "Extreme weather such as floods is becoming more common.", "youglish": "https://youglish.com/pronounce/extreme%20weather/english"}, {"en": "harmful to the environment", "ko": "환경에 해로운", "example": "Plastic bags are harmful to the environment.", "youglish": "https://youglish.com/pronounce/harmful%20to%20the%20environment/english"}, {"en": "cut down trees", "ko": "나무를 베다", "example": "Large areas of forest are cut down every year.", "youglish": "https://youglish.com/pronounce/cut%20down%20trees/english"}], "words": [{"en": "deforestation", "ipa": "/ˌdiːˌfɒrɪˈsteɪʃn/", "ko": "삼림 벌채", "example": "Deforestation destroys the homes of many animals.", "youglish": "https://youglish.com/pronounce/deforestation/english", "dict": "https://dictionary.cambridge.org/dictionary/english/deforestation"}, {"en": "pollutant", "ipa": "/pəˈluːtənt/", "ko": "오염 물질", "example": "Cars release pollutants into the air.", "youglish": "https://youglish.com/pronounce/pollutant/english", "dict": "https://dictionary.cambridge.org/dictionary/english/pollutant"}, {"en": "drought", "ipa": "/draʊt/", "ko": "가뭄", "example": "The drought destroyed the crops.", "youglish": "https://youglish.com/pronounce/drought/english", "dict": "https://dictionary.cambridge.org/dictionary/english/drought"}, {"en": "endangered", "ipa": "/ɪnˈdeɪndʒəd/", "ko": "멸종 위기의", "example": "Pandas are an endangered species.", "youglish": "https://youglish.com/pronounce/endangered/english", "dict": "https://dictionary.cambridge.org/dictionary/english/endangered"}, {"en": "toxic", "ipa": "/ˈtɒksɪk/", "ko": "유독한", "example": "Factories should not release toxic waste into rivers.", "youglish": "https://youglish.com/pronounce/toxic/english", "dict": "https://dictionary.cambridge.org/dictionary/english/toxic"}]}'::jsonb, todos = '[{"kind": "blog", "text": "환경 문제 10개: 오디오 듣고 빈칸 채우기 1~5번 (Listening 연습도 돼요)", "url": "http://www.ieltsliz.com/world-environmental-problems-vocabulary", "minutes": 15}, {"kind": "reading", "text": "British Council 공식 GT Reading Test 1 — Section 1 (20분)", "url": "https://takeielts.britishcouncil.org/take-ielts/prepare/free-ielts-english-practice-tests/reading/general-training", "minutes": 20}]'::jsonb where day = '2026-12-02';
update public.ielts_days set note = '{"summary": "해결책 문단은 ''누가(정부/개인) + 무엇을 + 그 결과''까지 쓰면 Band 6에 가까워져요. 해결책만 나열하고 결과를 안 쓰는 게 가장 흔한 실수예요.", "items": [{"en": "reduce waste", "ko": "쓰레기를 줄이다", "usage": "waste는 셀 수 없는 명사예요. food waste, plastic waste.", "examples": [{"type": "w", "text": "Supermarkets should reduce waste by charging for plastic bags."}, {"type": "s", "text": "I try to reduce waste by bringing my own cup to cafés."}], "mistake": "✗ reduce wastes / 발음은 waist(허리)와 같아요", "pron": {"word": "waste", "ipa": "/weɪst/", "youglish": "https://youglish.com/pronounce/reduce%20waste/english", "dict": "https://dictionary.cambridge.org/dictionary/english/waste"}}, {"en": "renewable energy", "ko": "재생 에너지", "usage": "셀 수 없는 명사. renewable energy such as solar and wind power.", "examples": [{"type": "w", "text": "Governments should invest more in renewable energy such as solar and wind power."}, {"type": "s", "text": "I think renewable energy is the future, but it''s still expensive."}], "mistake": "✗ renewal energy → renewable", "pron": {"word": "renewable", "ipa": "/rɪˈnjuːəbl/", "youglish": "https://youglish.com/pronounce/renewable%20energy/english", "dict": "https://dictionary.cambridge.org/dictionary/english/renewable"}}, {"en": "use public transport", "ko": "대중교통을 이용하다", "usage": "영국식 transport, 미국식 transportation. 관사 없이 써요.", "examples": [{"type": "w", "text": "If more people used public transport, there would be less traffic and pollution."}, {"type": "s", "text": "I usually use public transport because parking in Seoul is expensive."}], "mistake": "✗ use a public transport / ✗ public transports", "pron": {"word": "transport", "ipa": "/ˈtrænspɔːt/", "youglish": "https://youglish.com/pronounce/public%20transport/english", "dict": "https://dictionary.cambridge.org/dictionary/english/transport"}}, {"en": "protect wildlife", "ko": "야생동물을 보호하다", "usage": "wildlife는 셀 수 없는 명사예요.", "examples": [{"type": "w", "text": "Governments should create national parks to protect wildlife."}, {"type": "s", "text": "I think zoos can help protect wildlife in some ways."}], "mistake": "✗ wildlifes", "pron": {"word": "wildlife", "ipa": "/ˈwaɪldlaɪf/", "youglish": "https://youglish.com/pronounce/protect%20wildlife/english", "dict": "https://dictionary.cambridge.org/dictionary/english/wildlife"}}, {"en": "take action", "ko": "조치를 취하다", "usage": "take action to + 동사 / take action on + 명사. 보통 관사 없이 써요.", "examples": [{"type": "w", "text": "Governments must take action to reduce plastic waste."}, {"type": "s", "text": "I think everyone needs to take action, not just the government."}], "mistake": "✗ take an action / ✗ do action", "pron": {"word": "action", "ipa": "/ˈækʃn/", "youglish": "https://youglish.com/pronounce/take%20action/english", "dict": "https://dictionary.cambridge.org/dictionary/english/action"}}], "frame_tip": "해결책 제시 문장이에요. solution to가 정확해요 (for/of는 흔한 실수). 뒤에 결과(so that ...)까지 붙이면 좋아요.", "extra": null}'::jsonb, quiz = '[{"q": "전치사: One possible solution ___ this problem is to ...", "a": "to"}, {"q": "틀린 곳 고치기: “Governments should take an action.”", "a": "take action (an 삭제)"}, {"q": "Solar and wind power are types of ______ ______.", "a": "renewable energy"}, {"q": "틀린 곳 고치기: “I usually use a public transport.”", "a": "use public transport (a 삭제)"}]'::jsonb, model = '{"text": "One possible solution to this problem is to make public transport cheaper so that more people leave their cars at home. Another solution is for governments to invest in renewable energy and reduce the use of fossil fuels.", "why": ["해결책 + 그 결과(so that)까지 썼어요.", "Another solution is for + 주체 + to + 동사로 누가 할지 밝혔어요.", "어제 표현(fossil fuels)과 오늘 표현을 연결했어요."]}'::jsonb, extras = '{"phrases": [{"en": "go green", "ko": "친환경적으로 살다", "example": "Many companies are trying to go green.", "youglish": "https://youglish.com/pronounce/go%20green/english"}, {"en": "raise awareness of ~", "ko": "~에 대한 인식을 높이다", "example": "Schools should raise awareness of environmental issues.", "youglish": "https://youglish.com/pronounce/raise%20awareness%20of/english"}, {"en": "single-use plastics", "ko": "일회용 플라스틱", "example": "Some countries have banned single-use plastics.", "youglish": "https://youglish.com/pronounce/single-use%20plastics/english"}, {"en": "carbon footprint", "ko": "탄소 발자국", "example": "Flying increases your carbon footprint.", "youglish": "https://youglish.com/pronounce/carbon%20footprint/english"}, {"en": "make a difference", "ko": "변화를 만들다, 효과가 있다", "example": "Even small changes can make a difference.", "youglish": "https://youglish.com/pronounce/make%20a%20difference/english"}], "words": [{"en": "recycle", "ipa": "/ˌriːˈsaɪkl/", "ko": "재활용하다", "example": "We recycle paper, glass and plastic at home.", "youglish": "https://youglish.com/pronounce/recycle/english", "dict": "https://dictionary.cambridge.org/dictionary/english/recycle"}, {"en": "sustainable", "ipa": "/səˈsteɪnəbl/", "ko": "지속 가능한", "example": "We need more sustainable ways of producing food.", "youglish": "https://youglish.com/pronounce/sustainable/english", "dict": "https://dictionary.cambridge.org/dictionary/english/sustainable"}, {"en": "conservation", "ipa": "/ˌkɒnsəˈveɪʃn/", "ko": "보존, 보호", "example": "Wildlife conservation needs government funding.", "youglish": "https://youglish.com/pronounce/conservation/english", "dict": "https://dictionary.cambridge.org/dictionary/english/conservation"}, {"en": "incentive", "ipa": "/ɪnˈsentɪv/", "ko": "장려책, 인센티브", "example": "Tax incentives can encourage people to buy electric cars.", "youglish": "https://youglish.com/pronounce/incentive/english", "dict": "https://dictionary.cambridge.org/dictionary/english/incentive"}, {"en": "biodegradable", "ipa": "/ˌbaɪəʊdɪˈɡreɪdəbl/", "ko": "생분해성의", "example": "Biodegradable bags break down naturally.", "youglish": "https://youglish.com/pronounce/biodegradable/english", "dict": "https://dictionary.cambridge.org/dictionary/english/biodegradable"}]}'::jsonb, todos = '[{"kind": "blog", "text": "환경 오디오 빈칸 6~10번 마저 풀기", "url": "http://www.ieltsliz.com/world-environmental-problems-vocabulary", "minutes": 15}]'::jsonb where day = '2026-12-03';
update public.ielts_days set note = '{"summary": "Task 2 서론에서 문제 문장을 그대로 베끼면 그 부분은 단어 수에서 빠지고 어휘 점수도 낮아져요. 단어 바꾸기 + 구조 바꾸기, 두 가지만 기억하세요.", "items": [{"en": "important → essential / crucial", "ko": "중요한", "usage": "essential = 꼭 필요한, crucial = 결정적인. It is essential / crucial to + 동사.", "examples": [{"type": "w", "text": "It is essential for children to learn basic computer skills."}, {"type": "s", "text": "I think sleep is crucial for good health."}], "mistake": "✗ very essential (이미 강한 뜻이라 very를 안 붙여요)", "pron": {"word": "crucial", "ipa": "/ˈkruːʃl/", "youglish": "https://youglish.com/pronounce/crucial/english", "dict": "https://dictionary.cambridge.org/dictionary/english/crucial"}}, {"en": "think → believe / argue", "ko": "생각하다 → 믿다 / 주장하다", "usage": "argue = 근거를 대며 주장하다. 에세이에서 ''어떤 사람들은 ~라고 주장한다''에 딱 맞아요.", "examples": [{"type": "w", "text": "Some people argue that technology makes us lazy."}, {"type": "s", "text": "I believe it''s important to travel when you''re young."}], "mistake": "argue를 ''말다툼하다''로만 알면 에세이에서 못 써요.", "pron": {"word": "argue", "ipa": "/ˈɑːɡjuː/", "youglish": "https://youglish.com/pronounce/argue%20that/english", "dict": "https://dictionary.cambridge.org/dictionary/english/argue"}}, {"en": "many people → a large number of people", "ko": "많은 사람들", "usage": "a large number of + 복수 명사 + 복수 동사. 셀 수 없는 명사엔 a large amount of.", "examples": [{"type": "w", "text": "A large number of people now work from home."}, {"type": "s", "text": "A lot of people in my office work from home. (말할 땐 a lot of)"}], "mistake": "✗ a large number of money → a large amount of money", "pron": {"word": "number", "ipa": "/ˈnʌmbə(r)/", "youglish": "https://youglish.com/pronounce/a%20large%20number%20of/english", "dict": "https://dictionary.cambridge.org/dictionary/english/number"}}, {"en": "children → young people", "ko": "아이들 → 젊은이들", "usage": "young people / the younger generation으로 바꿔요. 아주 어린 아이라면 young children.", "examples": [{"type": "w", "text": "The younger generation spends more time online than ever before."}, {"type": "s", "text": "Young people in my country often live with their parents until they marry."}], "mistake": "✗ childs / ✗ young peoples", "pron": {"word": "generation", "ipa": "/ˌdʒenəˈreɪʃn/", "youglish": "https://youglish.com/pronounce/the%20younger%20generation/english", "dict": "https://dictionary.cambridge.org/dictionary/english/generation"}}, {"en": "increase → rise / grow", "ko": "증가하다", "usage": "rise·grow는 목적어 없이 써요. ''~을 올리다''는 raise. 명사: a rise in ~.", "examples": [{"type": "w", "text": "The number of cars on the roads has risen sharply."}, {"type": "s", "text": "Prices keep going up these days. (말할 땐 go up)"}], "mistake": "✗ rise the price → raise the price", "pron": {"word": "rise", "ipa": "/raɪz/", "youglish": "https://youglish.com/pronounce/has%20risen/english", "dict": "https://dictionary.cambridge.org/dictionary/english/rise"}}], "frame_tip": "서론에서 문제 문장을 바꿔 쓸 때 써요. 예: 문제 “Many people think children should learn a foreign language.” → It is often argued that young people should study a second language.", "extra": null}'::jsonb, quiz = '[{"q": "바꿔 쓰기: “Many people think ...” → It is often ______ that ...", "a": "argued"}, {"q": "틀린 곳 고치기: “The government should rise taxes.”", "a": "*raise* taxes"}, {"q": "틀린 곳 고치기: “A large number of money is spent on games.”", "a": "A large *amount* of money"}, {"q": "바꿔 쓰기: “Computers are very important for children.”", "a": "Computers are *essential* for *young people*."}]'::jsonb, model = '{"text": "문제 1: University education should be free for everyone.\n→ It is often argued that higher education should be available to all students at no cost.\n\n문제 2: Environmental problems are too big for individuals to solve.\n→ Some people believe that issues such as climate change and pollution are too serious to be solved by individuals alone.", "why": ["단어(university → higher education, free → at no cost)와 구조(It is often argued that) 둘 다 바꿨어요.", "environmental problems를 구체적인 예(climate change, pollution)로 풀어 썼어요.", "뜻은 그대로 유지했어요. 바꾸다가 뜻이 달라지면 오히려 감점이에요."]}'::jsonb, extras = '{"phrases": [{"en": "a growing number of ~", "ko": "점점 더 많은 ~", "example": "A growing number of people are working from home.", "youglish": "https://youglish.com/pronounce/a%20growing%20number%20of/english"}, {"en": "these days / nowadays", "ko": "요즘 (today 대신)", "example": "These days, most people own a smartphone.", "youglish": "https://youglish.com/pronounce/these%20days/english"}, {"en": "has a negative effect on ~", "ko": "~에 부정적 영향을 미치다 (bad for 대신)", "example": "Stress has a negative effect on health.", "youglish": "https://youglish.com/pronounce/has%20a%20negative%20effect%20on/english"}, {"en": "play an important role in ~", "ko": "~에서 중요한 역할을 하다", "example": "Parents play an important role in a child''s education.", "youglish": "https://youglish.com/pronounce/play%20an%20important%20role%20in/english"}, {"en": "in my view,", "ko": "내 생각에는 (In my opinion 대신)", "example": "In my view, governments should do more.", "youglish": "https://youglish.com/pronounce/in%20my%20view/english"}], "words": [{"en": "significant", "ipa": "/sɪɡˈnɪfɪkənt/", "ko": "상당한, 중요한 (big 대신)", "example": "There has been a significant increase in car use.", "youglish": "https://youglish.com/pronounce/significant/english", "dict": "https://dictionary.cambridge.org/dictionary/english/significant"}, {"en": "individual", "ipa": "/ˌɪndɪˈvɪdʒuəl/", "ko": "개인 (person 대신)", "example": "Every individual can help protect the environment.", "youglish": "https://youglish.com/pronounce/individual/english", "dict": "https://dictionary.cambridge.org/dictionary/english/individual"}, {"en": "beneficial", "ipa": "/ˌbenɪˈfɪʃl/", "ko": "이로운 (good 대신)", "example": "Regular exercise is beneficial for mental health.", "youglish": "https://youglish.com/pronounce/beneficial/english", "dict": "https://dictionary.cambridge.org/dictionary/english/beneficial"}, {"en": "decline", "ipa": "/dɪˈklaɪn/", "ko": "감소하다 (decrease 대신)", "example": "The number of smokers has declined.", "youglish": "https://youglish.com/pronounce/decline/english", "dict": "https://dictionary.cambridge.org/dictionary/english/decline"}, {"en": "numerous", "ipa": "/ˈnjuːmərəs/", "ko": "수많은 (many 대신)", "example": "There are numerous benefits to learning a language.", "youglish": "https://youglish.com/pronounce/numerous/english", "dict": "https://dictionary.cambridge.org/dictionary/english/numerous"}]}'::jsonb, todos = '[{"kind": "blog", "text": "바꿔 말하기 페이지는 글이 짧고 영상 중심이에요. 사이드바 영상만 보면 충분 (댓글 Q&A는 선택)", "url": "https://ieltsliz.com/ielts-vocabulary-paraphrasing-tips/", "minutes": 10}]'::jsonb where day = '2026-12-04';
update public.ielts_days set note = '{"summary": "Band 5와 6을 가르는 건 어려운 단어가 아니라 기본 표현을 안 틀리는 거예요. 오늘 5개는 채점관이 거의 매번 보는 실수들이에요.", "items": [{"en": "be detrimental to ~", "ko": "~에 해롭다", "usage": "격식 있는 표현이라 Writing용이에요. 전치사는 to.", "examples": [{"type": "w", "text": "Spending too much time online can be detrimental to children''s health."}, {"type": "s", "text": "Too much coffee is bad for you. (말할 땐 bad for)"}], "mistake": "✗ detrimental for → detrimental to", "pron": {"word": "detrimental", "ipa": "/ˌdetrɪˈmentl/", "youglish": "https://youglish.com/pronounce/be%20detrimental%20to/english", "dict": "https://dictionary.cambridge.org/dictionary/english/detrimental"}}, {"en": "a lack of + 명사", "ko": "~의 부족", "usage": "명사 lack은 a lack of. 동사 lack은 of 없이 바로 목적어: They lack money.", "examples": [{"type": "w", "text": "A lack of exercise is a major cause of obesity."}, {"type": "s", "text": "I feel tired because of a lack of sleep."}], "mistake": "✗ They lack of money. → They lack money.", "pron": {"word": "lack", "ipa": "/læk/", "youglish": "https://youglish.com/pronounce/a%20lack%20of/english", "dict": "https://dictionary.cambridge.org/dictionary/english/lack"}}, {"en": "be lacking in ~", "ko": "~이 부족하다", "usage": "be lacking in + 명사.", "examples": [{"type": "w", "text": "Many graduates are lacking in practical skills."}, {"type": "s", "text": "My hometown is lacking in things for young people to do."}], "mistake": "✗ lacking of → lacking in", "pron": {"word": "lacking", "ipa": "/ˈlækɪŋ/", "youglish": "https://youglish.com/pronounce/lacking%20in/english", "dict": "https://dictionary.cambridge.org/dictionary/english/lacking"}}, {"en": "information / advice / equipment", "ko": "불가산 명사 (-s 안 붙음)", "usage": "a/an도 안 붙여요. 셀 땐 a piece of advice / a piece of information.", "examples": [{"type": "w", "text": "Teachers should give students advice about their future careers."}, {"type": "s", "text": "I got some useful information from the website."}], "mistake": "✗ informations / ✗ an advice / ✗ equipments", "pron": {"word": "equipment", "ipa": "/ɪˈkwɪpmənt/", "youglish": "https://youglish.com/pronounce/useful%20information/english", "dict": "https://dictionary.cambridge.org/dictionary/english/equipment"}}, {"en": "common vs popular", "ko": "흔한 vs 인기 있는", "usage": "common = 자주 일어나는·흔한 (common problem), popular = 많은 사람이 좋아하는 (popular sport).", "examples": [{"type": "w", "text": "Obesity is becoming more common among children."}, {"type": "s", "text": "Hiking is very popular in Korea."}], "mistake": "✗ Back pain is popular among office workers. → common", "pron": {"word": "common", "ipa": "/ˈkɒmən/", "youglish": "https://youglish.com/pronounce/is%20becoming%20more%20common/english", "dict": "https://dictionary.cambridge.org/dictionary/english/common"}}], "frame_tip": "부정적 영향을 말하는 문장이에요. 같은 뜻의 다른 표현: has a negative effect on ...", "extra": null}'::jsonb, quiz = '[{"q": "틀린 곳 고치기: “He gave me many useful advices.”", "a": "He gave me *a lot of useful advice*."}, {"q": "전치사: Smoking is detrimental ___ your health.", "a": "to"}, {"q": "common / popular: “Back pain is very ______ among office workers.”", "a": "common"}, {"q": "틀린 곳 고치기: “Many students lack of motivation.”", "a": "Many students *lack motivation*."}]'::jsonb, model = '{"text": "이번 주에 자주 나올 만한 오류 고치기 예시:\n✗ One advantage of work from home is ... → ✓ One advantage of working from home is ...\n✗ I got many informations. → ✓ I got a lot of information.\n✗ Tuition fee is expensive. → ✓ Tuition fees are high.\n✗ Although it is cheap, but it is slow. → ✓ Although it is cheap, it is slow.", "why": ["오류는 대부분 네 가지 패턴이에요: 동명사(-ing), 불가산 명사, 복수형, Although + but.", "내 문장에서 이 네 가지만 확인해도 문법 점수가 확 올라가요.", "메모 칸에 ''내가 자주 틀리는 패턴''을 적어 두세요."]}'::jsonb, extras = '{"phrases": [{"en": "affect vs effect", "ko": "affect(동사) / effect(명사)", "example": "Stress can affect your health. It has a bad effect on your sleep.", "youglish": "https://youglish.com/pronounce/affect%20vs%20effect/english"}, {"en": "fewer vs less", "ko": "fewer + 복수 명사 / less + 불가산", "example": "There are fewer cars and less pollution.", "youglish": "https://youglish.com/pronounce/fewer%20vs%20less/english"}, {"en": "the number of vs a number of", "ko": "~의 수(단수 동사) / 몇몇의(복수 동사)", "example": "The number of students is rising. A number of students are absent.", "youglish": "https://youglish.com/pronounce/the%20number%20of%20vs%20a%20number%20of/english"}, {"en": "most people (✗ most of people)", "ko": "대부분의 사람들", "example": "Most people use social media every day.", "youglish": "https://youglish.com/pronounce/most%20people%20%28%E2%9C%97%20most%20of%20people%29/english"}, {"en": "each / every + 단수 명사", "ko": "각각의, 모든", "example": "Every student has a laptop.", "youglish": "https://youglish.com/pronounce/each/english"}], "words": [{"en": "accommodation", "ipa": "/əˌkɒməˈdeɪʃn/", "ko": "숙소 (영국식 불가산)", "example": "It is hard to find cheap accommodation in London.", "youglish": "https://youglish.com/pronounce/accommodation/english", "dict": "https://dictionary.cambridge.org/dictionary/english/accommodation"}, {"en": "furniture", "ipa": "/ˈfɜːnɪtʃə(r)/", "ko": "가구 (불가산)", "example": "We bought some new furniture for the living room.", "youglish": "https://youglish.com/pronounce/furniture/english", "dict": "https://dictionary.cambridge.org/dictionary/english/furniture"}, {"en": "research", "ipa": "/rɪˈsɜːtʃ/", "ko": "연구 (불가산)", "example": "More research is needed on this topic.", "youglish": "https://youglish.com/pronounce/research/english", "dict": "https://dictionary.cambridge.org/dictionary/english/research"}, {"en": "knowledge", "ipa": "/ˈnɒlɪdʒ/", "ko": "지식 (불가산)", "example": "Travelling increases your knowledge of other cultures.", "youglish": "https://youglish.com/pronounce/knowledge/english", "dict": "https://dictionary.cambridge.org/dictionary/english/knowledge"}, {"en": "traffic", "ipa": "/ˈtræfɪk/", "ko": "교통량 (불가산)", "example": "There is a lot of traffic in the city centre.", "youglish": "https://youglish.com/pronounce/traffic/english", "dict": "https://dictionary.cambridge.org/dictionary/english/traffic"}]}'::jsonb, todos = '[{"kind": "blog", "text": "detrimental 예문 6개 소리 내 읽기", "url": "https://ieltsliz.com/detrimental-vocabulary-sample-sentence/", "minutes": 5}, {"kind": "reading", "text": "GT Reading Test 1 — Section 2 (20분)", "url": "https://takeielts.britishcouncil.org/take-ielts/prepare/free-ielts-english-practice-tests/reading/general-training", "minutes": 20}]'::jsonb where day = '2026-12-05';
update public.ielts_days set note = '{"summary": "환경 에세이를 써 봐요. 이번 주 표현을 원인 → 해결 구조에 배치하면 돼요. 문제가 “To what extent do you agree?”라 입장(전부 동의 / 일부 동의 / 반대)을 서론에서 분명히 밝혀야 해요.", "items": [], "frame_tip": null, "extra": "*🧭 에세이 설계도*\n• *서론*: Nowadays, more and more people ... + Some people believe that ... + 입장 (I partly agree ...)\n• *본론 1 (정부가 필요한 이유)*: 원인 표현 (fossil fuels, greenhouse gas emissions) + Only governments can ...\n• *본론 2 (개인도 할 수 있는 것)*: 해결 표현 (use public transport, reduce waste) + One clear example is ...\n• *결론*: In conclusion, although ..., I believe that ...\n\n*✅ 2분 체크*\n• climate change 앞에 the 없나? • damage에 s 없나? • solution to? • take action (an 없이)?"}'::jsonb, quiz = null, model = '{"text": "Nowadays, more and more people are worried about environmental problems such as climate change and air pollution. Some people believe that these issues are too big for individuals to solve. I partly agree with this view, because governments must take the lead, but individuals also have an important role.\n\nOn the one hand, the main causes of environmental problems are too large for one person to control. For example, factories and power stations that burn fossil fuels produce a large amount of greenhouse gas emissions. Only governments can introduce laws to reduce these emissions and invest in renewable energy. Therefore, without government action, individual efforts will have a limited effect.\n\nOn the other hand, small actions by millions of people can make a real difference. If people use public transport instead of driving, there will be less air pollution in cities. In addition, people can reduce waste by recycling and avoiding plastic bags. One clear example is Korea, where strict recycling rules have changed people''s daily habits.\n\nIn conclusion, although governments must take action on large issues like climate change, I believe that individuals can also help to protect the environment. Both groups need to work together to solve these problems.", "why": ["서론에서 ''일부 동의(partly agree)'' 입장과 그 이유를 한 문장으로 밝혔어요.", "On the one hand / On the other hand로 두 측면을 나눴어요.", "이번 주 표현 10개 이상, 약 270단어예요."]}'::jsonb, extras = null, todos = null where day = '2026-12-06';
update public.ielts_days set note = '{"summary": "범죄 주제는 “감옥 vs 교화”, “처벌을 강화하면 범죄가 줄까?”가 단골이에요. 오늘은 기본 단어, 내일은 대안(예방·교화) 표현이에요.", "items": [{"en": "commit a crime", "ko": "범죄를 저지르다", "usage": "범죄는 do나 make가 아니라 commit과 짝이에요.", "examples": [{"type": "w", "text": "People who commit serious crimes should be sent to prison."}, {"type": "s", "text": "I don''t think poor people are more likely to commit crimes."}], "mistake": "✗ do a crime / ✗ make a crime", "pron": {"word": "commit", "ipa": "/kəˈmɪt/", "youglish": "https://youglish.com/pronounce/commit%20a%20crime/english", "dict": "https://dictionary.cambridge.org/dictionary/english/commit"}}, {"en": "the crime rate", "ko": "범죄율", "usage": "보통 the를 붙여요. rise / fall / reduce the crime rate.", "examples": [{"type": "w", "text": "Better street lighting can help reduce the crime rate."}, {"type": "s", "text": "The crime rate in my city is quite low, so I feel safe at night."}], "mistake": "✗ The crime rate is increased. → has increased / is rising", "pron": {"word": "rate", "ipa": "/reɪt/", "youglish": "https://youglish.com/pronounce/the%20crime%20rate/english", "dict": "https://dictionary.cambridge.org/dictionary/english/rate"}}, {"en": "be sent to prison", "ko": "감옥에 가다", "usage": "기관으로서의 prison에는 관사를 안 붙여요. go to prison도 OK.", "examples": [{"type": "w", "text": "Young offenders should not be sent to prison for minor crimes."}, {"type": "s", "text": "In crime dramas, the bad guy is usually sent to prison at the end."}], "mistake": "✗ sent to the prison (면회 가는 장소일 때만 the)", "pron": {"word": "prison", "ipa": "/ˈprɪzn/", "youglish": "https://youglish.com/pronounce/sent%20to%20prison/english", "dict": "https://dictionary.cambridge.org/dictionary/english/prison"}}, {"en": "reoffend", "ko": "재범하다", "usage": "목적어 없이 써요. 명사는 reoffending.", "examples": [{"type": "w", "text": "Many prisoners reoffend soon after they are released."}, {"type": "s", "text": "Some people commit another crime after they leave prison. (말할 땐 commit another crime)"}], "mistake": "✗ reoffend a crime → reoffend", "pron": {"word": "reoffend", "ipa": "/ˌriːəˈfend/", "youglish": "https://youglish.com/pronounce/reoffend/english", "dict": "https://dictionary.cambridge.org/dictionary/english/reoffend"}}, {"en": "a harsh punishment", "ko": "가혹한 처벌", "usage": "harsh / severe punishment, punishment for + 범죄.", "examples": [{"type": "w", "text": "Harsh punishments do not always stop people from committing crimes."}, {"type": "s", "text": "I think prison is too harsh a punishment for small crimes like shoplifting."}], "mistake": "✗ hard punishment (어색해요) → harsh / severe", "pron": {"word": "harsh", "ipa": "/hɑːʃ/", "youglish": "https://youglish.com/pronounce/harsh%20punishment/english", "dict": "https://dictionary.cambridge.org/dictionary/english/harsh"}}], "frame_tip": "근거를 댄 뒤 ''분명한 사실''을 강조할 때 써요. 근거 없이 남발하면 오히려 설득력이 떨어져요.", "extra": null}'::jsonb, quiz = '[{"q": "틀린 곳 고치기: “He did a crime when he was young.”", "a": "He *committed* a crime ..."}, {"q": "관사: “She was sent to ___ prison.” (a / the / 없음)", "a": "없음"}, {"q": "Many ex-prisoners ______ within two years. (재범하다)", "a": "reoffend"}, {"q": "형용사: “a ______ punishment” (hard / harsh)", "a": "harsh"}]'::jsonb, model = '{"text": "I do not think prison is always the best punishment for criminals. It is clear that people who commit serious crimes, such as murder, should be sent to prison. However, many prisoners reoffend after they are released, so other punishments may work better for minor crimes.", "why": ["입장 → 인정(It is clear that) → 반박(However) + 근거 순서예요.", "serious crimes와 minor crimes를 나눠서 균형 있게 답했어요.", "오늘 표현 3개를 자연스럽게 넣었어요."]}'::jsonb, extras = '{"phrases": [{"en": "break the law", "ko": "법을 어기다", "example": "People who break the law should be punished.", "youglish": "https://youglish.com/pronounce/break%20the%20law/english"}, {"en": "serve a sentence", "ko": "형을 살다", "example": "He is serving a five-year sentence for robbery.", "youglish": "https://youglish.com/pronounce/serve%20a%20sentence/english"}, {"en": "a minor crime / a serious crime", "ko": "경범죄 / 중범죄", "example": "Shoplifting is a minor crime, while murder is a serious crime.", "youglish": "https://youglish.com/pronounce/a%20minor%20crime/english"}, {"en": "be released from prison", "ko": "출소하다", "example": "Many people struggle to find work after they are released from prison.", "youglish": "https://youglish.com/pronounce/be%20released%20from%20prison/english"}, {"en": "a criminal record", "ko": "전과 기록", "example": "It is hard to get a job if you have a criminal record.", "youglish": "https://youglish.com/pronounce/a%20criminal%20record/english"}], "words": [{"en": "offence", "ipa": "/əˈfens/", "ko": "범죄, 위법 행위 (영국 철자)", "example": "Drink-driving is a serious offence.", "youglish": "https://youglish.com/pronounce/offence/english", "dict": "https://dictionary.cambridge.org/dictionary/english/offence"}, {"en": "victim", "ipa": "/ˈvɪktɪm/", "ko": "피해자", "example": "Victims of crime need support.", "youglish": "https://youglish.com/pronounce/victim/english", "dict": "https://dictionary.cambridge.org/dictionary/english/victim"}, {"en": "punishment", "ipa": "/ˈpʌnɪʃmənt/", "ko": "처벌", "example": "The punishment should fit the crime.", "youglish": "https://youglish.com/pronounce/punishment/english", "dict": "https://dictionary.cambridge.org/dictionary/english/punishment"}, {"en": "theft", "ipa": "/θeft/", "ko": "절도", "example": "Car theft has fallen in recent years.", "youglish": "https://youglish.com/pronounce/theft/english", "dict": "https://dictionary.cambridge.org/dictionary/english/theft"}, {"en": "justice", "ipa": "/ˈdʒʌstɪs/", "ko": "정의, 사법", "example": "The justice system should be fair to everyone.", "youglish": "https://youglish.com/pronounce/justice/english", "dict": "https://dictionary.cambridge.org/dictionary/english/justice"}]}'::jsonb, todos = '[{"kind": "blog", "text": "범죄 어휘(약 90개)를 섹션별 오디오와 함께 훑고, 빈칸 12문제 풀기", "url": "https://ieltsliz.com/crime-and-punishment-vocabulary/", "minutes": 20}]'::jsonb where day = '2026-12-07';
update public.ielts_days set note = '{"summary": "Task 2에서 “감옥 말고 대안은?”이 나오면 예방(교육·조명·CCTV)과 교화(사회봉사·직업훈련)를 쓰면 돼요.", "items": [{"en": "prevent crime", "ko": "범죄를 예방하다", "usage": "prevent + 명사 / prevent A from -ing.", "examples": [{"type": "w", "text": "Education is the best way to prevent crime among young people."}, {"type": "s", "text": "CCTV cameras help prevent crime in my neighbourhood."}], "mistake": "✗ prevent people to steal → prevent people from stealing", "pron": {"word": "prevent", "ipa": "/prɪˈvent/", "youglish": "https://youglish.com/pronounce/prevent%20crime/english", "dict": "https://dictionary.cambridge.org/dictionary/english/prevent"}}, {"en": "young offenders", "ko": "청소년 범죄자", "usage": "offender = 범죄자, offence = 범죄 (영국 철자).", "examples": [{"type": "w", "text": "Young offenders should be given a second chance."}, {"type": "s", "text": "I think young offenders need help more than punishment."}], "mistake": "offender(사람)와 offence(범죄)를 헷갈리지 마세요.", "pron": {"word": "offenders", "ipa": "/əˈfendəz/", "youglish": "https://youglish.com/pronounce/young%20offenders/english", "dict": "https://dictionary.cambridge.org/dictionary/english/offenders"}}, {"en": "community service", "ko": "사회봉사 명령", "usage": "셀 수 없는 명사. do community service.", "examples": [{"type": "w", "text": "Community service allows offenders to give something back to society."}, {"type": "s", "text": "In my country, people caught drink-driving sometimes have to do community service."}], "mistake": "✗ a community service / 동사는 do", "pron": {"word": "community", "ipa": "/kəˈmjuːnəti/", "youglish": "https://youglish.com/pronounce/community%20service/english", "dict": "https://dictionary.cambridge.org/dictionary/english/community"}}, {"en": "rehabilitation", "ko": "교화, 사회 복귀", "usage": "셀 수 없는 명사. rehabilitation programmes.", "examples": [{"type": "w", "text": "Prisons should focus on rehabilitation rather than punishment."}, {"type": "s", "text": "I think rehabilitation is more important than punishment."}], "mistake": "철자 주의: re-ha-bi-li-ta-tion", "pron": {"word": "rehabilitation", "ipa": "/ˌriːəˌbɪlɪˈteɪʃn/", "youglish": "https://youglish.com/pronounce/rehabilitation/english", "dict": "https://dictionary.cambridge.org/dictionary/english/rehabilitation"}}, {"en": "deter people from ~ing", "ko": "~하지 못하게 막다", "usage": "deter + 사람 + from + -ing.", "examples": [{"type": "w", "text": "Heavy fines may deter people from driving too fast."}, {"type": "s", "text": "Speed cameras really deter people from speeding."}], "mistake": "✗ deter people to → from + -ing", "pron": {"word": "deter", "ipa": "/dɪˈtɜː(r)/", "youglish": "https://youglish.com/pronounce/deter%20people%20from/english", "dict": "https://dictionary.cambridge.org/dictionary/english/deter"}}], "frame_tip": "기존 방식 대신 대안을 제시할 때 써요. Instead of 뒤에는 명사나 -ing가 와요.", "extra": null}'::jsonb, quiz = '[{"q": "전치사: Cameras deter people ___ committing crimes.", "a": "from"}, {"q": "틀린 곳 고치기: “Instead of send them to prison, ...”", "a": "Instead of *sending* them ..."}, {"q": "He had to do 100 hours of ______ ______. (사회봉사)", "a": "community service"}, {"q": "Prisons should focus on r____________ rather than punishment.", "a": "rehabilitation"}]'::jsonb, model = '{"text": "Instead of building more prisons, governments should spend money on education and job training to prevent crime. In addition, young offenders could do community service, which teaches them responsibility and may deter them from reoffending.", "why": ["Instead of로 대안을 제시하고, 구체적인 방법(education, job training)을 썼어요.", "which로 그 결과(책임감, 재범 방지)까지 연결했어요.", "어제 표현 reoffend를 재활용했어요."]}'::jsonb, extras = '{"phrases": [{"en": "give someone a second chance", "ko": "~에게 다시 기회를 주다", "example": "Young offenders deserve a second chance.", "youglish": "https://youglish.com/pronounce/give%20someone%20a%20second%20chance/english"}, {"en": "get into trouble", "ko": "말썽을 일으키다, 곤란해지다", "example": "Teenagers with nothing to do may get into trouble.", "youglish": "https://youglish.com/pronounce/get%20into%20trouble/english"}, {"en": "job training", "ko": "직업 훈련", "example": "Job training helps prisoners find work after release.", "youglish": "https://youglish.com/pronounce/job%20training/english"}, {"en": "the root causes of crime", "ko": "범죄의 근본 원인", "example": "We need to tackle the root causes of crime, such as poverty.", "youglish": "https://youglish.com/pronounce/the%20root%20causes%20of%20crime/english"}, {"en": "peer pressure", "ko": "또래 압력", "example": "Peer pressure can lead teenagers to commit crimes.", "youglish": "https://youglish.com/pronounce/peer%20pressure/english"}], "words": [{"en": "poverty", "ipa": "/ˈpɒvəti/", "ko": "가난", "example": "Poverty is one of the main causes of crime.", "youglish": "https://youglish.com/pronounce/poverty/english", "dict": "https://dictionary.cambridge.org/dictionary/english/poverty"}, {"en": "deterrent", "ipa": "/dɪˈterənt/", "ko": "억지책, 범죄를 막는 것", "example": "Heavy fines act as a deterrent.", "youglish": "https://youglish.com/pronounce/deterrent/english", "dict": "https://dictionary.cambridge.org/dictionary/english/deterrent"}, {"en": "fine", "ipa": "/faɪn/", "ko": "벌금; 벌금을 물리다", "example": "He was fined for driving too fast.", "youglish": "https://youglish.com/pronounce/fine/english", "dict": "https://dictionary.cambridge.org/dictionary/english/fine"}, {"en": "juvenile", "ipa": "/ˈdʒuːvənaɪl/", "ko": "청소년의 (격식)", "example": "Juvenile crime has increased in some areas.", "youglish": "https://youglish.com/pronounce/juvenile/english", "dict": "https://dictionary.cambridge.org/dictionary/english/juvenile"}, {"en": "reform", "ipa": "/rɪˈfɔːm/", "ko": "개혁; 개선하다", "example": "Prison reform is needed to reduce reoffending.", "youglish": "https://youglish.com/pronounce/reform/english", "dict": "https://dictionary.cambridge.org/dictionary/english/reform"}]}'::jsonb, todos = '[{"kind": "blog", "text": "범죄 어휘 빈칸 7문제 풀기 (오늘 미션)", "url": "https://ieltsliz.com/crime-vocabulary-exercise/", "minutes": 10}]'::jsonb where day = '2026-12-08';
update public.ielts_days set note = '{"summary": "“정부가 돈을 어디에 써야 하나?”(의료 vs 예술, 대중교통, 우주 개발)는 단골 유형이에요. 오늘 표현은 다른 주제에도 계속 재활용돼요.", "items": [{"en": "government spending", "ko": "정부 지출", "usage": "셀 수 없는 명사. increase / cut government spending on ~.", "examples": [{"type": "w", "text": "Government spending on healthcare should be a top priority."}, {"type": "s", "text": "I think government spending on parks is a good idea."}], "mistake": "✗ government spendings", "pron": {"word": "government", "ipa": "/ˈɡʌvənmənt/", "youglish": "https://youglish.com/pronounce/government%20spending/english", "dict": "https://dictionary.cambridge.org/dictionary/english/government"}}, {"en": "public services", "ko": "공공 서비스", "usage": "의료·교육·교통 등을 묶어 말할 땐 복수형이에요.", "examples": [{"type": "w", "text": "Higher taxes can pay for better public services."}, {"type": "s", "text": "Public services in Korea are quite efficient, like the subway and hospitals."}], "mistake": "발음: services /ˈsɜːvɪsɪz/", "pron": {"word": "services", "ipa": "/ˈsɜːvɪsɪz/", "youglish": "https://youglish.com/pronounce/public%20services/english", "dict": "https://dictionary.cambridge.org/dictionary/english/services"}}, {"en": "raise taxes", "ko": "세금을 올리다", "usage": "raise는 목적어가 필요한 동사. 반대는 cut / lower taxes.", "examples": [{"type": "w", "text": "Governments may need to raise taxes to pay for free education."}, {"type": "s", "text": "Nobody likes it when the government raises taxes."}], "mistake": "✗ rise taxes → raise taxes", "pron": {"word": "taxes", "ipa": "/ˈtæksɪz/", "youglish": "https://youglish.com/pronounce/raise%20taxes/english", "dict": "https://dictionary.cambridge.org/dictionary/english/taxes"}}, {"en": "be funded by the government", "ko": "정부 지원을 받다", "usage": "be funded by + 주체.", "examples": [{"type": "w", "text": "Museums should be funded by the government so that everyone can visit for free."}, {"type": "s", "text": "My university was partly funded by the government."}], "mistake": "✗ funded from the government → by", "pron": {"word": "funded", "ipa": "/ˈfʌndɪd/", "youglish": "https://youglish.com/pronounce/funded%20by%20the%20government/english", "dict": "https://dictionary.cambridge.org/dictionary/english/funded"}}, {"en": "introduce a law", "ko": "법을 도입하다", "usage": "introduce / pass a law, a law on / against ~.", "examples": [{"type": "w", "text": "The government should introduce a law to ban smoking in public places."}, {"type": "s", "text": "They should introduce stricter laws against drink-driving."}], "mistake": "make a law도 통하지만 introduce / pass가 더 정확해요.", "pron": {"word": "law", "ipa": "/lɔː/", "youglish": "https://youglish.com/pronounce/introduce%20a%20law/english", "dict": "https://dictionary.cambridge.org/dictionary/english/law"}}], "frame_tip": "책임 주체를 밝히는 문장이에요. be responsible for + 명사/-ing.", "extra": null}'::jsonb, quiz = '[{"q": "틀린 곳 고치기: “Free museums should be funded from the government.”", "a": "funded *by* the government"}, {"q": "The government plans to ______ a new law on recycling.", "a": "introduce"}, {"q": "틀린 곳 고치기: “Government spendings on roads have increased.”", "a": "Government *spending* on roads *has* increased."}, {"q": "The government should be responsible ___ public transport.", "a": "for"}]'::jsonb, model = '{"text": "In my opinion, the government should spend more money on healthcare than on the arts. Healthcare is a basic public service, and everyone needs it at some point in their lives. Although the arts are important, they can also be funded by private companies and ticket sales.", "why": ["비교 질문에 ''어느 쪽''인지 분명히 답했어요.", "Although로 반대쪽(예술)의 가치를 인정하고 대안(민간 후원)까지 제시했어요.", "오늘 표현 2개 + 지난주 Although를 활용했어요."]}'::jsonb, extras = '{"phrases": [{"en": "allocate funds to ~", "ko": "~에 예산을 배정하다", "example": "The government should allocate more funds to education.", "youglish": "https://youglish.com/pronounce/allocate%20funds%20to/english"}, {"en": "the public sector / the private sector", "ko": "공공 부문 / 민간 부문", "example": "Many graduates want to work in the public sector.", "youglish": "https://youglish.com/pronounce/the%20public%20sector/english"}, {"en": "a waste of money", "ko": "돈 낭비", "example": "Some people think space exploration is a waste of money.", "youglish": "https://youglish.com/pronounce/a%20waste%20of%20money/english"}, {"en": "the taxpayer", "ko": "납세자 (세금을 내는 국민)", "example": "The new stadium was paid for by the taxpayer.", "youglish": "https://youglish.com/pronounce/the%20taxpayer/english"}, {"en": "a top priority", "ko": "최우선 순위", "example": "Healthcare should be a top priority for the government.", "youglish": "https://youglish.com/pronounce/a%20top%20priority/english"}], "words": [{"en": "budget", "ipa": "/ˈbʌdʒɪt/", "ko": "예산", "example": "The education budget has been cut again.", "youglish": "https://youglish.com/pronounce/budget/english", "dict": "https://dictionary.cambridge.org/dictionary/english/budget"}, {"en": "infrastructure", "ipa": "/ˈɪnfrəstrʌktʃə(r)/", "ko": "사회 기반 시설", "example": "Good infrastructure attracts foreign companies.", "youglish": "https://youglish.com/pronounce/infrastructure/english", "dict": "https://dictionary.cambridge.org/dictionary/english/infrastructure"}, {"en": "policy", "ipa": "/ˈpɒləsi/", "ko": "정책", "example": "The new policy aims to reduce unemployment.", "youglish": "https://youglish.com/pronounce/policy/english", "dict": "https://dictionary.cambridge.org/dictionary/english/policy"}, {"en": "citizen", "ipa": "/ˈsɪtɪzn/", "ko": "시민", "example": "Every citizen has the right to free education.", "youglish": "https://youglish.com/pronounce/citizen/english", "dict": "https://dictionary.cambridge.org/dictionary/english/citizen"}, {"en": "subsidise", "ipa": "/ˈsʌbsɪdaɪz/", "ko": "보조금을 주다", "example": "The government subsidises public transport.", "youglish": "https://youglish.com/pronounce/subsidise/english", "dict": "https://dictionary.cambridge.org/dictionary/english/subsidise"}]}'::jsonb, todos = '[{"kind": "blog", "text": "Speaking 질문 4개의 모범 답안 읽기 + Task 2 문제 7개 중 하나 골라 개요만 짜기", "url": "https://ieltsliz.com/government-vocabulary-word-lists/", "minutes": 15}, {"kind": "reading", "text": "GT Reading Test 1 — Section 3 (20분)", "url": "https://takeielts.britishcouncil.org/take-ielts/prepare/free-ielts-english-practice-tests/reading/general-training", "minutes": 20}]'::jsonb where day = '2026-12-09';
update public.ielts_days set note = '{"summary": "건강 주제는 “개인 책임 vs 정부 책임” 비교가 핵심이에요. Discuss both views 문제로 많이 나와서 양쪽 표현이 다 필요해요.", "items": [{"en": "healthcare system", "ko": "의료 제도", "usage": "healthcare는 한 단어로 써요.", "examples": [{"type": "w", "text": "A good healthcare system should be available to everyone."}, {"type": "s", "text": "I think the healthcare system in Korea is quite good and affordable."}], "mistake": "✗ medical system (어색해요) → healthcare system", "pron": {"word": "healthcare", "ipa": "/ˈhelθkeə(r)/", "youglish": "https://youglish.com/pronounce/healthcare%20system/english", "dict": "https://dictionary.cambridge.org/dictionary/english/healthcare"}}, {"en": "free healthcare", "ko": "무상 의료", "usage": "셀 수 없는 명사. provide free healthcare.", "examples": [{"type": "w", "text": "Free healthcare is expensive, but it protects the poorest people in society."}, {"type": "s", "text": "In the UK, people get free healthcare from the NHS."}], "mistake": "✗ free of healthcare", "pron": {"word": null, "ipa": null, "youglish": "https://youglish.com/pronounce/free%20healthcare/english", "dict": null}}, {"en": "lead a healthy lifestyle", "ko": "건강한 생활을 하다", "usage": "lead / have / live a healthy lifestyle.", "examples": [{"type": "w", "text": "Schools should teach children how to lead a healthy lifestyle."}, {"type": "s", "text": "I try to lead a healthy lifestyle, but it''s hard with my busy schedule."}], "mistake": "✗ do a healthy life", "pron": {"word": "lifestyle", "ipa": "/ˈlaɪfstaɪl/", "youglish": "https://youglish.com/pronounce/healthy%20lifestyle/english", "dict": "https://dictionary.cambridge.org/dictionary/english/lifestyle"}}, {"en": "take regular exercise", "ko": "규칙적으로 운동하다", "usage": "영국식 take exercise, 미국식 get exercise. exercise는 셀 수 없는 명사로 써요.", "examples": [{"type": "w", "text": "People who take regular exercise are less likely to get heart disease."}, {"type": "s", "text": "I try to get some exercise three times a week."}], "mistake": "✗ take regular exercises", "pron": {"word": "exercise", "ipa": "/ˈeksəsaɪz/", "youglish": "https://youglish.com/pronounce/regular%20exercise/english", "dict": "https://dictionary.cambridge.org/dictionary/english/exercise"}}, {"en": "junk food", "ko": "정크푸드", "usage": "셀 수 없는 명사예요. eat too much junk food.", "examples": [{"type": "w", "text": "Junk food advertising should be banned during children''s TV programmes."}, {"type": "s", "text": "I eat junk food when I''m stressed, like fried chicken."}], "mistake": "✗ junk foods / ✗ too many junk food → too much", "pron": {"word": "junk", "ipa": "/dʒʌŋk/", "youglish": "https://youglish.com/pronounce/junk%20food/english", "dict": "https://dictionary.cambridge.org/dictionary/english/junk"}}], "frame_tip": "양쪽 모두에게 책임이 있다고 말할 때 써요. A as well as B가 주어면 동사는 A에 맞춰요.", "extra": null}'::jsonb, quiz = '[{"q": "틀린 곳 고치기: “People should take regular exercises.”", "a": "regular *exercise*"}, {"q": "It''s hard to ______ a healthy lifestyle when you work long hours.", "a": "lead"}, {"q": "틀린 곳 고치기: “Children eat too many junk foods.”", "a": "Children eat *too much junk food*."}, {"q": "한 단어로: 국가의 의료 서비스 체계 = the ______ system", "a": "healthcare"}]'::jsonb, model = '{"text": "Some people believe that individuals are responsible for their own health. They argue that people can choose to take regular exercise and avoid junk food.\n\nOn the other hand, others believe that governments should take responsibility. They argue that free healthcare and laws against unhealthy food advertising can protect everyone, especially the poor.", "why": ["양쪽 의견을 각각 2문장씩, 주장 + 근거(They argue that)로 썼어요.", "On the other hand로 입장을 전환했어요.", "Discuss both views 에세이의 본론 두 문단 뼈대 그대로예요."]}'::jsonb, extras = '{"phrases": [{"en": "stay in shape", "ko": "몸매·건강을 유지하다", "example": "I go swimming twice a week to stay in shape.", "youglish": "https://youglish.com/pronounce/stay%20in%20shape/english"}, {"en": "a balanced diet", "ko": "균형 잡힌 식단", "example": "A balanced diet includes fruit, vegetables and protein.", "youglish": "https://youglish.com/pronounce/a%20balanced%20diet/english"}, {"en": "a sedentary lifestyle", "ko": "앉아서 지내는 생활 방식", "example": "Office workers often have a sedentary lifestyle.", "youglish": "https://youglish.com/pronounce/a%20sedentary%20lifestyle/english"}, {"en": "put on weight", "ko": "살이 찌다", "example": "I put on weight when I stopped exercising.", "youglish": "https://youglish.com/pronounce/put%20on%20weight/english"}, {"en": "prevention is better than cure", "ko": "예방이 치료보다 낫다", "example": "Governments should remember that prevention is better than cure.", "youglish": "https://youglish.com/pronounce/prevention%20is%20better%20than%20cure/english"}], "words": [{"en": "obesity", "ipa": "/əʊˈbiːsəti/", "ko": "비만", "example": "Childhood obesity is rising in many countries.", "youglish": "https://youglish.com/pronounce/obesity/english", "dict": "https://dictionary.cambridge.org/dictionary/english/obesity"}, {"en": "nutrition", "ipa": "/njuˈtrɪʃn/", "ko": "영양", "example": "Schools should teach children about nutrition.", "youglish": "https://youglish.com/pronounce/nutrition/english", "dict": "https://dictionary.cambridge.org/dictionary/english/nutrition"}, {"en": "life expectancy", "ipa": "/laɪf ɪkˈspektənsi/", "ko": "기대 수명", "example": "Life expectancy in Korea is over 80 years.", "youglish": "https://youglish.com/pronounce/life%20expectancy/english", "dict": "https://dictionary.cambridge.org/dictionary/english/life-expectancy"}, {"en": "well-being", "ipa": "/ˌwelˈbiːɪŋ/", "ko": "건강, 행복, 복지", "example": "Exercise is good for both physical and mental well-being.", "youglish": "https://youglish.com/pronounce/well-being/english", "dict": "https://dictionary.cambridge.org/dictionary/english/well-being"}, {"en": "chronic", "ipa": "/ˈkrɒnɪk/", "ko": "만성의", "example": "Smoking can cause chronic diseases.", "youglish": "https://youglish.com/pronounce/chronic/english", "dict": "https://dictionary.cambridge.org/dictionary/english/chronic"}]}'::jsonb, todos = '[{"kind": "blog", "text": "Task 2 허브의 ''모범 에세이'' 목록에서 건강 주제 에세이 1편 읽기", "url": "https://ieltsliz.com/ielts-writing-task-2/", "minutes": 15}]'::jsonb where day = '2026-12-10';
update public.ielts_days set note = '{"summary": "광고 주제는 “아이 대상 광고를 금지해야 하나?”, “광고가 불필요한 소비를 부추기나?”가 대표 문제예요.", "items": [{"en": "an advertising campaign", "ko": "광고 캠페인", "usage": "advertising = 광고 활동(셀 수 없음), advertisement / ad = 광고 한 편(셀 수 있음).", "examples": [{"type": "w", "text": "The company launched a large advertising campaign on social media."}, {"type": "s", "text": "I remember a really funny advertising campaign for a coffee brand."}], "mistake": "✗ an advertising (광고 한 편) → an advertisement", "pron": {"word": "advertising", "ipa": "/ˈædvətaɪzɪŋ/", "youglish": "https://youglish.com/pronounce/advertising%20campaign/english", "dict": "https://dictionary.cambridge.org/dictionary/english/advertising"}}, {"en": "target children", "ko": "아이들을 겨냥하다", "usage": "target은 바로 목적어. 수동태: be aimed at / be targeted at.", "examples": [{"type": "w", "text": "Many fast food companies target children with toys and cartoons."}, {"type": "s", "text": "I think a lot of mobile games target children."}], "mistake": "✗ target to children → target children", "pron": {"word": "target", "ipa": "/ˈtɑːɡɪt/", "youglish": "https://youglish.com/pronounce/target%20children/english", "dict": "https://dictionary.cambridge.org/dictionary/english/target"}}, {"en": "persuade people to buy", "ko": "사람들에게 사도록 설득하다", "usage": "persuade + 사람 + to + 동사.", "examples": [{"type": "w", "text": "Advertisements often persuade people to buy things they do not need."}, {"type": "s", "text": "Online ads sometimes persuade me to buy clothes I don''t need."}], "mistake": "✗ persuade people buying → to buy", "pron": {"word": "persuade", "ipa": "/pəˈsweɪd/", "youglish": "https://youglish.com/pronounce/persuade%20people%20to%20buy/english", "dict": "https://dictionary.cambridge.org/dictionary/english/persuade"}}, {"en": "consumers", "ko": "소비자", "usage": "consumer = 소비자 일반, customer = 가게·회사의 손님.", "examples": [{"type": "w", "text": "Consumers should be protected from false information."}, {"type": "s", "text": "As a consumer, I always read reviews before I buy something."}], "mistake": "consumer와 customer를 구분해서 써요.", "pron": {"word": "consumers", "ipa": "/kənˈsjuːməz/", "youglish": "https://youglish.com/pronounce/consumers/english", "dict": "https://dictionary.cambridge.org/dictionary/english/consumers"}}, {"en": "misleading advertisements", "ko": "오해를 부르는 광고", "usage": "misleading = 사실과 다르게 믿게 만드는.", "examples": [{"type": "w", "text": "Misleading advertisements should be banned by law."}, {"type": "s", "text": "I''ve seen some misleading advertisements for diet products."}], "mistake": "발음: /ˌmɪsˈliːdɪŋ/ (미스-리-딩)", "pron": {"word": "misleading", "ipa": "/ˌmɪsˈliːdɪŋ/", "youglish": "https://youglish.com/pronounce/misleading%20advertisements/english", "dict": "https://dictionary.cambridge.org/dictionary/english/misleading"}}], "frame_tip": "앞 문장의 이유를 설명할 때 써요. This is because + 주어 + 동사. (because of + 명사와 헷갈리지 마세요)", "extra": null}'::jsonb, quiz = '[{"q": "틀린 곳 고치기: “Ads persuade people buying unnecessary things.”", "a": "persuade people *to buy*"}, {"q": "advertising / advertisement: “I saw a funny ______ on TV.”", "a": "advertisement"}, {"q": "틀린 곳 고치기: “This is because of children believe ads.”", "a": "This is *because* children believe ads."}, {"q": "Many toy companies ______ children directly.", "a": "target"}]'::jsonb, model = '{"text": "I believe that advertising aimed at children should be banned. This is because young children cannot tell the difference between information and misleading advertisements. As a result, companies can easily persuade them to want unhealthy food and expensive toys.", "why": ["입장 → 이유(This is because) → 결과(As a result) 3단 구조예요.", "aimed at children으로 target을 바꿔 썼어요 (같은 단어 반복 피하기).", "어휘가 쉬워도 논리 연결이 분명하면 Band 6에 가까워요."]}'::jsonb, extras = '{"phrases": [{"en": "brand loyalty", "ko": "브랜드 충성도", "example": "Companies try to build brand loyalty from a young age.", "youglish": "https://youglish.com/pronounce/brand%20loyalty/english"}, {"en": "impulse buying", "ko": "충동구매", "example": "Online ads encourage impulse buying.", "youglish": "https://youglish.com/pronounce/impulse%20buying/english"}, {"en": "on sale", "ko": "할인 중인", "example": "I only buy clothes when they are on sale.", "youglish": "https://youglish.com/pronounce/on%20sale/english"}, {"en": "a must-have item", "ko": "꼭 가져야 할 물건", "example": "Ads make every new phone look like a must-have item.", "youglish": "https://youglish.com/pronounce/a%20must-have%20item/english"}, {"en": "value for money", "ko": "가격 대비 가치, 가성비", "example": "This laptop is good value for money.", "youglish": "https://youglish.com/pronounce/value%20for%20money/english"}], "words": [{"en": "commercial", "ipa": "/kəˈmɜːʃl/", "ko": "(TV·라디오) 광고 방송", "example": "I usually skip the commercials on YouTube.", "youglish": "https://youglish.com/pronounce/commercial/english", "dict": "https://dictionary.cambridge.org/dictionary/english/commercial"}, {"en": "materialistic", "ipa": "/məˌtɪəriəˈlɪstɪk/", "ko": "물질만능주의의", "example": "Advertising makes society more materialistic.", "youglish": "https://youglish.com/pronounce/materialistic/english", "dict": "https://dictionary.cambridge.org/dictionary/english/materialistic"}, {"en": "influence", "ipa": "/ˈɪnfluəns/", "ko": "영향을 미치다", "example": "Celebrities influence what young people buy.", "youglish": "https://youglish.com/pronounce/influence/english", "dict": "https://dictionary.cambridge.org/dictionary/english/influence"}, {"en": "sponsor", "ipa": "/ˈspɒnsə(r)/", "ko": "후원하다; 후원자", "example": "Many sports events are sponsored by big companies.", "youglish": "https://youglish.com/pronounce/sponsor/english", "dict": "https://dictionary.cambridge.org/dictionary/english/sponsor"}, {"en": "endorse", "ipa": "/ɪnˈdɔːs/", "ko": "(유명인이 상품을) 광고·보증하다", "example": "Famous athletes often endorse sports brands.", "youglish": "https://youglish.com/pronounce/endorse/english", "dict": "https://dictionary.cambridge.org/dictionary/english/endorse"}]}'::jsonb, todos = '[{"kind": "blog", "text": "광고 어휘 발음 오디오 듣기 + 빈칸 7문제 풀기", "url": "https://ieltsliz.com/advertising-vocabulary-and-pronunciation/", "minutes": 15}]'::jsonb where day = '2026-12-11';
update public.ielts_days set note = '{"summary": "뉴스·미디어는 Speaking Part 1(“뉴스를 어떻게 보세요?”)과 Task 2(“종이 신문은 사라질까?”, “가짜 뉴스”) 모두에 나와요.", "items": [{"en": "read the news online", "ko": "온라인으로 뉴스를 보다", "usage": "news는 -s로 끝나도 단수 취급: The news is ...", "examples": [{"type": "w", "text": "Most young people now read the news online rather than in newspapers."}, {"type": "s", "text": "I usually read the news online on my way to work."}], "mistake": "✗ The news are ... / ✗ a news", "pron": {"word": "news", "ipa": "/njuːz/", "youglish": "https://youglish.com/pronounce/read%20the%20news%20online/english", "dict": "https://dictionary.cambridge.org/dictionary/english/news"}}, {"en": "a reliable source", "ko": "신뢰할 만한 출처", "usage": "a reliable source of information / news.", "examples": [{"type": "w", "text": "Students should learn how to check whether a website is a reliable source."}, {"type": "s", "text": "I think public broadcasters are usually a reliable source of news."}], "mistake": "발음: reliable /rɪˈlaɪəbl/ (릴라이어블)", "pron": {"word": "reliable", "ipa": "/rɪˈlaɪəbl/", "youglish": "https://youglish.com/pronounce/reliable%20source/english", "dict": "https://dictionary.cambridge.org/dictionary/english/reliable"}}, {"en": "fake news", "ko": "가짜 뉴스", "usage": "셀 수 없는 명사. spread fake news.", "examples": [{"type": "w", "text": "Social media allows fake news to spread very quickly."}, {"type": "s", "text": "I sometimes see fake news on YouTube."}], "mistake": "✗ a fake news → a fake news story / some fake news", "pron": {"word": "fake", "ipa": "/feɪk/", "youglish": "https://youglish.com/pronounce/fake%20news/english", "dict": "https://dictionary.cambridge.org/dictionary/english/fake"}}, {"en": "keep up with current affairs", "ko": "시사를 놓치지 않다", "usage": "current affairs는 항상 복수형이에요.", "examples": [{"type": "w", "text": "It is important for citizens to keep up with current affairs."}, {"type": "s", "text": "I listen to podcasts to keep up with current affairs."}], "mistake": "✗ current affair", "pron": {"word": "affairs", "ipa": "/əˈfeəz/", "youglish": "https://youglish.com/pronounce/current%20affairs/english", "dict": "https://dictionary.cambridge.org/dictionary/english/affairs"}}, {"en": "headlines", "ko": "헤드라인, 주요 뉴스", "usage": "셀 수 있는 명사. check / read the headlines, hit the headlines (뉴스가 되다).", "examples": [{"type": "w", "text": "Many people only read the headlines and not the full story."}, {"type": "s", "text": "I usually just check the headlines in the morning."}], "mistake": "the headlines = 그날의 주요 뉴스 (관용적으로 복수)", "pron": {"word": "headlines", "ipa": "/ˈhedlaɪnz/", "youglish": "https://youglish.com/pronounce/headlines/english", "dict": "https://dictionary.cambridge.org/dictionary/english/headlines"}}], "frame_tip": "두 가지 장점을 한 문장에 담을 때 써요. Band 5~6에선 문장 중간에 쓰는 게 안전해요: Online news is not only fast but also free. (문장 맨 앞에 Not only를 쓰면 어순이 바뀌어 어려워요)", "extra": null}'::jsonb, quiz = '[{"q": "틀린 곳 고치기: “The news are very depressing today.”", "a": "The news *is* ..."}, {"q": "틀린 곳 고치기: “I read a fake news yesterday.”", "a": "I read *a fake news story* / *some fake news* yesterday."}, {"q": "I listen to the radio to keep up with current ______.", "a": "affairs"}, {"q": "Online news is not only fast ___ ___ free.", "a": "but also"}]'::jsonb, model = '{"text": "Q: How do you usually get the news?\nA: I usually read the news online, mostly on my phone. In the morning I check the headlines on a news app, and sometimes I watch short clips on YouTube. I try to stick to reliable sources, because there''s a lot of fake news on social media these days.", "why": ["방법(online) → 구체적 습관(morning, headlines) → 태도(reliable sources) 순이에요.", "because로 이유를 하나 붙이면 답이 자연스럽게 길어져요.", "Part 1 적정 길이(3~4문장)예요."]}'::jsonb, extras = '{"phrases": [{"en": "breaking news", "ko": "속보", "example": "I saw the breaking news on my phone.", "youglish": "https://youglish.com/pronounce/breaking%20news/english"}, {"en": "a news outlet", "ko": "언론사", "example": "Many news outlets now publish stories online first.", "youglish": "https://youglish.com/pronounce/a%20news%20outlet/english"}, {"en": "follow the news", "ko": "뉴스를 챙겨 보다", "example": "I don''t follow the news very closely.", "youglish": "https://youglish.com/pronounce/follow%20the%20news/english"}, {"en": "freedom of the press", "ko": "언론의 자유", "example": "Freedom of the press is important in a democracy.", "youglish": "https://youglish.com/pronounce/freedom%20of%20the%20press/english"}, {"en": "spread rumours", "ko": "소문을 퍼뜨리다", "example": "Social media makes it easy to spread rumours.", "youglish": "https://youglish.com/pronounce/spread%20rumours/english"}], "words": [{"en": "journalist", "ipa": "/ˈdʒɜːnəlɪst/", "ko": "기자", "example": "Journalists should check their facts carefully.", "youglish": "https://youglish.com/pronounce/journalist/english", "dict": "https://dictionary.cambridge.org/dictionary/english/journalist"}, {"en": "biased", "ipa": "/ˈbaɪəst/", "ko": "편향된", "example": "Some newspapers are politically biased.", "youglish": "https://youglish.com/pronounce/biased/english", "dict": "https://dictionary.cambridge.org/dictionary/english/biased"}, {"en": "publish", "ipa": "/ˈpʌblɪʃ/", "ko": "출판하다, 게재하다", "example": "The article was published last week.", "youglish": "https://youglish.com/pronounce/publish/english", "dict": "https://dictionary.cambridge.org/dictionary/english/publish"}, {"en": "subscription", "ipa": "/səbˈskrɪpʃn/", "ko": "구독", "example": "I pay for a monthly news subscription.", "youglish": "https://youglish.com/pronounce/subscription/english", "dict": "https://dictionary.cambridge.org/dictionary/english/subscription"}, {"en": "broadcast", "ipa": "/ˈbrɔːdkɑːst/", "ko": "방송하다", "example": "The match was broadcast live on TV.", "youglish": "https://youglish.com/pronounce/broadcast/english", "dict": "https://dictionary.cambridge.org/dictionary/english/broadcast"}]}'::jsonb, todos = '[{"kind": "blog", "text": "신문 어휘(약 40개) + 빈칸 8문제 + 오류 고치기 8문제", "url": "http://www.ieltsliz.com/newspaper-vocabulary", "minutes": 20}, {"kind": "listening", "text": "British Council 공식 Listening Test 2 (30분) → 채점 → 스크립트 확인", "url": "https://takeielts.britishcouncil.org/take-ielts/prepare/free-ielts-english-practice-tests/listening-2/section-1", "minutes": 45}]'::jsonb where day = '2026-12-12';
update public.ielts_days set note = '{"summary": "Discuss both views 에세이예요. 양쪽을 공평하게 한 문단씩 쓰고, 서론과 결론에 내 의견을 넣어요. (보통 문제 끝에 “give your own opinion”이 붙어요)", "items": [], "frame_tip": null, "extra": "*🧭 에세이 설계도*\n• *서론*: Some people believe that ..., while others argue that ... + This essay will discuss both views, and I will explain why ...\n• *본론 1 (긴 형량 찬성)*: Firstly ... Secondly, a harsh punishment may deter people from ...\n• *본론 2 (대안 찬성)*: reoffend, rehabilitation, community service, young offenders\n• *결론*: In conclusion, although ..., I believe that ...\n\n*✅ 2분 체크*\n• commit a crime? • sent to prison (the 없이)? • deter ... from -ing? • Instead of + -ing?"}'::jsonb, quiz = null, model = '{"text": "Some people believe that longer prison sentences are the most effective way to reduce crime, while others argue that there are better alternatives. This essay will discuss both views, and I will explain why I believe that alternatives are more effective.\n\nOn the one hand, there are some good reasons to support longer prison sentences. Firstly, criminals cannot commit crimes while they are in prison, so society is safer. Secondly, a harsh punishment may deter people from breaking the law. For example, people may think twice before stealing if they know they could spend many years in prison.\n\nOn the other hand, many people believe that prison does not solve the real causes of crime. A large number of prisoners reoffend soon after they are released, because they have no job and no skills. Therefore, it is better to focus on rehabilitation, such as education and job training. In addition, young offenders who commit minor crimes could do community service instead of being sent to prison, which gives them a second chance.\n\nIn conclusion, although long prison sentences are necessary for serious crimes, I believe that prevention and rehabilitation are better ways to reduce the crime rate in the long term.", "why": ["양쪽 본론의 길이와 근거 수를 비슷하게 맞췄어요 (공정한 discuss).", "서론에서 내 입장을 예고하고, 결론에서 다시 확인했어요.", "이번 주 범죄 표현 8개 이상, 약 260단어예요."]}'::jsonb, extras = null, todos = null where day = '2026-12-13';
update public.ielts_days set note = '{"summary": "Speaking Part 1은 4~5분 동안 일상 질문 10~12개가 나와요. 길게 말하기보다 ''바로 답 + 이유나 예시 하나''가 핵심이에요. 고향·집은 거의 매번 첫 주제예요.", "items": [{"en": "I grew up in ~", "ko": "~에서 자랐어요", "usage": "grow up의 과거형 grew up. 수동태로 쓰지 않아요.", "examples": [{"type": "s", "text": "I grew up in Busan, but I''ve lived in Seoul for ten years."}, {"type": "s", "text": "I grew up in a small town, so I''m used to a quiet life."}], "mistake": "✗ I was grown up in → I grew up in", "pron": {"word": "grew", "ipa": "/ɡruː/", "youglish": "https://youglish.com/pronounce/I%20grew%20up%20in/english", "dict": "https://dictionary.cambridge.org/dictionary/english/grew"}}, {"en": "It''s a fairly quiet area", "ko": "꽤 조용한 동네예요", "usage": "fairly / quite / pretty(구어) + 형용사로 정도를 조절해요.", "examples": [{"type": "s", "text": "It''s a fairly quiet area, so it''s good for families."}, {"type": "s", "text": "My neighbourhood is pretty busy at night because there are lots of restaurants."}], "mistake": "✗ It''s very quiet place → It''s a very quiet place (관사 a)", "pron": {"word": "fairly", "ipa": "/ˈfeəli/", "youglish": "https://youglish.com/pronounce/it%27s%20a%20fairly%20quiet/english", "dict": "https://dictionary.cambridge.org/dictionary/english/fairly"}}, {"en": "a convenient location", "ko": "편리한 위치", "usage": "형용사 convenient, 명사 convenience.", "examples": [{"type": "s", "text": "My apartment is in a convenient location, near a subway station."}, {"type": "s", "text": "The best thing about my office is its convenient location."}], "mistake": "✗ convenience location → convenient location", "pron": {"word": "convenient", "ipa": "/kənˈviːniənt/", "youglish": "https://youglish.com/pronounce/convenient%20location/english", "dict": "https://dictionary.cambridge.org/dictionary/english/convenient"}}, {"en": "I live in an apartment", "ko": "아파트에 살아요", "usage": "영국 flat, 미국 apartment 둘 다 OK. 관사 an 잊지 마세요.", "examples": [{"type": "s", "text": "I live in an apartment on the 15th floor."}, {"type": "s", "text": "Like most people in Korea, I live in an apartment."}], "mistake": "✗ I live in apartment → in an apartment", "pron": {"word": "apartment", "ipa": "/əˈpɑːtmənt/", "youglish": "https://youglish.com/pronounce/I%20live%20in%20an%20apartment/english", "dict": "https://dictionary.cambridge.org/dictionary/english/apartment"}}, {"en": "The best thing about ~ is ...", "ko": "~의 가장 좋은 점은", "usage": "about을 써요. 반대는 The worst thing about ~ is ...", "examples": [{"type": "s", "text": "The best thing about my hometown is the food."}, {"type": "s", "text": "The best thing about living in Seoul is the public transport."}], "mistake": "✗ The best thing of → about", "pron": {"word": null, "ipa": null, "youglish": "https://youglish.com/pronounce/the%20best%20thing%20about/english", "dict": null}}], "frame_tip": "답을 시작하면서 생각할 시간을 벌고 자연스럽게 들리게 해요. 매 답마다 쓰면 어색하니 2~3번에 한 번만. Actually는 ''사실은(예상과 다르게)'' 뉘앙스예요.", "extra": null}'::jsonb, quiz = '[{"q": "틀린 곳 고치기: “I was grown up in Daegu.”", "a": "*I grew up* in Daegu."}, {"q": "틀린 곳 고치기: “It''s very convenience location.”", "a": "It''s *a* very *convenient* location."}, {"q": "전치사: The best thing ___ my hometown is the beach.", "a": "about"}, {"q": "관사: “I live in ___ apartment near the river.”", "a": "an"}]'::jsonb, model = '{"text": "Q: Where are you from?\nA: I''m from Seoul, but actually I grew up in a small city called Cheongju. I moved to Seoul for university.\n\nQ: Do you like your hometown?\nA: Yes, I do. It''s a fairly quiet area, and the best thing about it is that it''s close to the mountains.\n\nQ: Do you live in a house or an apartment?\nA: I live in an apartment, like most people in Korea. It''s in a convenient location, right next to a subway station.\n\nQ: What would you change about your home?\nA: To be honest, I''d like a bigger kitchen, because I enjoy cooking and ours is really small.", "why": ["모든 답이 ''바로 답 + 디테일 하나''로 2문장이에요.", "Actually, To be honest를 한 번씩만 썼어요.", "답변 내용은 사실이 아니어도 돼요. 채점은 영어만 봐요."]}'::jsonb, extras = '{"phrases": [{"en": "I''ve lived there for ~ years", "ko": "거기서 ~년째 살고 있어요", "example": "I''ve lived in Seoul for about ten years.", "youglish": "https://youglish.com/pronounce/I%27ve%20lived%20there%20for%20years/english"}, {"en": "It''s changed a lot", "ko": "많이 변했어요", "example": "My hometown has changed a lot since I was a child.", "youglish": "https://youglish.com/pronounce/It%27s%20changed%20a%20lot/english"}, {"en": "within walking distance", "ko": "걸어갈 수 있는 거리에", "example": "There''s a supermarket within walking distance.", "youglish": "https://youglish.com/pronounce/within%20walking%20distance/english"}, {"en": "get a bit noisy", "ko": "좀 시끄러워지다", "example": "It can get a bit noisy at night.", "youglish": "https://youglish.com/pronounce/get%20a%20bit%20noisy/english"}, {"en": "I''d like to move to ~", "ko": "~로 이사 가고 싶어요", "example": "One day, I''d like to move to the countryside.", "youglish": "https://youglish.com/pronounce/I%27d%20like%20to%20move%20to/english"}], "words": [{"en": "neighbourhood", "ipa": "/ˈneɪbəhʊd/", "ko": "동네", "example": "My neighbourhood is quiet and safe.", "youglish": "https://youglish.com/pronounce/neighbourhood/english", "dict": "https://dictionary.cambridge.org/dictionary/english/neighbourhood"}, {"en": "spacious", "ipa": "/ˈspeɪʃəs/", "ko": "넓은", "example": "Our living room is quite spacious.", "youglish": "https://youglish.com/pronounce/spacious/english", "dict": "https://dictionary.cambridge.org/dictionary/english/spacious"}, {"en": "cosy", "ipa": "/ˈkəʊzi/", "ko": "아늑한", "example": "My apartment is small but cosy.", "youglish": "https://youglish.com/pronounce/cosy/english", "dict": "https://dictionary.cambridge.org/dictionary/english/cosy"}, {"en": "suburb", "ipa": "/ˈsʌbɜːb/", "ko": "교외", "example": "I live in a suburb about 30 minutes from the city centre.", "youglish": "https://youglish.com/pronounce/suburb/english", "dict": "https://dictionary.cambridge.org/dictionary/english/suburb"}, {"en": "lively", "ipa": "/ˈlaɪvli/", "ko": "활기찬", "example": "The area is very lively at the weekend.", "youglish": "https://youglish.com/pronounce/lively/english", "dict": "https://dictionary.cambridge.org/dictionary/english/lively"}]}'::jsonb, todos = '[{"kind": "blog", "text": "Part 1 질문 목록에서 Hometown·Home 질문(각 10개 정도)을 소리 내 답하기", "url": "https://ieltsliz.com/ielts-speaking-part-1-topics/", "minutes": 15}]'::jsonb where day = '2026-12-14';
update public.ielts_days set note = '{"summary": "취미·영화는 Part 1 단골이고 Part 2(좋아하는 영화 묘사)로도 이어져요. 현재 취미 + 과거와 비교(used to)를 넣으면 문법 다양성 점수를 받아요.", "items": [{"en": "in my free time", "ko": "여가 시간에", "usage": "free time은 셀 수 없는 명사. spare time도 같은 뜻이에요.", "examples": [{"type": "s", "text": "In my free time, I like going for walks along the river."}, {"type": "s", "text": "I don''t have much free time these days because of work."}], "mistake": "✗ in my free times / ✗ at my free time", "pron": {"word": null, "ipa": null, "youglish": "https://youglish.com/pronounce/in%20my%20free%20time/english", "dict": null}}, {"en": "I''m really into ~", "ko": "~에 푹 빠져 있어요", "usage": "into + 명사 / -ing. 구어에서 아주 자연스러운 표현이에요.", "examples": [{"type": "s", "text": "I''m really into cooking at the moment."}, {"type": "s", "text": "My friend is really into K-pop; she goes to every concert."}], "mistake": "✗ I''m really into to cook → into cooking", "pron": {"word": null, "ipa": null, "youglish": "https://youglish.com/pronounce/I%27m%20really%20into/english", "dict": null}}, {"en": "an action film / a comedy", "ko": "액션 영화 / 코미디", "usage": "다른 장르: thriller, romantic comedy, documentary, animated film, horror film. 미국식은 movie.", "examples": [{"type": "s", "text": "I usually watch action films because they''re exciting."}, {"type": "s", "text": "When I''m tired, I prefer a light comedy."}], "mistake": "a comedy movie도 되지만 a comedy로 충분해요.", "pron": {"word": "comedy", "ipa": "/ˈkɒmədi/", "youglish": "https://youglish.com/pronounce/action%20films/english", "dict": "https://dictionary.cambridge.org/dictionary/english/comedy"}}, {"en": "It helps me relax", "ko": "긴장을 풀어줘요", "usage": "help + 사람 + 동사원형.", "examples": [{"type": "s", "text": "Watching films helps me relax after work."}, {"type": "s", "text": "Cooking helps me forget about stress."}], "mistake": "✗ helps me relaxing → helps me relax", "pron": {"word": "relax", "ipa": "/rɪˈlæks/", "youglish": "https://youglish.com/pronounce/helps%20me%20relax/english", "dict": "https://dictionary.cambridge.org/dictionary/english/relax"}}, {"en": "I used to ..., but now ...", "ko": "예전엔 ~했지만 지금은", "usage": "used to + 동사원형. 현재형 use to는 없어요.", "examples": [{"type": "s", "text": "I used to go to the cinema every week, but now I watch everything on Netflix."}, {"type": "s", "text": "I used to play computer games a lot, but now I don''t have time."}], "mistake": "✗ I used to going / 발음: used /juːst/ (유스트, 유즈드 아님)", "pron": {"word": "used", "ipa": "/juːst/", "youglish": "https://youglish.com/pronounce/I%20used%20to/english", "dict": "https://dictionary.cambridge.org/dictionary/english/used"}}], "frame_tip": "선호·빈도 질문에 답할 때 써요. I''d say = I would say (단정 대신 부드럽게). mainly because로 이유를 하나 붙여요.", "extra": null}'::jsonb, quiz = '[{"q": "틀린 곳 고치기: “I used to playing tennis.”", "a": "I used to *play* tennis."}, {"q": "I''m really ______ hiking these days.", "a": "into"}, {"q": "틀린 곳 고치기: “Music helps me relaxing.”", "a": "helps me *relax*"}, {"q": "발음: used to의 used는? (유즈드 / 유스트)", "a": "유스트 /juːst/"}]'::jsonb, model = '{"text": "Q: What do you do in your free time?\nA: In my free time, I''m really into cooking. I try new recipes on weekends, and it helps me relax after a busy week.\n\nQ: What kind of films do you like?\nA: I''d say action films, mainly because they''re exciting and easy to watch when I''m tired. But I also enjoy a good comedy.\n\nQ: How often do you watch films?\nA: I used to go to the cinema every week, but now I mostly watch films at home, maybe once or twice a week.", "why": ["현재(I''m into) + 과거(used to) 시제를 섞어서 문법 다양성을 보여줬어요.", "I''d say ..., mainly because ... 틀을 그대로 썼어요.", "각 답 2문장, 15~20초 분량이에요."]}'::jsonb, extras = '{"phrases": [{"en": "unwind after work", "ko": "퇴근 후 쉬다", "example": "I usually watch a drama to unwind after work.", "youglish": "https://youglish.com/pronounce/unwind%20after%20work/english"}, {"en": "binge-watch", "ko": "(드라마를) 몰아서 보다", "example": "I binge-watched a whole series last weekend.", "youglish": "https://youglish.com/pronounce/binge-watch/english"}, {"en": "take up a hobby", "ko": "취미를 시작하다", "example": "I took up running last year.", "youglish": "https://youglish.com/pronounce/take%20up%20a%20hobby/english"}, {"en": "I''m not really a fan of ~", "ko": "~을 별로 안 좋아해요", "example": "I''m not really a fan of horror films.", "youglish": "https://youglish.com/pronounce/I%27m%20not%20really%20a%20fan%20of/english"}, {"en": "from time to time", "ko": "가끔", "example": "I go to the cinema from time to time.", "youglish": "https://youglish.com/pronounce/from%20time%20to%20time/english"}], "words": [{"en": "plot", "ipa": "/plɒt/", "ko": "줄거리", "example": "The plot was a bit confusing.", "youglish": "https://youglish.com/pronounce/plot/english", "dict": "https://dictionary.cambridge.org/dictionary/english/plot"}, {"en": "gripping", "ipa": "/ˈɡrɪpɪŋ/", "ko": "손에 땀을 쥐게 하는", "example": "It was a gripping thriller.", "youglish": "https://youglish.com/pronounce/gripping/english", "dict": "https://dictionary.cambridge.org/dictionary/english/gripping"}, {"en": "cast", "ipa": "/kɑːst/", "ko": "출연진", "example": "The film has an amazing cast.", "youglish": "https://youglish.com/pronounce/cast/english", "dict": "https://dictionary.cambridge.org/dictionary/english/cast"}, {"en": "pastime", "ipa": "/ˈpɑːstaɪm/", "ko": "취미, 여가 활동", "example": "Reading is my favourite pastime.", "youglish": "https://youglish.com/pronounce/pastime/english", "dict": "https://dictionary.cambridge.org/dictionary/english/pastime"}, {"en": "subtitles", "ipa": "/ˈsʌbtaɪtlz/", "ko": "자막", "example": "I watch English films with subtitles.", "youglish": "https://youglish.com/pronounce/subtitles/english", "dict": "https://dictionary.cambridge.org/dictionary/english/subtitles"}]}'::jsonb, todos = '[{"kind": "blog", "text": "영화 장르 12개 리스닝 퀴즈 (설명 듣고 장르 맞히기)", "url": "https://ieltsliz.com/types-of-films-vocabulary/", "minutes": 10}]'::jsonb where day = '2026-12-15';
update public.ielts_days set note = '{"summary": "음식·옷도 Part 1에 자주 나와요. “It depends”로 시작해서 두 가지 상황을 비교하면 답이 자연스럽게 길어져요.", "items": [{"en": "I prefer casual clothes", "ko": "편한 옷을 선호해요", "usage": "prefer A to B (than 아님).", "examples": [{"type": "s", "text": "I prefer casual clothes, like jeans and T-shirts."}, {"type": "s", "text": "I prefer comfortable clothes to fashionable ones."}], "mistake": "✗ prefer A than B → prefer A to B", "pron": {"word": "casual", "ipa": "/ˈkæʒuəl/", "youglish": "https://youglish.com/pronounce/casual%20clothes/english", "dict": "https://dictionary.cambridge.org/dictionary/english/casual"}}, {"en": "dress up for ~", "ko": "~을 위해 차려입다", "usage": "dress up = 격식 있게 차려입다. 그냥 옷을 입다는 get dressed.", "examples": [{"type": "s", "text": "I only dress up for weddings or important meetings."}, {"type": "s", "text": "People in Seoul often dress up for a night out."}], "mistake": "dress up(차려입다)과 get dressed(옷을 입다)를 구분해요.", "pron": {"word": null, "ipa": null, "youglish": "https://youglish.com/pronounce/dress%20up%20for/english", "dict": null}}, {"en": "home-cooked meals", "ko": "집밥", "usage": "home-made food도 같은 뜻이에요.", "examples": [{"type": "s", "text": "Nothing beats my mum''s home-cooked meals."}, {"type": "s", "text": "I try to eat home-cooked meals because they''re healthier."}], "mistake": "하이픈 주의: home-cooked", "pron": {"word": "cooked", "ipa": "/kʊkt/", "youglish": "https://youglish.com/pronounce/home-cooked%20meals/english", "dict": "https://dictionary.cambridge.org/dictionary/english/cooked"}}, {"en": "eat out", "ko": "외식하다", "usage": "목적어 없이 써요.", "examples": [{"type": "s", "text": "We usually eat out on Friday nights."}, {"type": "s", "text": "Eating out is getting more expensive in Korea."}], "mistake": "✗ eat out food / ✗ eat outside (밖에서, 즉 야외에서 먹다는 뜻이 돼요)", "pron": {"word": null, "ipa": null, "youglish": "https://youglish.com/pronounce/eat%20out/english", "dict": null}}, {"en": "It depends on ~", "ko": "~에 따라 달라요", "usage": "depend on + 명사 / wh-절.", "examples": [{"type": "s", "text": "It depends on the weather."}, {"type": "s", "text": "It depends on who I''m with."}], "mistake": "✗ It depends of / ✗ It''s depend on", "pron": {"word": "depends", "ipa": "/dɪˈpendz/", "youglish": "https://youglish.com/pronounce/it%20depends%20on/english", "dict": "https://dictionary.cambridge.org/dictionary/english/depends"}}], "frame_tip": "“어느 쪽이 좋아요?” 질문에 상황별로 답할 때 써요. It depends로 끝내지 말고 반드시 For example로 두 상황을 보여주세요.", "extra": null}'::jsonb, quiz = '[{"q": "전치사: It depends ___ my mood.", "a": "on"}, {"q": "틀린 곳 고치기: “I prefer jeans than suits.”", "a": "I prefer jeans *to* suits."}, {"q": "틀린 곳 고치기: “We eat outside at a restaurant every Friday.”", "a": "We *eat out* every Friday."}, {"q": "I usually ______ ___ for weddings. (차려입다)", "a": "dress up"}]'::jsonb, model = '{"text": "Q: What kind of clothes do you usually wear?\nA: I prefer casual clothes, like jeans and a sweatshirt. I only dress up for special occasions, such as weddings.\n\nQ: Do you prefer eating out or cooking at home?\nA: It depends on how busy I am. For example, on weekdays I often eat out because I''m tired, but on weekends I enjoy home-cooked meals.\n\nQ: What''s your favourite food?\nA: I''d say kimchi stew. It''s simple, but it reminds me of my mum''s cooking.", "why": ["It depends on → For example → but 구조로 두 상황을 비교했어요.", "such as로 예시를 들었어요.", "어제 틀(I''d say)도 재활용했어요."]}'::jsonb, extras = '{"phrases": [{"en": "I''m a big fan of ~", "ko": "~을 아주 좋아해요", "example": "I''m a big fan of spicy food.", "youglish": "https://youglish.com/pronounce/I%27m%20a%20big%20fan%20of/english"}, {"en": "grab a bite to eat", "ko": "간단히 뭘 먹다", "example": "Let''s grab a bite to eat before the film.", "youglish": "https://youglish.com/pronounce/grab%20a%20bite%20to%20eat/english"}, {"en": "I can''t stand ~", "ko": "~을 정말 못 참겠어요, 싫어해요", "example": "I can''t stand very sweet food.", "youglish": "https://youglish.com/pronounce/I%20can%27t%20stand/english"}, {"en": "follow the latest trends", "ko": "최신 유행을 따르다", "example": "I don''t really follow the latest fashion trends.", "youglish": "https://youglish.com/pronounce/follow%20the%20latest%20trends/english"}, {"en": "a special occasion", "ko": "특별한 날", "example": "I only wear a suit on special occasions.", "youglish": "https://youglish.com/pronounce/a%20special%20occasion/english"}], "words": [{"en": "cuisine", "ipa": "/kwɪˈziːn/", "ko": "(나라·지역의) 요리", "example": "I love Italian cuisine.", "youglish": "https://youglish.com/pronounce/cuisine/english", "dict": "https://dictionary.cambridge.org/dictionary/english/cuisine"}, {"en": "takeaway", "ipa": "/ˈteɪkəweɪ/", "ko": "포장 음식 (영국식)", "example": "We often get a takeaway on Friday nights.", "youglish": "https://youglish.com/pronounce/takeaway/english", "dict": "https://dictionary.cambridge.org/dictionary/english/takeaway"}, {"en": "outfit", "ipa": "/ˈaʊtfɪt/", "ko": "옷차림 한 벌", "example": "I bought a new outfit for the wedding.", "youglish": "https://youglish.com/pronounce/outfit/english", "dict": "https://dictionary.cambridge.org/dictionary/english/outfit"}, {"en": "fashionable", "ipa": "/ˈfæʃnəbl/", "ko": "유행하는", "example": "My sister always wears fashionable clothes.", "youglish": "https://youglish.com/pronounce/fashionable/english", "dict": "https://dictionary.cambridge.org/dictionary/english/fashionable"}, {"en": "ingredient", "ipa": "/ɪnˈɡriːdiənt/", "ko": "재료", "example": "Fresh ingredients make a big difference.", "youglish": "https://youglish.com/pronounce/ingredient/english", "dict": "https://dictionary.cambridge.org/dictionary/english/ingredient"}]}'::jsonb, todos = '[{"kind": "blog", "text": "옷·액세서리 단어를 격식/비격식으로 분류하는 연습", "url": "https://ieltsliz.com/clothes-vocabulary/", "minutes": 10}, {"kind": "reading", "text": "GT Reading Test 2 전체 (3섹션, 60분) — 실전처럼 시간 재기", "url": "https://takeielts.britishcouncil.org/take-ielts/prepare/free-ielts-english-practice-tests/reading/general-training", "minutes": 60}]'::jsonb where day = '2026-12-16';
update public.ielts_days set note = '{"summary": "Part 2는 큐카드를 받고 1분 준비, 1~2분 말하기예요. 큐카드의 질문 4개(누구 / 어떻게 알게 됐나 / 어떤 사람인가 / 왜)를 순서대로 답하면 구조가 저절로 잡혀요.", "items": [{"en": "someone I really look up to", "ko": "정말 존경하는 사람", "usage": "look up to = admire (구어). 사람을 소개하는 첫 문장으로 좋아요.", "examples": [{"type": "s", "text": "I''d like to talk about someone I really look up to, my old manager."}, {"type": "s", "text": "I''ve always looked up to my grandfather."}], "mistake": "✗ look up to at", "pron": {"word": null, "ipa": null, "youglish": "https://youglish.com/pronounce/look%20up%20to/english", "dict": null}}, {"en": "get on well with ~", "ko": "~와 잘 지내다", "usage": "영국식이에요. 미국식은 get along with.", "examples": [{"type": "s", "text": "We get on well with each other because we have similar interests."}, {"type": "s", "text": "I didn''t get on well with him at first."}], "mistake": "✗ get well with → get on well with", "pron": {"word": null, "ipa": null, "youglish": "https://youglish.com/pronounce/get%20on%20well%20with/english", "dict": null}}, {"en": "hard-working / patient", "ko": "성실한 / 인내심 있는", "usage": "형용사 뒤에 항상 예시를 붙이세요. 그래야 시간이 채워져요.", "examples": [{"type": "s", "text": "She''s incredibly hard-working; she''s always the first to arrive."}, {"type": "s", "text": "He''s very patient with beginners."}], "mistake": "발음: patient /ˈpeɪʃnt/ (페이션트)", "pron": {"word": "patient", "ipa": "/ˈpeɪʃnt/", "youglish": "https://youglish.com/pronounce/very%20patient/english", "dict": "https://dictionary.cambridge.org/dictionary/english/patient"}}, {"en": "have a big influence on ~", "ko": "~에게 큰 영향을 주다", "usage": "전치사는 on. influence의 강세는 첫 음절이에요.", "examples": [{"type": "s", "text": "My teacher had a big influence on my career."}, {"type": "s", "text": "Living abroad had a big influence on the way I think."}], "mistake": "✗ influence to → influence on", "pron": {"word": "influence", "ipa": "/ˈɪnfluəns/", "youglish": "https://youglish.com/pronounce/big%20influence%20on/english", "dict": "https://dictionary.cambridge.org/dictionary/english/influence"}}, {"en": "I first met him/her when ...", "ko": "처음 만난 건 ~ 때예요", "usage": "first는 met 앞에 와요. 또는 for the first time.", "examples": [{"type": "s", "text": "I first met her when I started my first job."}, {"type": "s", "text": "I first met him when we were in the same class at university."}], "mistake": "✗ I met him first time → for the first time", "pron": {"word": null, "ipa": null, "youglish": "https://youglish.com/pronounce/I%20first%20met%20her%20when/english", "dict": null}}], "frame_tip": "Part 2의 시작과 마무리 문장이에요. 시작: I''d like to talk about ... / 마무리: The reason I chose her is that ...", "extra": null}'::jsonb, quiz = '[{"q": "전치사: She had a big influence ___ me.", "a": "on"}, {"q": "틀린 곳 고치기: “I get well with my colleagues.”", "a": "I *get on well with* my colleagues."}, {"q": "발음: patient의 강세는? (PAY-shnt / pa-TIENT)", "a": "첫 음절 PAY-shnt /ˈpeɪʃnt/"}, {"q": "My father is someone I really look ___ ___.", "a": "up to"}]'::jsonb, model = '{"text": "I''d like to talk about someone I really look up to, my first manager at work. I first met her when I joined my company about ten years ago. I was very nervous at that time, because I had no experience.\n\nShe was incredibly hard-working. She always arrived early, and she never left a problem unfinished. She was also very patient. When I made mistakes, she didn''t get angry. Instead, she explained what went wrong and helped me fix it.\n\nWe got on well with each other, even though she was much older than me. We often had lunch together and talked about our families and hobbies.\n\nThe reason I chose her is that she had a big influence on my career. Because of her, I learned how to plan my work and communicate clearly. Now I try to treat new team members in the same way she treated me.\n\nWe don''t work together anymore, but we still keep in touch, and I sometimes ask her for advice.", "why": ["큐카드 순서(누구 → 만남 → 어떤 사람 → 왜)대로 말했어요. 약 2분 분량이에요.", "형용사(hard-working, patient)마다 구체적인 예시를 붙였어요.", "마지막에 현재 이야기(keep in touch)로 자연스럽게 마무리했어요."]}'::jsonb, extras = '{"phrases": [{"en": "a role model", "ko": "롤모델", "example": "My father has always been my role model.", "youglish": "https://youglish.com/pronounce/a%20role%20model/english"}, {"en": "go out of their way to ~", "ko": "일부러 애써서 ~하다", "example": "She always goes out of her way to help others.", "youglish": "https://youglish.com/pronounce/go%20out%20of%20their%20way%20to/english"}, {"en": "keep calm under pressure", "ko": "압박 속에서 침착하다", "example": "He keeps calm under pressure.", "youglish": "https://youglish.com/pronounce/keep%20calm%20under%20pressure/english"}, {"en": "learn a lot from ~", "ko": "~에게서 많이 배우다", "example": "I learned a lot from my first teacher.", "youglish": "https://youglish.com/pronounce/learn%20a%20lot%20from/english"}, {"en": "someone I can rely on", "ko": "믿고 의지할 수 있는 사람", "example": "My best friend is someone I can rely on.", "youglish": "https://youglish.com/pronounce/someone%20I%20can%20rely%20on/english"}], "words": [{"en": "generous", "ipa": "/ˈdʒenərəs/", "ko": "너그러운, 인심 좋은", "example": "My uncle is very generous with his time.", "youglish": "https://youglish.com/pronounce/generous/english", "dict": "https://dictionary.cambridge.org/dictionary/english/generous"}, {"en": "determined", "ipa": "/dɪˈtɜːmɪnd/", "ko": "의지가 강한", "example": "She was determined to pass the exam.", "youglish": "https://youglish.com/pronounce/determined/english", "dict": "https://dictionary.cambridge.org/dictionary/english/determined"}, {"en": "inspiring", "ipa": "/ɪnˈspaɪərɪŋ/", "ko": "영감을 주는", "example": "Her story is really inspiring.", "youglish": "https://youglish.com/pronounce/inspiring/english", "dict": "https://dictionary.cambridge.org/dictionary/english/inspiring"}, {"en": "supportive", "ipa": "/səˈpɔːtɪv/", "ko": "힘이 되어 주는", "example": "My parents have always been very supportive.", "youglish": "https://youglish.com/pronounce/supportive/english", "dict": "https://dictionary.cambridge.org/dictionary/english/supportive"}, {"en": "admire", "ipa": "/ədˈmaɪə(r)/", "ko": "존경하다", "example": "I admire people who work hard.", "youglish": "https://youglish.com/pronounce/admire/english", "dict": "https://dictionary.cambridge.org/dictionary/english/admire"}]}'::jsonb, todos = '[{"kind": "blog", "text": "큐카드 29개 중 ''사람'' 카드 2개를 골라 1분 메모만 해 보기", "url": "https://ieltsliz.com/ielts-speaking-part-2-topics/", "minutes": 10}]'::jsonb where day = '2026-12-17';
update public.ielts_days set note = '{"summary": "장소 묘사는 ''위치 → 모습 → 거기서 하는 일 → 느낌'' 순서로 말하면 돼요. 감각 표현(조용한, 붐비는)을 하나 넣으면 생생해져요.", "items": [{"en": "It''s located in ~", "ko": "~에 있어요", "usage": "be located in / on / near. 능동태 locate로 쓰지 않아요.", "examples": [{"type": "s", "text": "It''s located in the north of Seoul, about an hour from my home."}, {"type": "s", "text": "The café is located on a small street near the river."}], "mistake": "✗ It locates in → It''s located in", "pron": {"word": "located", "ipa": "/ləʊˈkeɪtɪd/", "youglish": "https://youglish.com/pronounce/it%27s%20located%20in/english", "dict": "https://dictionary.cambridge.org/dictionary/english/located"}}, {"en": "crowded / peaceful", "ko": "붐비는 / 평화로운", "usage": "get crowded (붐비게 되다)로도 자주 써요.", "examples": [{"type": "s", "text": "It gets really crowded on weekends."}, {"type": "s", "text": "Early in the morning it''s very peaceful."}], "mistake": "✗ It''s crowd → It''s crowded", "pron": {"word": "crowded", "ipa": "/ˈkraʊdɪd/", "youglish": "https://youglish.com/pronounce/really%20crowded/english", "dict": "https://dictionary.cambridge.org/dictionary/english/crowded"}}, {"en": "green spaces", "ko": "녹지 공간", "usage": "도시의 공원·숲 등을 통틀어 말할 땐 복수형이에요. Writing에도 좋아요.", "examples": [{"type": "s", "text": "Seoul has more green spaces than people think."}, {"type": "w", "text": "Cities need more green spaces where children can play."}], "mistake": "전체를 말할 땐 green spaces (복수)", "pron": {"word": null, "ipa": null, "youglish": "https://youglish.com/pronounce/green%20spaces/english", "dict": null}}, {"en": "a great place to unwind", "ko": "쉬기 좋은 곳", "usage": "unwind = relax. 발음 /ʌnˈwaɪnd/ (언와인드). wind가 ''감다''라는 뜻일 때 발음이에요.", "examples": [{"type": "s", "text": "The park is a great place to unwind after work."}, {"type": "s", "text": "For me, the beach is the best place to unwind."}], "mistake": "✗ 언윈드 (바람 wind 발음) → 언와인드", "pron": {"word": "unwind", "ipa": "/ʌnˈwaɪnd/", "youglish": "https://youglish.com/pronounce/place%20to%20unwind/english", "dict": "https://dictionary.cambridge.org/dictionary/english/unwind"}}, {"en": "I''d recommend it to ~", "ko": "~에게 추천하고 싶어요", "usage": "recommend + 사물 + to + 사람 / recommend + -ing.", "examples": [{"type": "s", "text": "I''d recommend it to anyone who likes nature."}, {"type": "s", "text": "I''d definitely recommend visiting it in autumn."}], "mistake": "✗ I''d recommend to visit it → I''d recommend visiting it", "pron": {"word": "recommend", "ipa": "/ˌrekəˈmend/", "youglish": "https://youglish.com/pronounce/I%27d%20recommend%20it%20to/english", "dict": "https://dictionary.cambridge.org/dictionary/english/recommend"}}], "frame_tip": "가장 좋은 점을 강조할 때 써요. What I like most about it is that + 문장 / is + 명사.", "extra": null}'::jsonb, quiz = '[{"q": "틀린 곳 고치기: “The park locates near my house.”", "a": "The park *is located* near my house."}, {"q": "틀린 곳 고치기: “I''d recommend to visit it in spring.”", "a": "I''d recommend *visiting* it in spring."}, {"q": "The beach is a great place to ______. (쉬다, un-으로 시작)", "a": "unwind"}, {"q": "형태: “It gets really ______ on weekends.” (crowd)", "a": "crowded"}]'::jsonb, model = '{"text": "I''d like to talk about a park I like to visit, Seoul Forest. It''s located in the east of Seoul, near the Han River, and it takes me about thirty minutes to get there by subway.\n\nIt''s a huge park with lots of green spaces, a small lake and some walking paths. There''s also an area where you can see deer, which is quite unusual for a city park.\n\nI usually go there on Sunday mornings. I take a long walk, sometimes have a coffee, and just sit on a bench and watch people. It gets really crowded in the afternoon, but early in the morning it''s very peaceful.\n\nWhat I like most about it is that it doesn''t feel like you''re in the city at all. After a stressful week, it''s a great place to unwind.\n\nI''d recommend it to anyone who visits Seoul, especially people who like nature.", "why": ["위치 → 모습 → 하는 일 → 느낌 → 추천 순서예요.", "crowded / peaceful로 시간대에 따른 대비를 보여줬어요.", "오늘 표현 5개 + 문장 틀을 모두 썼어요."]}'::jsonb, extras = '{"phrases": [{"en": "off the beaten track", "ko": "사람들이 잘 모르는 (한적한 곳)", "example": "The café is a bit off the beaten track.", "youglish": "https://youglish.com/pronounce/off%20the%20beaten%20track/english"}, {"en": "a breath of fresh air", "ko": "기분 전환이 되는 것", "example": "Going to the mountains is a breath of fresh air.", "youglish": "https://youglish.com/pronounce/a%20breath%20of%20fresh%20air/english"}, {"en": "take in the view", "ko": "경치를 감상하다", "example": "I sat on a bench and took in the view.", "youglish": "https://youglish.com/pronounce/take%20in%20the%20view/english"}, {"en": "it''s well worth a visit", "ko": "가 볼 만한 가치가 충분해요", "example": "If you''re in Busan, the market is well worth a visit.", "youglish": "https://youglish.com/pronounce/it%27s%20well%20worth%20a%20visit/english"}, {"en": "a hidden gem", "ko": "숨은 명소", "example": "This little bookshop is a hidden gem.", "youglish": "https://youglish.com/pronounce/a%20hidden%20gem/english"}], "words": [{"en": "scenery", "ipa": "/ˈsiːnəri/", "ko": "경치 (불가산)", "example": "The scenery in Jeju is beautiful.", "youglish": "https://youglish.com/pronounce/scenery/english", "dict": "https://dictionary.cambridge.org/dictionary/english/scenery"}, {"en": "atmosphere", "ipa": "/ˈætməsfɪə(r)/", "ko": "분위기", "example": "The café has a relaxing atmosphere.", "youglish": "https://youglish.com/pronounce/atmosphere/english", "dict": "https://dictionary.cambridge.org/dictionary/english/atmosphere"}, {"en": "landmark", "ipa": "/ˈlændmɑːk/", "ko": "랜드마크, 명소", "example": "N Seoul Tower is a famous landmark.", "youglish": "https://youglish.com/pronounce/landmark/english", "dict": "https://dictionary.cambridge.org/dictionary/english/landmark"}, {"en": "breathtaking", "ipa": "/ˈbreθteɪkɪŋ/", "ko": "숨이 멎을 듯한", "example": "The view from the top is breathtaking.", "youglish": "https://youglish.com/pronounce/breathtaking/english", "dict": "https://dictionary.cambridge.org/dictionary/english/breathtaking"}, {"en": "tranquil", "ipa": "/ˈtræŋkwɪl/", "ko": "고요한 (peaceful 대신)", "example": "The temple is very tranquil in the early morning.", "youglish": "https://youglish.com/pronounce/tranquil/english", "dict": "https://dictionary.cambridge.org/dictionary/english/tranquil"}]}'::jsonb, todos = '[{"kind": "blog", "text": "도시 어휘 25개 훑고, Part 3 모범 답안 5개 읽기", "url": "https://ieltsliz.com/ielts-topic-urban-planning-design/", "minutes": 15}]'::jsonb where day = '2026-12-18';
update public.ielts_days set note = '{"summary": "모르는 주제나 경험이 없는 큐카드가 나와도 멈추면 안 돼요. 시간을 버는 표현으로 시작하고, 비슷한 경험이나 지어낸 이야기로 2분을 채우세요. 내용이 사실인지는 채점하지 않아요.", "items": [{"en": "I''ve never really thought about it, but ...", "ko": "생각해 본 적은 없지만", "usage": "현재완료(I''ve never)가 자연스러워요.", "examples": [{"type": "s", "text": "I''ve never really thought about it, but I''d say my favourite season is autumn."}, {"type": "s", "text": "I''ve never really thought about it before, but I suppose I''m quite a patient person."}], "mistake": "✗ I never thought about it (가능하지만 현재완료가 더 자연스러워요)", "pron": {"word": null, "ipa": null, "youglish": "https://youglish.com/pronounce/never%20really%20thought%20about%20it/english", "dict": null}}, {"en": "If I had to choose, I''d say ...", "ko": "굳이 고르자면", "usage": "가정법이라 had ... would로 맞춰요.", "examples": [{"type": "s", "text": "If I had to choose, I''d say summer, because I love the beach."}, {"type": "s", "text": "If I had to choose one thing, I''d say my phone."}], "mistake": "✗ If I have to choose, I would say → If I had to choose, I''d say", "pron": {"word": null, "ipa": null, "youglish": "https://youglish.com/pronounce/if%20I%20had%20to%20choose/english", "dict": null}}, {"en": "a memorable experience", "ko": "기억에 남는 경험", "usage": "memorable의 강세는 첫 음절이에요.", "examples": [{"type": "s", "text": "One memorable experience was my first trip abroad."}, {"type": "s", "text": "Volunteering at a charity event was a really memorable experience."}], "mistake": "발음: /ˈmemərəbl/ (MEM-er-a-ble)", "pron": {"word": "memorable", "ipa": "/ˈmemərəbl/", "youglish": "https://youglish.com/pronounce/memorable%20experience/english", "dict": "https://dictionary.cambridge.org/dictionary/english/memorable"}}, {"en": "It made me realise that ...", "ko": "~을 깨닫게 했어요", "usage": "make + 사람 + 동사원형. 영국식 realise, 미국식 realize.", "examples": [{"type": "s", "text": "It made me realise that small actions can help people."}, {"type": "s", "text": "The trip made me realise how lucky I am."}], "mistake": "✗ made me to realise → made me realise", "pron": {"word": "realise", "ipa": "/ˈrɪəlaɪz/", "youglish": "https://youglish.com/pronounce/made%20me%20realise/english", "dict": "https://dictionary.cambridge.org/dictionary/english/realise"}}, {"en": "Looking back, ...", "ko": "돌이켜보면", "usage": "Part 2 마무리에서 느낌이나 교훈을 말할 때 좋아요.", "examples": [{"type": "s", "text": "Looking back, I think I was too nervous."}, {"type": "s", "text": "Looking back, it was one of the best decisions I''ve ever made."}], "mistake": "✗ Look back, ... → Looking back, ...", "pron": {"word": null, "ipa": null, "youglish": "https://youglish.com/pronounce/looking%20back/english", "dict": null}}], "frame_tip": "Part 2 마무리 문장이에요. 지금의 관점에서 그 경험을 평가하면 시제 다양성(과거 + 현재)도 보여줄 수 있어요.", "extra": null}'::jsonb, quiz = '[{"q": "틀린 곳 고치기: “It made me to realise that I was wrong.”", "a": "It *made me realise* that I was wrong."}, {"q": "시제: If I ___ to choose, I''d say coffee. (have / had)", "a": "had"}, {"q": "______ back, I think it was a good decision.", "a": "Looking"}, {"q": "강세: memorable — MEM-or-a-ble / me-MOR-a-ble", "a": "첫 음절 MEM-or-a-ble"}]'::jsonb, model = '{"text": "I''d like to talk about a time when I helped an elderly man at a subway station. It happened about two years ago, on a cold winter evening.\n\nI was on my way home from work when I saw an old man standing in front of the ticket machine. He looked confused, and people were just walking past him. To be honest, I was tired and wanted to go home, but I decided to ask if he needed help.\n\nIt turned out that he didn''t know how to use the machine, and he was also about to take the wrong line. I bought him a ticket and walked with him to the right platform. It only took about ten minutes, but he thanked me many times.\n\nIt was a memorable experience, because it made me realise that small actions can really help people. Looking back, I almost didn''t stop, and I''m glad I did. Since then, I try to pay more attention to people around me who might need help.", "why": ["언제 → 무슨 일 → 내가 한 일 → 느낀 점 순서예요.", "과거 시제로 이야기하고, 마지막에 현재(Since then, I try ...)로 마무리했어요.", "To be honest로 솔직한 감정을 넣으니 이야기가 자연스러워져요."]}'::jsonb, extras = '{"phrases": [{"en": "to be fair,", "ko": "공정하게 말하면", "example": "To be fair, it wasn''t completely his fault.", "youglish": "https://youglish.com/pronounce/to%20be%20fair/english"}, {"en": "it turned out that ~", "ko": "알고 보니 ~였다", "example": "It turned out that he was lost.", "youglish": "https://youglish.com/pronounce/it%20turned%20out%20that/english"}, {"en": "at first, ... but then ...", "ko": "처음엔 ~했지만 그다음엔", "example": "At first I was nervous, but then I started to enjoy it.", "youglish": "https://youglish.com/pronounce/at%20first%20but%20then/english"}, {"en": "I''ll never forget ~", "ko": "~을 절대 잊지 못할 거예요", "example": "I''ll never forget the look on his face.", "youglish": "https://youglish.com/pronounce/I%27ll%20never%20forget/english"}, {"en": "it was a turning point", "ko": "그것이 전환점이었어요", "example": "Moving abroad was a turning point in my life.", "youglish": "https://youglish.com/pronounce/it%20was%20a%20turning%20point/english"}], "words": [{"en": "grateful", "ipa": "/ˈɡreɪtfl/", "ko": "고마워하는", "example": "I was grateful for his help.", "youglish": "https://youglish.com/pronounce/grateful/english", "dict": "https://dictionary.cambridge.org/dictionary/english/grateful"}, {"en": "embarrassed", "ipa": "/ɪmˈbærəst/", "ko": "창피한", "example": "I felt really embarrassed when I fell over.", "youglish": "https://youglish.com/pronounce/embarrassed/english", "dict": "https://dictionary.cambridge.org/dictionary/english/embarrassed"}, {"en": "relieved", "ipa": "/rɪˈliːvd/", "ko": "안도한", "example": "I was relieved when I found my wallet.", "youglish": "https://youglish.com/pronounce/relieved/english", "dict": "https://dictionary.cambridge.org/dictionary/english/relieved"}, {"en": "unexpected", "ipa": "/ˌʌnɪkˈspektɪd/", "ko": "예상치 못한", "example": "It was a completely unexpected gift.", "youglish": "https://youglish.com/pronounce/unexpected/english", "dict": "https://dictionary.cambridge.org/dictionary/english/unexpected"}, {"en": "rewarding", "ipa": "/rɪˈwɔːdɪŋ/", "ko": "보람 있는", "example": "Volunteering is a very rewarding experience.", "youglish": "https://youglish.com/pronounce/rewarding/english", "dict": "https://dictionary.cambridge.org/dictionary/english/rewarding"}]}'::jsonb, todos = '[{"kind": "blog", "text": "어려운 큐카드 5개의 팁 펼쳐 보고, 하나 골라 2분 말하기", "url": "https://ieltsliz.com/ielts-speaking-part-2-difficult-topics", "minutes": 15}, {"kind": "listening", "text": "Listening Test 1 다시 듣기 — 스크립트를 보며 틀렸던 부분 받아쓰기", "url": "https://takeielts.britishcouncil.org/prepare-test/free-ielts-practice-tests/listening-practice-test-1", "minutes": 30}]'::jsonb where day = '2026-12-19';
update public.ielts_days set note = '{"summary": "Part 2 실전 연습이에요. 큐카드 3장을 1분 메모 → 2분 말하기로 연속해서 녹음해 보세요. 메모는 문장이 아니라 키워드로 쓰는 게 핵심이에요.", "items": [], "frame_tip": null, "extra": "*📝 1분 메모 예시* (Describe a time you helped someone)\n```\n누구/언제: old man · subway · 2 yrs ago · winter\n상황: confused · ticket machine · people walking past\n내가 한 일: bought ticket · walked to platform · 10 min\n느낌: memorable · made me realise · looking back\n```\n*✅ 녹음 듣고 체크*\n• 2분 가까이 말했나? (1분 30초 미만이면 디테일 추가)\n• 같은 단어를 반복하지 않았나? (good, nice → helpful, peaceful ...)\n• 과거 시제를 유지했나? (I go → I went)\n• 마무리 문장(Looking back / The reason I chose)이 있었나?"}'::jsonb, quiz = null, model = null, extras = null, todos = null where day = '2026-12-20';
update public.ielts_days set note = '{"summary": "GT Writing Task 1은 150단어 이상의 편지를 20분 안에 써요. 문제에 나온 bullet point 3개에 빠짐없이 답하는 게 Task Achievement의 핵심이에요. 받는 사람에 따라 격식(Dear Sir or Madam) / 반격식(Dear Mr Kim) / 비격식(Dear Tom)으로 나뉘어요.", "items": [{"en": "I am writing to complain about ~", "ko": "~에 대해 항의하려고 씁니다", "usage": "편지 첫 문장에서 목적을 밝혀요. 진행형(am writing)이 정석이에요.", "examples": [{"type": "w", "text": "I am writing to complain about the room I stayed in at your hotel last weekend."}, {"type": "w", "text": "I am writing to complain about a faulty washing machine I bought from your shop."}], "mistake": "✗ I write to complain → I am writing / ✗ complain for → about", "pron": {"word": "complain", "ipa": "/kəmˈpleɪn/", "youglish": "https://youglish.com/pronounce/I%20am%20writing%20to%20complain%20about/english", "dict": "https://dictionary.cambridge.org/dictionary/english/complain"}}, {"en": "I am writing to enquire about ~", "ko": "~에 대해 문의하려고 씁니다", "usage": "영국식 enquire, 미국식 inquire 둘 다 OK.", "examples": [{"type": "w", "text": "I am writing to enquire about the evening English courses at your college."}, {"type": "w", "text": "I am writing to enquire about the apartment advertised on your website."}], "mistake": "✗ enquire for → enquire about", "pron": {"word": "enquire", "ipa": "/ɪnˈkwaɪə(r)/", "youglish": "https://youglish.com/pronounce/I%20am%20writing%20to%20enquire%20about/english", "dict": "https://dictionary.cambridge.org/dictionary/english/enquire"}}, {"en": "I would be grateful if you could ~", "ko": "~해 주시면 감사하겠습니다", "usage": "격식 있는 요청. would와 맞춰 could를 써요.", "examples": [{"type": "w", "text": "I would be grateful if you could refund the cost of the room."}, {"type": "w", "text": "I would be grateful if you could send me more information about the fees."}], "mistake": "✗ I would be grateful if you can → could", "pron": {"word": "grateful", "ipa": "/ˈɡreɪtfl/", "youglish": "https://youglish.com/pronounce/I%20would%20be%20grateful%20if%20you%20could/english", "dict": "https://dictionary.cambridge.org/dictionary/english/grateful"}}, {"en": "I look forward to hearing from you.", "ko": "답장 기다리겠습니다", "usage": "격식 편지의 마지막 문장. to는 전치사라 뒤에 -ing가 와요.", "examples": [{"type": "w", "text": "I look forward to hearing from you soon."}, {"type": "w", "text": "I look forward to your reply."}], "mistake": "✗ I look forward to hear from you → hearing", "pron": {"word": "forward", "ipa": "/ˈfɔːwəd/", "youglish": "https://youglish.com/pronounce/I%20look%20forward%20to%20hearing%20from%20you/english", "dict": "https://dictionary.cambridge.org/dictionary/english/forward"}}, {"en": "Yours faithfully, / Yours sincerely,", "ko": "맺음말 (격식)", "usage": "Dear Sir or Madam(이름 모름)이면 Yours faithfully, Dear Mr Park(이름 앎)이면 Yours sincerely.", "examples": [{"type": "w", "text": "Dear Sir or Madam, ... Yours faithfully, Kim Minsoo"}, {"type": "w", "text": "Dear Mr Park, ... Yours sincerely, Kim Minsoo"}], "mistake": "인사말과 맺음말이 안 맞으면 감점 포인트예요.", "pron": {"word": "faithfully", "ipa": "/ˈfeɪθfəli/", "youglish": "https://youglish.com/pronounce/yours%20faithfully/english", "dict": "https://dictionary.cambridge.org/dictionary/english/faithfully"}}], "frame_tip": "첫 문장에서 편지의 목적을 밝힐 때 써요. regarding = about (격식). 예: I am writing regarding the parcel I ordered last week.", "extra": "*🧭 격식 편지 구조 (150~180단어)*\n• Dear Sir or Madam,\n• *1문단*: 목적 (I am writing to ...)\n• *2~3문단*: bullet point 3개를 하나씩 (각 2~3문장)\n• *마지막 문단*: 요청 (I would be grateful if you could ...) + I look forward to hearing from you.\n• Yours faithfully, + 이름"}'::jsonb, quiz = '[{"q": "틀린 곳 고치기: “I look forward to hear from you.”", "a": "I look forward to *hearing* from you."}, {"q": "Dear Sir or Madam으로 시작하면 맺음말은?", "a": "Yours faithfully,"}, {"q": "틀린 곳 고치기: “I would be grateful if you can help me.”", "a": "... if you *could* help me."}, {"q": "전치사: I am writing to complain ___ the noise.", "a": "about"}]'::jsonb, model = '{"text": "Dear Sir or Madam,\n\nI am writing to complain about the room I stayed in at your hotel from 5 to 7 December. I had booked a double room with a sea view, but when I arrived, I was given a small room facing the car park.\n\n(가운데 문단: bullet point 2~3에 대한 내용)\n\nI would be grateful if you could refund the difference in price between the two rooms. I look forward to hearing from you.\n\nYours faithfully,\nKim Minsoo", "why": ["첫 문단에 목적(complain) + 구체적 상황(날짜, 예약한 방 vs 받은 방)을 넣었어요.", "마지막 문단은 원하는 해결책(refund) + 정해진 맺음 문장이에요.", "Dear Sir or Madam ↔ Yours faithfully를 맞췄어요."]}'::jsonb, extras = '{"phrases": [{"en": "I was very disappointed with ~", "ko": "~에 매우 실망했습니다", "example": "I was very disappointed with the service at your restaurant.", "youglish": "https://youglish.com/pronounce/I%20was%20very%20disappointed%20with/english"}, {"en": "as soon as possible", "ko": "가능한 한 빨리", "example": "Please let me know as soon as possible.", "youglish": "https://youglish.com/pronounce/as%20soon%20as%20possible/english"}, {"en": "I have attached ~", "ko": "~을 첨부했습니다", "example": "I have attached a copy of my receipt.", "youglish": "https://youglish.com/pronounce/I%20have%20attached/english"}, {"en": "Please do not hesitate to contact me", "ko": "언제든 연락 주세요", "example": "Please do not hesitate to contact me if you need more information.", "youglish": "https://youglish.com/pronounce/Please%20do%20not%20hesitate%20to%20contact%20me/english"}, {"en": "I would appreciate it if you could ~", "ko": "~해 주시면 감사하겠습니다", "example": "I would appreciate it if you could reply by Friday.", "youglish": "https://youglish.com/pronounce/I%20would%20appreciate%20it%20if%20you%20could/english"}], "words": [{"en": "refund", "ipa": "/ˈriːfʌnd/", "ko": "환불", "example": "I would like a full refund.", "youglish": "https://youglish.com/pronounce/refund/english", "dict": "https://dictionary.cambridge.org/dictionary/english/refund"}, {"en": "inconvenience", "ipa": "/ˌɪnkənˈviːniəns/", "ko": "불편", "example": "The delay caused me a lot of inconvenience.", "youglish": "https://youglish.com/pronounce/inconvenience/english", "dict": "https://dictionary.cambridge.org/dictionary/english/inconvenience"}, {"en": "faulty", "ipa": "/ˈfɔːlti/", "ko": "결함이 있는", "example": "The kettle I bought was faulty.", "youglish": "https://youglish.com/pronounce/faulty/english", "dict": "https://dictionary.cambridge.org/dictionary/english/faulty"}, {"en": "compensation", "ipa": "/ˌkɒmpenˈseɪʃn/", "ko": "보상", "example": "I believe I am entitled to some compensation.", "youglish": "https://youglish.com/pronounce/compensation/english", "dict": "https://dictionary.cambridge.org/dictionary/english/compensation"}, {"en": "unacceptable", "ipa": "/ˌʌnəkˈseptəbl/", "ko": "용납할 수 없는", "example": "Waiting two hours for a table is unacceptable.", "youglish": "https://youglish.com/pronounce/unacceptable/english", "dict": "https://dictionary.cambridge.org/dictionary/english/unacceptable"}]}'::jsonb, todos = '[{"kind": "blog", "text": "편지 쓰기 팁 11개 섹션 읽고, 아래 모범 편지 링크에서 항의 편지 1통 읽기", "url": "https://ieltsliz.com/ielts-letter-writing-essential-tips/", "minutes": 20}]'::jsonb where day = '2026-12-21';
update public.ielts_days set note = '{"summary": "Part 3는 Part 2 주제를 사회 전체로 넓힌 토론 질문이에요. ''나''에서 ''사람들/사회''로 시점을 바꾸고, 과거·현재·미래를 비교하면 답이 깊어져요.", "items": [{"en": "I think the main reason is ...", "ko": "주된 이유는 ~ 같아요", "usage": "is 뒤에는 that절 또는 명사가 와요.", "examples": [{"type": "s", "text": "I think the main reason is that people are busier than before."}, {"type": "s", "text": "I think the main reason is the cost of housing."}], "mistake": "✗ The main reason is because → The main reason is that", "pron": {"word": "reason", "ipa": "/ˈriːzn/", "youglish": "https://youglish.com/pronounce/the%20main%20reason%20is/english", "dict": "https://dictionary.cambridge.org/dictionary/english/reason"}}, {"en": "That''s a difficult question, but ...", "ko": "어려운 질문이지만", "usage": "생각할 시간을 벌어요. 시험 내내 한두 번만 쓰세요.", "examples": [{"type": "s", "text": "That''s a difficult question, but I''d say technology has made us less patient."}, {"type": "s", "text": "That''s a difficult question, but I think both have advantages."}], "mistake": "매번 쓰면 외운 티가 나요.", "pron": {"word": null, "ipa": null, "youglish": "https://youglish.com/pronounce/that%27s%20a%20difficult%20question/english", "dict": null}}, {"en": "In the future, I expect ...", "ko": "앞으로는 ~ 것 같아요", "usage": "expect 뒤에 (that) + 주어 + will + 동사.", "examples": [{"type": "s", "text": "In the future, I expect more people will work from home."}, {"type": "s", "text": "In the future, I expect AI will do many simple jobs."}], "mistake": "✗ I expect people works → people will work", "pron": {"word": "expect", "ipa": "/ɪkˈspekt/", "youglish": "https://youglish.com/pronounce/in%20the%20future%20I%20expect/english", "dict": "https://dictionary.cambridge.org/dictionary/english/expect"}}, {"en": "It''s probably because ...", "ko": "아마 ~ 때문일 거예요", "usage": "확신이 없을 때 부드럽게 이유를 말해요.", "examples": [{"type": "s", "text": "It''s probably because young people use their phones more."}, {"type": "s", "text": "It''s probably because life in cities is so expensive."}], "mistake": "probably 위치: be동사 뒤 / 일반동사 앞", "pron": {"word": "probably", "ipa": "/ˈprɒbəbli/", "youglish": "https://youglish.com/pronounce/it%27s%20probably%20because/english", "dict": "https://dictionary.cambridge.org/dictionary/english/probably"}}, {"en": "compared to the past", "ko": "과거에 비해", "usage": "Compared to / with + 명사. 문장 앞에 쓰면 쉼표를 찍어요.", "examples": [{"type": "s", "text": "Compared to the past, people travel abroad much more."}, {"type": "w", "text": "Compared to the past, families today are much smaller."}], "mistake": "✗ Compare to the past → Compared to the past", "pron": {"word": "compared", "ipa": "/kəmˈpeəd/", "youglish": "https://youglish.com/pronounce/compared%20to%20the%20past/english", "dict": "https://dictionary.cambridge.org/dictionary/english/compared"}}], "frame_tip": "과거와 현재를 대조할 때 써요. whereas = 반면에 (while로 바꿔도 돼요).", "extra": null}'::jsonb, quiz = '[{"q": "틀린 곳 고치기: “The main reason is because people are busy.”", "a": "The main reason is *that* people are busy."}, {"q": "형태: ______ to the past, prices are much higher. (compare)", "a": "Compared"}, {"q": "In the past people wrote letters, ______ nowadays they send messages.", "a": "whereas"}, {"q": "틀린 곳 고치기: “In the future, I expect people works from home.”", "a": "... people *will work* from home."}]'::jsonb, model = '{"text": "Q: How has technology changed the way people communicate?\nA: That''s a difficult question, but I''d say technology has made communication much faster. In the past, people wrote letters or made phone calls, whereas nowadays we send messages instantly, even to people on the other side of the world. However, I think face-to-face conversations have become less common. It''s probably because people find it easier to text than to talk. In the future, I expect video calls will become even more important, especially for work.", "why": ["과거(In the past) → 현재(nowadays) → 미래(In the future)로 시점을 옮기며 답했어요.", "변화 → 단점 → 이유 → 전망으로 1분 분량이에요.", "I가 아니라 people / we 시점으로 사회 전체를 이야기했어요."]}'::jsonb, extras = '{"phrases": [{"en": "on the whole,", "ko": "대체로", "example": "On the whole, I think people are happier now.", "youglish": "https://youglish.com/pronounce/on%20the%20whole/english"}, {"en": "it''s hard to say, but ~", "ko": "단정하긴 어렵지만", "example": "It''s hard to say, but I think prices will keep rising.", "youglish": "https://youglish.com/pronounce/it%27s%20hard%20to%20say%20but/english"}, {"en": "there are pros and cons", "ko": "장단점이 있어요", "example": "There are pros and cons to living in a big city.", "youglish": "https://youglish.com/pronounce/there%20are%20pros%20and%20cons/english"}, {"en": "as far as I know,", "ko": "내가 아는 한", "example": "As far as I know, most schools teach English from age eight.", "youglish": "https://youglish.com/pronounce/as%20far%20as%20I%20know/english"}, {"en": "from my point of view,", "ko": "내 관점에서는", "example": "From my point of view, families are less close than before.", "youglish": "https://youglish.com/pronounce/from%20my%20point%20of%20view/english"}], "words": [{"en": "generation", "ipa": "/ˌdʒenəˈreɪʃn/", "ko": "세대", "example": "The older generation prefers phone calls.", "youglish": "https://youglish.com/pronounce/generation/english", "dict": "https://dictionary.cambridge.org/dictionary/english/generation"}, {"en": "tendency", "ipa": "/ˈtendənsi/", "ko": "경향", "example": "There is a tendency for young people to marry later.", "youglish": "https://youglish.com/pronounce/tendency/english", "dict": "https://dictionary.cambridge.org/dictionary/english/tendency"}, {"en": "inevitable", "ipa": "/ɪnˈevɪtəbl/", "ko": "피할 수 없는", "example": "Some change is inevitable.", "youglish": "https://youglish.com/pronounce/inevitable/english", "dict": "https://dictionary.cambridge.org/dictionary/english/inevitable"}, {"en": "trend", "ipa": "/trend/", "ko": "추세, 유행", "example": "Working from home is a growing trend.", "youglish": "https://youglish.com/pronounce/trend/english", "dict": "https://dictionary.cambridge.org/dictionary/english/trend"}, {"en": "perspective", "ipa": "/pəˈspektɪv/", "ko": "관점", "example": "Travel gives you a different perspective on life.", "youglish": "https://youglish.com/pronounce/perspective/english", "dict": "https://dictionary.cambridge.org/dictionary/english/perspective"}]}'::jsonb, todos = '[{"kind": "blog", "text": "Speaking 허브의 모범 답안 목록에서 Part 3 답안 1개 읽기 (환경·기술 중)", "url": "https://ieltsliz.com/ielts-speaking-free-lessons-essential-tips/", "minutes": 10}]'::jsonb where day = '2026-12-22';
update public.ielts_days set note = '{"summary": "친구에게 쓰는 비격식 편지는 축약형(I''m, don''t)과 구어 표현을 써도 돼요. 오히려 너무 딱딱하면 ''어조(tone)''에서 감점돼요. 구조는 인사 → 목적 → bullet point 3개 → 마무리예요.", "items": [{"en": "It was great to hear from you.", "ko": "소식 들어서 반가웠어", "usage": "친구 편지의 첫 줄. Thanks for your letter.도 좋아요.", "examples": [{"type": "w", "text": "Dear Tom, It was great to hear from you!"}, {"type": "w", "text": "Thanks for your letter. It was great to hear your news."}], "mistake": "친구에게 I am writing to inform you는 너무 격식 있어요.", "pron": {"word": null, "ipa": null, "youglish": "https://youglish.com/pronounce/it%20was%20great%20to%20hear%20from%20you/english", "dict": null}}, {"en": "I''m writing to let you know that ~", "ko": "~를 알려주려고 편지 써", "usage": "let + 사람 + know (to 없이).", "examples": [{"type": "w", "text": "I''m writing to let you know that I''ve moved to a new flat."}, {"type": "w", "text": "I''m writing to let you know that I can''t come to your party."}], "mistake": "✗ let you to know → let you know", "pron": {"word": null, "ipa": null, "youglish": "https://youglish.com/pronounce/let%20you%20know%20that/english", "dict": null}}, {"en": "Would you like to ~?", "ko": "~할래?", "usage": "초대·제안. Would you like to + 동사원형.", "examples": [{"type": "w", "text": "Would you like to come over for dinner next Saturday?"}, {"type": "w", "text": "Would you like to join us on the trip?"}], "mistake": "✗ Would you like come → to come", "pron": {"word": null, "ipa": null, "youglish": "https://youglish.com/pronounce/would%20you%20like%20to%20come/english", "dict": null}}, {"en": "Sorry I couldn''t ~", "ko": "~ 못해서 미안해", "usage": "make it = (모임에) 가다, 참석하다.", "examples": [{"type": "w", "text": "Sorry I couldn''t reply sooner; I''ve been really busy with work."}, {"type": "w", "text": "Sorry I couldn''t make it to your wedding."}], "mistake": "make it을 알아두면 편지·말하기 모두에 유용해요.", "pron": {"word": null, "ipa": null, "youglish": "https://youglish.com/pronounce/sorry%20I%20couldn%27t%20make%20it/english", "dict": null}}, {"en": "Hope to see you soon. / Best wishes,", "ko": "곧 보자 / 안부를 전하며", "usage": "친구 편지 맺음: Best wishes, / Take care, / Love, (가까운 사이).", "examples": [{"type": "w", "text": "Hope to see you soon. Best wishes, Minsoo"}, {"type": "w", "text": "Can''t wait to see you! Love, Minsoo"}], "mistake": "친구에게 ✗ Yours faithfully", "pron": {"word": null, "ipa": null, "youglish": "https://youglish.com/pronounce/hope%20to%20see%20you%20soon/english", "dict": null}}], "frame_tip": "편지의 목적을 밝히는 비격식 버전이에요. 격식 편지의 I am writing to inform you that ...과 비교해서 기억하세요.", "extra": "*🧭 비격식 편지 구조 (150~180단어)*\n• Dear Jenny,\n• *1문단*: 안부 (It was great to hear from you!) + 목적 (I''m writing to let you know ...)\n• *2~3문단*: bullet point 3개 (축약형 OK: I''m, it''s, don''t)\n• *마지막*: Hope to see you soon! / Best wishes, + 이름"}'::jsonb, quiz = '[{"q": "친구 편지 맺음말로 어색한 것: Best wishes / Yours faithfully / Take care", "a": "Yours faithfully"}, {"q": "틀린 곳 고치기: “Would you like come to my party?”", "a": "Would you like *to come* ...?"}, {"q": "Sorry I couldn''t make ___ to your birthday.", "a": "it"}, {"q": "친구에게 맞게 바꾸기: “I am writing to inform you that I have moved.”", "a": "*I''m writing to let you know that I''ve* moved."}]'::jsonb, model = '{"text": "Dear Jenny,\n\nIt was great to hear from you, and I''m glad your new job is going well!\n\nI''m writing to let you know that I''ve finally moved into my new apartment, and I''m having a small housewarming party. Would you like to come? It''s on Saturday 10 January, from 6 p.m. The address is 25 Hangang-ro, Apartment 1203. It''s only five minutes from Yongsan Station, so it''s easy to find.\n\nI''m going to cook some Korean food, like bulgogi and japchae, so you don''t need to bring anything to eat. But if you like, you could bring a dessert or something to drink. Also, feel free to bring your boyfriend. I''d love to meet him!\n\nPlease let me know by Wednesday if you can come, so I know how much food to prepare.\n\nHope to see you soon!\n\nBest wishes,\nMinsoo", "why": ["bullet point(날짜·장소, 음식, 가져올 것)를 문단마다 하나씩 다뤘어요.", "축약형과 느낌표로 친근한 어조를 유지했어요.", "약 160단어, 20분 안에 쓸 수 있는 분량이에요."]}'::jsonb, extras = '{"phrases": [{"en": "How are things with you?", "ko": "요즘 어떻게 지내?", "example": "How are things with you? I hope work isn''t too busy.", "youglish": "https://youglish.com/pronounce/How%20are%20things%20with%20you/english"}, {"en": "I can''t wait to ~", "ko": "빨리 ~하고 싶어", "example": "I can''t wait to see you!", "youglish": "https://youglish.com/pronounce/I%20can%27t%20wait%20to/english"}, {"en": "Let me know if ~", "ko": "~하면 알려줘", "example": "Let me know if you can come.", "youglish": "https://youglish.com/pronounce/Let%20me%20know%20if/english"}, {"en": "Guess what?", "ko": "있잖아, 그거 알아?", "example": "Guess what? I''ve got a new job!", "youglish": "https://youglish.com/pronounce/Guess%20what/english"}, {"en": "It would be great if you could ~", "ko": "~해 주면 정말 좋겠어", "example": "It would be great if you could help me move.", "youglish": "https://youglish.com/pronounce/It%20would%20be%20great%20if%20you%20could/english"}], "words": [{"en": "housewarming", "ipa": "/ˈhaʊswɔːmɪŋ/", "ko": "집들이", "example": "I''m having a housewarming party next week.", "youglish": "https://youglish.com/pronounce/housewarming/english", "dict": "https://dictionary.cambridge.org/dictionary/english/housewarming"}, {"en": "catch up", "ipa": "/kætʃ ʌp/", "ko": "(근황을) 나누다, 밀린 얘기를 하다", "example": "Let''s meet for coffee and catch up.", "youglish": "https://youglish.com/pronounce/catch%20up/english", "dict": "https://dictionary.cambridge.org/dictionary/english/catch-up"}, {"en": "invitation", "ipa": "/ˌɪnvɪˈteɪʃn/", "ko": "초대", "example": "Thanks for the invitation.", "youglish": "https://youglish.com/pronounce/invitation/english", "dict": "https://dictionary.cambridge.org/dictionary/english/invitation"}, {"en": "celebrate", "ipa": "/ˈselɪbreɪt/", "ko": "축하하다", "example": "We''re going out to celebrate my birthday.", "youglish": "https://youglish.com/pronounce/celebrate/english", "dict": "https://dictionary.cambridge.org/dictionary/english/celebrate"}, {"en": "directions", "ipa": "/dəˈrekʃnz/", "ko": "길 안내", "example": "I''ve sent you directions to my new place.", "youglish": "https://youglish.com/pronounce/directions/english", "dict": "https://dictionary.cambridge.org/dictionary/english/directions"}]}'::jsonb, todos = '[{"kind": "blog", "text": "편지 페이지의 모범 편지 링크에서 친구에게 쓰는 편지 1통 읽기", "url": "https://ieltsliz.com/ielts-letter-writing-essential-tips/", "minutes": 10}]'::jsonb where day = '2026-12-23';
update public.ielts_days set note = '{"summary": "도시 문제(교통 체증·집값·생활비)는 Task 2 ''문제-해결'' 유형 단골이에요. GT 편지 주제(이웃 소음, 이사)와도 겹쳐서 활용도가 높아요.", "items": [{"en": "traffic congestion", "ko": "교통 체증", "usage": "셀 수 없는 명사. 구어에선 traffic jam(셀 수 있음)을 많이 써요.", "examples": [{"type": "w", "text": "Traffic congestion is a serious problem in most large cities."}, {"type": "s", "text": "The traffic in Seoul is terrible during rush hour."}], "mistake": "✗ traffic congestions / ✗ many traffic congestions", "pron": {"word": "congestion", "ipa": "/kənˈdʒestʃən/", "youglish": "https://youglish.com/pronounce/traffic%20congestion/english", "dict": "https://dictionary.cambridge.org/dictionary/english/congestion"}}, {"en": "commute to work", "ko": "통근하다", "usage": "commute는 동사·명사 둘 다 돼요 (my commute = 내 통근길).", "examples": [{"type": "w", "text": "Many people spend two hours a day commuting to work."}, {"type": "s", "text": "I commute to work by subway; it takes about 40 minutes."}], "mistake": "✗ commute my work → commute to work", "pron": {"word": "commute", "ipa": "/kəˈmjuːt/", "youglish": "https://youglish.com/pronounce/commute%20to%20work/english", "dict": "https://dictionary.cambridge.org/dictionary/english/commute"}}, {"en": "the cost of living", "ko": "생활비, 물가", "usage": "the를 붙여 고정 표현으로 써요.", "examples": [{"type": "w", "text": "The cost of living in capital cities has risen sharply."}, {"type": "s", "text": "The cost of living in Seoul is really high."}], "mistake": "living cost보다 the cost of living이 자연스러워요.", "pron": {"word": null, "ipa": null, "youglish": "https://youglish.com/pronounce/the%20cost%20of%20living/english", "dict": null}}, {"en": "affordable housing", "ko": "저렴한 주택", "usage": "housing은 셀 수 없는 명사(주택 전반). affordable = 감당할 수 있는 가격의.", "examples": [{"type": "w", "text": "The government should build more affordable housing for young people."}, {"type": "s", "text": "It''s really hard to find affordable housing near my office."}], "mistake": "✗ affordable housings", "pron": {"word": "affordable", "ipa": "/əˈfɔːdəbl/", "youglish": "https://youglish.com/pronounce/affordable%20housing/english", "dict": "https://dictionary.cambridge.org/dictionary/english/affordable"}}, {"en": "urban / rural areas", "ko": "도시 / 시골 지역", "usage": "rural 발음이 어려워요. 천천히 /ˈrʊərəl/.", "examples": [{"type": "w", "text": "Young people are moving from rural areas to urban areas to find work."}, {"type": "s", "text": "I grew up in a rural area, so city life was a big change for me."}], "mistake": "발음: rural /ˈrʊərəl/ (루어럴)", "pron": {"word": "rural", "ipa": "/ˈrʊərəl/", "youglish": "https://youglish.com/pronounce/rural%20areas/english", "dict": "https://dictionary.cambridge.org/dictionary/english/rural"}}], "frame_tip": "해결 방법을 제시할 때 써요. by 뒤에는 명사나 -ing가 와요.", "extra": null}'::jsonb, quiz = '[{"q": "틀린 곳 고치기: “This problem can be solved by build more roads.”", "a": "... by *building* more roads."}, {"q": "The ______ of living in Seoul is very high.", "a": "cost"}, {"q": "틀린 곳 고치기: “There are many traffic congestions in my city.”", "a": "There is *a lot of traffic congestion* in my city."}, {"q": "I ______ to work by bus every day. (통근하다)", "a": "commute"}]'::jsonb, model = '{"text": "One of the main causes of traffic congestion is that too many people commute to work by car. This problem can be solved by improving public transport and making it cheaper, so that more people leave their cars at home.", "why": ["원인(One of the main causes) + 해결(can be solved by) + 결과(so that) 구조예요.", "2주차 환경 표현(public transport)을 재활용했어요.", "Task 2 본론 한 문단의 뼈대로 그대로 쓸 수 있어요."]}'::jsonb, extras = '{"phrases": [{"en": "rush hour", "ko": "출퇴근 시간대", "example": "The subway is packed during rush hour.", "youglish": "https://youglish.com/pronounce/rush%20hour/english"}, {"en": "get stuck in traffic", "ko": "차가 막혀 꼼짝 못 하다", "example": "I got stuck in traffic for an hour.", "youglish": "https://youglish.com/pronounce/get%20stuck%20in%20traffic/english"}, {"en": "move to the city", "ko": "도시로 이사하다", "example": "Many young people move to the city for work.", "youglish": "https://youglish.com/pronounce/move%20to%20the%20city/english"}, {"en": "a sense of community", "ko": "공동체 의식", "example": "Small towns often have a strong sense of community.", "youglish": "https://youglish.com/pronounce/a%20sense%20of%20community/english"}, {"en": "the pace of life", "ko": "생활 속도", "example": "The pace of life in Seoul is very fast.", "youglish": "https://youglish.com/pronounce/the%20pace%20of%20life/english"}], "words": [{"en": "overcrowded", "ipa": "/ˌəʊvəˈkraʊdɪd/", "ko": "과밀한", "example": "Big cities are becoming overcrowded.", "youglish": "https://youglish.com/pronounce/overcrowded/english", "dict": "https://dictionary.cambridge.org/dictionary/english/overcrowded"}, {"en": "pedestrian", "ipa": "/pəˈdestriən/", "ko": "보행자", "example": "The city centre should be for pedestrians only.", "youglish": "https://youglish.com/pronounce/pedestrian/english", "dict": "https://dictionary.cambridge.org/dictionary/english/pedestrian"}, {"en": "residential", "ipa": "/ˌrezɪˈdenʃl/", "ko": "주거의", "example": "I live in a quiet residential area.", "youglish": "https://youglish.com/pronounce/residential/english", "dict": "https://dictionary.cambridge.org/dictionary/english/residential"}, {"en": "rent", "ipa": "/rent/", "ko": "집세; 세 들다", "example": "Rent in the city centre is very expensive.", "youglish": "https://youglish.com/pronounce/rent/english", "dict": "https://dictionary.cambridge.org/dictionary/english/rent"}, {"en": "outskirts", "ipa": "/ˈaʊtskɜːts/", "ko": "변두리, 외곽", "example": "We live on the outskirts of the city.", "youglish": "https://youglish.com/pronounce/outskirts/english", "dict": "https://dictionary.cambridge.org/dictionary/english/outskirts"}]}'::jsonb, todos = '[{"kind": "blog", "text": "도시 페이지의 Task 2 문제 5개 중 하나 골라 개요만 짜기", "url": "https://ieltsliz.com/ielts-topic-urban-planning-design/", "minutes": 10}]'::jsonb where day = '2026-12-24';
update public.ielts_days set note = '{"summary": "실전처럼 Writing 60분을 써 봐요. Task 1(편지)은 20분, Task 2(에세이)는 40분이에요. Task 2가 점수 비중이 더 크니 Task 1에서 시간을 넘기지 마세요.", "items": [], "frame_tip": null, "extra": "*📝 오늘의 실전 문제*\n\n*Task 1 (20분, 150단어 이상)*\nYou recently bought a laptop online, but it arrived damaged. Write a letter to the company. In your letter:\n• describe what you bought\n• explain the problem\n• say what you would like the company to do\n\n*Task 2 (40분, 250단어 이상)*\nSome people think that the best way to improve public health is to build more sports facilities. Others think that other measures are needed. Discuss both views and give your own opinion.\n\n*⏱ 시간 배분*\n• Task 1: 계획 3분 → 쓰기 15분 → 검토 2분\n• Task 2: 계획 5분 → 쓰기 30분 → 검토 5분\n• 끝나고 막힌 표현을 메모해 두세요 (내일 채우기 재료)"}'::jsonb, quiz = null, model = '{"text": "[Task 1 모범 답안]\n\nDear Sir or Madam,\n\nI am writing to complain about a laptop I ordered from your website on 15 December (order number 48213). It was a silver 14-inch model, and I paid for express delivery because I needed it for work.\n\nUnfortunately, when the parcel arrived, the box was badly damaged, and the laptop screen had a large crack across it. As a result, I cannot use the laptop at all. I have attached some photos of the damage to this letter.\n\nI would be grateful if you could send me a replacement as soon as possible. If this is not possible, I would like a full refund, including the delivery charge. I would also appreciate it if you could arrange for the damaged laptop to be collected from my address.\n\nI look forward to hearing from you.\n\nYours faithfully,\nKim Minsoo\n\n[Task 2 뼈대]\n서론: Some people believe that ..., while others argue that ... + 내 입장\n본론 1: 시설 찬성 — 접근성, 운동 습관 (take regular exercise)\n본론 2: 다른 방법 — junk food 광고 제한, 학교 교육 (lead a healthy lifestyle)\n결론: In conclusion, although ..., I believe that ...", "why": ["Task 1은 bullet point 3개를 문단마다 하나씩 다뤘어요 (약 170단어).", "Task 2는 3주차 건강 표현이 그대로 쓰이는 문제예요.", "실전에서 막힌 표현은 내일(12/26) 표현 칸에 직접 채워 넣으세요."]}'::jsonb, extras = null, todos = null where day = '2026-12-25';
update public.ielts_days set note = '{"summary": "어제 모의고사에서 막힌 표현을 내 것으로 만드는 날이에요. ''틀린 문장 → 고친 문장 → 규칙'' 3줄로 정리하면 시험 전까지 반복해서 볼 수 있어요.", "items": [], "frame_tip": null, "extra": "*📒 오류 노트 쓰는 법*\n```\n✗ I am writing to complain the laptop.\n✓ I am writing to complain about the laptop.\n규칙: complain about + 명사\n```\n• 어제 쓴 글에서 오류 5개를 골라 위 형식으로 적어요\n• Supabase `ielts_days` 테이블의 12/26 행 `expressions` 칸에 넣으면 이후 복습 메시지에 나와요\n   형식: `[{\"en\": \"complain about ~\", \"ko\": \"~에 대해 항의하다\"}]`\n• Liz의 Task 2 주제별 질문 목록에서 약한 주제를 하나 골라 개요만 짜 보세요"}'::jsonb, quiz = null, model = null, extras = null, todos = '[{"kind": "blog", "text": "Task 2 주제별 질문 목록(100개 이상)을 훑고, 약한 주제 1개 골라 개요 짜기", "url": "https://ieltsliz.com/ielts-writing-task-2/", "minutes": 15}]'::jsonb where day = '2026-12-26';
update public.ielts_days set note = '{"summary": "Speaking 실전 10분 연습이에요. Part 1 질문 6개 → Part 2 큐카드 1장을 쉬지 않고 이어서 녹음하세요.", "items": [], "frame_tip": null, "extra": "*🎤 오늘의 실전 순서*\n*Part 1 (4~5분)*\n1. Do you work or study?\n2. Do you like your hometown? Why?\n3. What do you do in your free time?\n4. How often do you use your phone?\n5. Do you prefer eating out or cooking at home?\n6. How do you usually get the news?\n\n*Part 2 (1분 준비 + 2분)*\nDescribe a skill you would like to learn. You should say: what it is / why you want to learn it / how you would learn it / and explain how it would help you.\n\n*✅ 녹음 듣고 체크*: 답마다 이유가 하나 있었나? · 2분을 채웠나? · used to, I''d say 같은 표현을 썼나?"}'::jsonb, quiz = null, model = null, extras = null, todos = '[{"kind": "mock", "text": "British Council 공식 모의시험(Familiarisation Test, General Training): Listening + Reading 실전. 두 영역 결과는 무료로 확인돼요", "url": "https://takeielts.britishcouncil.org/prepare/ielts-free-practice-mock-tests/ielts-familiarisation-test", "minutes": 100}]'::jsonb where day = '2026-12-27';
update public.ielts_days set note = '{"summary": "1주차 (교육·일·연결어) 표현을 다시 꺼내 보는 날이에요. 새 표현은 없어요.", "items": [], "frame_tip": null, "extra": "*🔁 최종 복습 방법*\n• 아래 복습 목록의 영어 표현을 보고 한국어 뜻을 먼저 떠올리세요\n• 그다음 ''복습 뜻 보기''로 확인 → 못 떠올린 표현만 메모\n• 메모한 표현으로 문장을 하나씩 소리 내 말해 보세요"}'::jsonb, quiz = null, model = null, extras = null, todos = null where day = '2026-12-28';
update public.ielts_days set note = '{"summary": "2주차 (기술·환경·바꿔 말하기) 표현을 다시 꺼내 보는 날이에요. 새 표현은 없어요.", "items": [], "frame_tip": null, "extra": "*🔁 최종 복습 방법*\n• 아래 복습 목록의 영어 표현을 보고 한국어 뜻을 먼저 떠올리세요\n• 그다음 ''복습 뜻 보기''로 확인 → 못 떠올린 표현만 메모\n• 메모한 표현으로 문장을 하나씩 소리 내 말해 보세요"}'::jsonb, quiz = null, model = null, extras = null, todos = null where day = '2026-12-29';
update public.ielts_days set note = '{"summary": "3주차 (범죄·정부·건강·광고·미디어) 표현을 다시 꺼내 보는 날이에요. 새 표현은 없어요.", "items": [], "frame_tip": null, "extra": "*🔁 최종 복습 방법*\n• 아래 복습 목록의 영어 표현을 보고 한국어 뜻을 먼저 떠올리세요\n• 그다음 ''복습 뜻 보기''로 확인 → 못 떠올린 표현만 메모\n• 메모한 표현으로 문장을 하나씩 소리 내 말해 보세요"}'::jsonb, quiz = null, model = null, extras = null, todos = '[{"kind": "listening", "text": "Listening Test 2 다시 듣기 — 스크립트 보며 따라 말하기 (감 유지)", "url": "https://takeielts.britishcouncil.org/take-ielts/prepare/free-ielts-english-practice-tests/listening-2/section-1", "minutes": 30}]'::jsonb where day = '2026-12-30';
update public.ielts_days set note = '{"summary": "4주차 (Speaking) 표현을 다시 꺼내 보는 날이에요. 새 표현은 없어요.", "items": [], "frame_tip": null, "extra": "*🔁 최종 복습 방법*\n• 아래 복습 목록의 영어 표현을 보고 한국어 뜻을 먼저 떠올리세요\n• 그다음 ''복습 뜻 보기''로 확인 → 못 떠올린 표현만 메모\n• 메모한 표현으로 문장을 하나씩 소리 내 말해 보세요"}'::jsonb, quiz = null, model = null, extras = null, todos = null where day = '2026-12-31';
update public.ielts_days set note = '{"summary": "그동안 배운 문장 틀을 한 번에 보는 날이에요. 시험장에서 바로 꺼내 쓸 수 있게 소리 내 읽어 보세요.", "items": [], "frame_tip": null, "extra": "*✍️ Writing 문장 틀*\n• Some people believe that ..., while others argue that ...\n• It is often argued that ...\n• Although ..., I believe that ...\n• In my opinion, ... because ...\n• One advantage / disadvantage of ... is that ...\n• One of the main causes of ... is ...\n• One possible solution to this problem is to ...\n• This problem can be solved by ...\n• Instead of ..., governments should ...\n• ... can be detrimental to ...\n• In conclusion, ...\n\n*✉️ 편지*\n• I am writing to complain about / enquire about ...\n• I would be grateful if you could ...\n• I look forward to hearing from you. → Yours faithfully / sincerely\n• I''m writing to let you know that ... → Best wishes\n\n*🗣 Speaking*\n• To be honest, ... / Actually, ...\n• I''d say ..., mainly because ...\n• It depends on ... For example, ...\n• I used to ..., but now ...\n• I''d like to talk about ... The reason I chose ... is ...\n• Looking back, I think ...\n• In the past ..., whereas nowadays ..."}'::jsonb, quiz = null, model = null, extras = null, todos = null where day = '2027-01-01';
update public.ielts_days set note = '{"summary": "내일이 시험이에요. 새로 외우지 말고 컨디션을 챙기세요. 지금까지 40일 동안 쌓은 표현이면 충분해요.", "items": [], "frame_tip": null, "extra": "*✅ 시험 전날 체크*\n• 준비물·입실 시간은 접수 확인 메일 기준으로 다시 확인 (신분증은 접수할 때 쓴 것과 같은 것)\n• 시험장까지 가는 길과 걸리는 시간 확인\n\n*🧠 시험장에서 기억할 3가지*\n• Writing: Task 1은 20분에서 끊기. bullet point 3개 모두 답하기\n• Speaking: 답마다 이유 하나. 모르는 질문엔 I''ve never really thought about it, but ...\n• Listening·Reading: 한 문제에 오래 머물지 말고 넘어가기\n\n오늘은 문장 틀만 한 번 훑고 일찍 자요. 화이팅! 💪"}'::jsonb, quiz = null, model = null, extras = null, todos = '[{"kind": "blog", "text": "시험 당일 팁 페이지에서 ''On the Day'' 섹션(준비물·시간)만 읽기", "url": "https://ieltsliz.com/ielts-exam-tips-on-the-day/", "minutes": 10}]'::jsonb where day = '2027-01-02';
